{
  "name": "Vayu Code IDE",
  "description": "A cloud-native browser IDE for design software development with glassmorphism UI, powered by Puter.js and multi-model AI integration.",
  "requestFramePermissions": [
    "camera",
    "microphone"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum AIModel {
  GEMINI = 'gemini-2.0-flash',
  GPT4 = 'gpt-4o',
  CLAUDE = 'claude-3.5-sonnet',
  DEEPSEEK = 'deepseek-v2',
  LLAMA = 'llama-3.1-70b'
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: AIModel;
  timestamp: number;
}

export interface FileEntry {
  name: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
  }
}

import React, { useState, useEffect, useCallback, useRef } from 'react';
import Editor from '@monaco-editor/react';
import { Sidebar } from './components/Sidebar';
import { Preview } from './components/Preview';
import { Header } from './components/Header';
import { AIModel, ChatMessage, FileEntry } from './types';

const DEFAULT_CODE = `<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { background: #0f172a; display: flex; align-items: center; justify-content: center; min-height: 100vh; margin: 0; color: white; font-family: sans-serif; }
    .glass {
      background: rgba(255, 255, 255, 0.1);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255, 255, 255, 0.2);
      padding: 2rem;
      border-radius: 1.5rem;
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
  </style>
</head>
<body>
  <div class="glass text-center">
    <h1 class="text-4xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500">
      Vayu Code
    </h1>
    <p class="text-slate-300">Start building something futuristic.</p>
    <div class="mt-6 animate-bounce">
      <svg class="w-8 h-8 mx-auto text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 14l-7 7m0 0l-7-7m7 7V3"></path>
      </svg>
    </div>
  </div>
</body>
</html>`;

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_CODE);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [isPuterReady, setIsPuterReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    if (window.puter) {
      window.puter.ready().then(() => {
        setIsPuterReady(true);
      });
    }
  }, []);

  const handleEditorChange = (value: string | undefined) => {
    if (value !== undefined) setCode(value);
  };

  const handleSendMessage = async (prompt: string) => {
    if (!isPuterReady || !prompt.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMsg]);
    setIsGenerating(true);

    try {
      const response = await window.puter.ai.chat(prompt, { model: activeModel });
      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.toString(),
        model: activeModel,
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, assistantMsg]);

      // Simple heuristic to extract code blocks
      const codeMatch = assistantMsg.content.match(/```(?:html|javascript|css)?([\s\S]*?)```/);
      if (codeMatch && codeMatch[1]) {
        setCode(codeMatch[1].trim());
      }
    } catch (error) {
      console.error('AI error:', error);
      const errorMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "Sorry, I encountered an error processing your request.",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#020617] text-slate-100 overflow-hidden">
      {/* Background Gradients */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none opacity-20">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-600 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600 blur-[120px] rounded-full"></div>
      </div>

      <Sidebar 
        isOpen={isSidebarOpen} 
        messages={messages} 
        onSendMessage={handleSendMessage}
        isGenerating={isGenerating}
        activeModel={activeModel}
        onModelChange={setActiveModel}
      />

      <div className="flex-1 flex flex-col min-w-0 relative z-10">
        <Header 
          activeModel={activeModel} 
          onModelChange={setActiveModel}
          onToggleSidebar={() => setSidebarOpen(!isSidebarOpen)}
          isSidebarOpen={isSidebarOpen}
        />

        <main className="flex-1 flex overflow-hidden p-4 gap-4">
          <div className="flex-1 flex flex-col bg-white/5 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-2xl overflow-hidden ring-1 ring-white/10">
            <div className="px-4 py-2 bg-white/5 border-b border-white/5 flex items-center justify-between">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Editor — index.html</span>
              <div className="flex gap-1.5">
                <div className="w-2.5 h-2.5 rounded-full bg-red-500/50"></div>
                <div className="w-2.5 h-2.5 rounded-full bg-yellow-500/50"></div>
                <div className="w-2.5 h-2.5 rounded-full bg-green-500/50"></div>
              </div>
            </div>
            <div className="flex-1 relative">
              <Editor
                height="100%"
                defaultLanguage="html"
                theme="vs-dark"
                value={code}
                onChange={handleEditorChange}
                options={{
                  minimap: { enabled: false },
                  fontSize: 14,
                  padding: { top: 16 },
                  scrollBeyondLastLine: false,
                  backgroundColor: 'transparent' as any,
                  fontFamily: "'Fira Code', 'Cascadia Code', monospace",
                  smoothScrolling: true,
                  cursorBlinking: "phase",
                  scrollbar: {
                    vertical: 'hidden',
                    horizontal: 'hidden'
                  }
                }}
              />
            </div>
          </div>

          <div className="flex-1 bg-neutral-900/40 backdrop-blur-md rounded-2xl border border-white/10 shadow-2xl overflow-hidden flex flex-col">
            <div className="px-4 py-2 bg-white/5 border-b border-white/5">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Live Preview</span>
            </div>
            <div className="flex-1 bg-white">
              <Preview code={code} />
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

import React from 'react';
import { AIModel } from '../types';

interface HeaderProps {
  activeModel: AIModel;
  onModelChange: (model: AIModel) => void;
  onToggleSidebar: () => void;
  isSidebarOpen: boolean;
}

export const Header: React.FC<HeaderProps> = ({ 
  activeModel, 
  onModelChange, 
  onToggleSidebar,
  isSidebarOpen
}) => {
  return (
    <header className="h-16 px-6 flex items-center justify-between border-b border-white/10 backdrop-blur-xl bg-white/5 relative z-20">
      <div className="flex items-center gap-4">
        <button 
          onClick={onToggleSidebar}
          className="p-2 hover:bg-white/10 rounded-lg transition-colors text-slate-400 hover:text-white"
        >
          <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d={isSidebarOpen ? "M4 6h16M4 12h16m-7 6h7" : "M4 6h16M4 12h16M4 18h16"} />
          </svg>
        </button>
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 rounded-lg bg-gradient-to-tr from-blue-600 to-purple-600 flex items-center justify-center shadow-lg shadow-blue-500/20">
            <span className="font-bold text-white text-sm">V</span>
          </div>
          <h1 className="font-bold text-xl tracking-tight bg-clip-text text-transparent bg-gradient-to-r from-white to-slate-400">
            Vayu Code
          </h1>
        </div>
      </div>

      <div className="flex items-center gap-4">
        <div className="flex items-center gap-2 bg-white/5 border border-white/10 rounded-xl px-2 py-1">
          <span className="text-[10px] font-bold uppercase text-slate-500 pl-2">Engine</span>
          <select 
            value={activeModel}
            onChange={(e) => onModelChange(e.target.value as AIModel)}
            className="bg-transparent text-sm font-medium text-slate-200 outline-none cursor-pointer py-1.5 px-2 hover:text-white"
          >
            <option value={AIModel.GEMINI} className="bg-slate-900">Gemini 2.0</option>
            <option value={AIModel.GPT4} className="bg-slate-900">GPT-4o</option>
            <option value={AIModel.CLAUDE} className="bg-slate-900">Claude 3.5</option>
            <option value={AIModel.DEEPSEEK} className="bg-slate-900">DeepSeek v2</option>
            <option value={AIModel.LLAMA} className="bg-slate-900">Llama 3.1</option>
          </select>
        </div>

        <button className="flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 rounded-xl transition-all font-medium text-sm shadow-lg shadow-blue-500/20">
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 4v16m8-8H4" />
          </svg>
          Deploy
        </button>
      </div>
    </header>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { ChatMessage, AIModel } from '../types';

interface SidebarProps {
  isOpen: boolean;
  messages: ChatMessage[];
  onSendMessage: (msg: string) => void;
  isGenerating: boolean;
  activeModel: AIModel;
  onModelChange: (model: AIModel) => void;
}

export const Sidebar: React.FC<SidebarProps> = ({ 
  isOpen, 
  messages, 
  onSendMessage, 
  isGenerating,
  activeModel,
  onModelChange
}) => {
  const [input, setInput] = useState('');
  const scrollRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (scrollRef.current) {
      scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }
  }, [messages]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (input.trim() && !isGenerating) {
      onSendMessage(input);
      setInput('');
    }
  };

  if (!isOpen) return null;

  return (
    <aside className="w-80 border-r border-white/10 backdrop-blur-3xl bg-slate-950/60 flex flex-col shrink-0 relative z-30 transition-all duration-300">
      <div className="p-6 border-b border-white/5">
        <h2 className="text-sm font-semibold text-slate-400 uppercase tracking-widest flex items-center gap-2">
          <span className="w-1.5 h-1.5 rounded-full bg-blue-400 animate-pulse"></span>
          AI Assistant
        </h2>
      </div>

      <div 
        ref={scrollRef}
        className="flex-1 overflow-y-auto p-4 space-y-4 scroll-smooth"
      >
        {messages.length === 0 && (
          <div className="text-center py-10 px-4">
            <div className="w-12 h-12 bg-white/5 rounded-2xl mx-auto flex items-center justify-center mb-4 border border-white/10">
              <svg className="w-6 h-6 text-slate-500" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" />
              </svg>
            </div>
            <p className="text-xs text-slate-500 leading-relaxed">
              Ask AI to generate design components, debug code, or research trends.
            </p>
          </div>
        )}

        {messages.map((msg) => (
          <div 
            key={msg.id} 
            className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'}`}
          >
            <div 
              className={`max-w-[90%] p-3 rounded-2xl text-sm leading-relaxed border ${
                msg.role === 'user' 
                  ? 'bg-blue-600/20 border-blue-500/30 text-blue-100 rounded-tr-none shadow-lg shadow-blue-900/10' 
                  : 'bg-white/5 border-white/10 text-slate-300 rounded-tl-none backdrop-blur-md'
              }`}
            >
              {msg.content}
            </div>
            {msg.model && (
              <span className="text-[10px] text-slate-600 mt-1 uppercase font-bold tracking-tighter">
                {msg.model.split('-')[0]}
              </span>
            )}
          </div>
        ))}

        {isGenerating && (
          <div className="flex items-center gap-2 text-blue-400 text-xs pl-2 font-medium">
            <div className="flex gap-1">
              <span className="w-1 h-1 bg-blue-400 rounded-full animate-bounce [animation-delay:-0.3s]"></span>
              <span className="w-1 h-1 bg-blue-400 rounded-full animate-bounce [animation-delay:-0.15s]"></span>
              <span className="w-1 h-1 bg-blue-400 rounded-full animate-bounce"></span>
            </div>
            Thinking...
          </div>
        )}
      </div>

      <div className="p-4 border-t border-white/5 bg-black/20">
        <form onSubmit={handleSubmit} className="relative">
          <textarea
            value={input}
            onChange={(e) => setInput(e.target.value)}
            placeholder="Build a glass card..."
            rows={1}
            className="w-full bg-white/5 border border-white/10 rounded-xl px-4 py-3 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500/50 resize-none pr-12 transition-all placeholder:text-slate-600"
            onKeyDown={(e) => {
              if (e.key === 'Enter' && !e.shiftKey) {
                e.preventDefault();
                handleSubmit(e);
              }
            }}
          />
          <button 
            type="submit"
            disabled={isGenerating || !input.trim()}
            className="absolute right-2 bottom-2 p-1.5 text-blue-400 hover:bg-blue-500/10 rounded-lg disabled:opacity-30 disabled:hover:bg-transparent transition-all"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 19l9 2-9-18-9 18 9-2zm0 0v-8" />
            </svg>
          </button>
        </form>
      </div>
    </aside>
  );
};

import React, { useEffect, useRef } from 'react';

interface PreviewProps {
  code: string;
}

export const Preview: React.FC<PreviewProps> = ({ code }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);

  useEffect(() => {
    if (iframeRef.current) {
      const doc = iframeRef.current.contentDocument;
      if (doc) {
        doc.open();
        doc.write(code);
        doc.close();
      }
    }
  }, [code]);

  return (
    <iframe
      ref={iframeRef}
      title="Preview"
      className="w-full h-full border-none"
      sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin"
    />
  );
};

import React, { useState, useEffect, useCallback, useRef } from 'react';
import Editor from '@monaco-editor/react';
import { Sidebar } from './components/Sidebar';
import { Preview } from './components/Preview';
import { Header } from './components/Header';
import { AIModel, ChatMessage, FileEntry } from './types';

const DEFAULT_CODE = `<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { background: #0f172a; display: flex; align-items: center; justify-content: center; min-height: 100vh; margin: 0; color: white; font-family: sans-serif; }
    .glass {
      background: rgba(255, 255, 255, 0.1);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255, 255, 255, 0.2);
      padding: 2rem;
      border-radius: 1.5rem;
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
  </style>
</head>
<body>
  <div class="glass text-center">
    <h1 class="text-4xl font-bold mb-4 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 to-purple-500">
      Vayu Code
    </h1>
    <p class="text-slate-300">Start building something futuristic.</p>
    <div class="mt-6 animate-bounce">
      <svg class="w-8 h-8 mx-auto text-blue-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
        <path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 14l-7 7m0 0l-7-7m7 7V3"></path>
      </svg>
    </div>
  </div>
</body>
</html>`;

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_CODE);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSidebarOpen, setSidebarOpen] = useState(true);
  const [isPuterReady, setIsPuterReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  useEffect(() => {
    // Puter.js v2 is typically available on window.puter.
    // We check for its presence and set the ready state accordingly.
    const checkPuter = () => {
      if (window.puter) {
        setIsPuterReady(true);
      } else {
        // Poll briefly if the script hasn't fully initialized the global object
        setTimeout(checkPuter, 100);
      }
    };
    checkPuter();
  }, []);

  const handleEditorChange = (value: string | undefined) => {
    if (value !== undefined) setCode(value);
  };

  const handleSendMessage = async (prompt: string) => {
    if (!isPuterReady || !prompt.trim()) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMsg]);
    setIsGenerating(true);

    try {
      // Use window.puter directly as it is provided by the v2 script tag
      const response = await window.puter.ai.chat(prompt, { model: activeModel });
      const assistantMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: response.toString(),
        model: activeModel,
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, assistantMsg]);

      // Simple heuristic to extract code blocks from markdown responses
      const codeMatch = assistantMsg.content.match(/```(?:html|javascript|css|typescript|tsx)?([\s\S]*?)```/);
      if (codeMatch && codeMatch[1]) {
        setCode(codeMatch[1].trim());
      }
    } catch (error: any) {
      console.error('AI error:', error);
      const errorMsg: ChatMessage = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: `Sorry, I encountered an error: ${error?.message || 'Unknown error'}. Please ensure you are logged into Puter or try again.`,
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMsg]);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#020617] text-slate-100 overflow-hidden">
      {/* Background Gradients */}
      <div className="fixed inset-0 overflow-hidden pointer-events-none opacity-20">
        <div className="absolute top-[-10%] left-[-10%] w-[40%] h-[40%] bg-purple-600 blur-[120px] rounded-full"></div>
        <div className="absolute bottom-[-10%] right-[-10%] w-[40%] h-[40%] bg-blue-600 blur-[120px] rounded-full"></div>
      </div>

      <Sidebar 
        isOpen={isSidebarOpen} 
        messages={messages} 
        onSendMessage={handleSendMessage}
        isGenerating={isGenerating}
        activeModel={activeModel}
        onModelChange={setActiveModel}
      />

      <div className="flex-1 flex flex-col min-w-0 relative z-10">
        <Header 
          activeModel={activeModel} 
          onModelChange={setActiveModel}
          onToggleSidebar={() => setSidebarOpen(!isSidebarOpen)}
          isSidebarOpen={isSidebarOpen}
        />

        <main className="flex-1 flex overflow-hidden p-4 gap-4">
          <div className="flex-1 flex flex-col bg-white/5 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-2xl overflow-hidden ring-1 ring-white/10">
            <div className="px-4 py-2 bg-white/5 border-b border-white/5 flex items-center justify-between">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Editor — index.html</span>
              <div className="flex gap-1.5">
                <div className="w-2.5 h-2.5 rounded-full bg-red-500/50"></div>
                <div className="w-2.5 h-2.5 rounded-full bg-yellow-500/50"></div>
                <div className="w-2.5 h-2.5 rounded-full bg-green-500/50"></div>
              </div>
            </div>
            <div className="flex-1 relative">
              <Editor
                height="100%"
                defaultLanguage="html"
                theme="vs-dark"
                value={code}
                onChange={handleEditorChange}
                options={{
                  minimap: { enabled: false },
                  fontSize: 14,
                  padding: { top: 16 },
                  scrollBeyondLastLine: false,
                  backgroundColor: 'transparent' as any,
                  fontFamily: "'Fira Code', 'Cascadia Code', monospace",
                  smoothScrolling: true,
                  cursorBlinking: "phase",
                  scrollbar: {
                    vertical: 'hidden',
                    horizontal: 'hidden'
                  }
                }}
              />
            </div>
          </div>

          <div className="flex-1 bg-neutral-900/40 backdrop-blur-md rounded-2xl border border-white/10 shadow-2xl overflow-hidden flex flex-col">
            <div className="px-4 py-2 bg-white/5 border-b border-white/5">
              <span className="text-xs font-medium text-slate-400 uppercase tracking-wider">Live Preview</span>
            </div>
            <div className="flex-1 bg-white">
              <Preview code={code} />
            </div>
          </div>
        </main>
      </div>
    </div>
  );
};

export default App;

payload.text:
Vayu Code refines its interface to mirror Google AI Studio's advanced editing format—expansive dual-pane prompt/response workspace, inline code editing with diff views, structured prompt tuning sidebar, and fluid streaming interactions. This evolution pushes beyond basic chat into a pro-grade AI IDE for design software, with glassmorphism layered over Studio's clean functionalism: prominent prompt composer (with history autocomplete), model parameter sliders, response forking, and seamless code playground integration.

## Google AI Studio Editing Layout
**Primary Workspace**: Centered prompt bar spans full-width (like Studio's input field), with real-time suggestions and template picker. Right-side response pane streams tokens with expandable code blocks that auto-sync to Monaco editor.

```
┌────────────────────────────────────────────────────────────── Vayu Code ───────┐
│ [Model: Claude 3.5 Sonnet] [Temp: 0.7 ▓ 1.2] [Max Tokens: 8k ▓ 128k] [Send] │
├─ Prompt Composer (Studio-style, 4x taller) ──────────────────────────────────────┤
│ "Build responsive glassmorphism navbar with Tailwind + Framer Motion wind effect" │
│ [🎨 Design Templates] [📚 Prompt History] [🔍 Web Context] [📎 Upload Sketch]   │
├─ Streaming Response (Forkable Cards) ───────────────────────────────────────────┤
│ AI: Here's your navbar component:                                                 │
│ ┌─ Code Block ──────────────────────┐ ┌─ Live Preview ─────────┐             │
│ │ ```jsx                            │ │ [Canvas Render]        │             │
