export enum AIModel {
  GEMINI = 'gemini-2.0-flash',
  GPT4 = 'gpt-4o',
  CLAUDE = 'claude-3.5-sonnet',
  DEEPSEEK = 'deepseek-v2',
  LLAMA = 'llama-3.1-70b'
}

export interface AIConfig {
  temperature: number;
  topP: number;
  maxTokens: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: AIModel;
  config?: AIConfig;
  timestamp: number;
  isStreaming?: boolean;
}

export interface FileEntry {
  name: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
  }
}

import React, { useState, useEffect, useRef } from 'react';
import Editor from '@monaco-editor/react';
import { Sidebar } from './components/Sidebar';
import { Preview } from './components/Preview';
import { Header } from './components/Header';
import { PromptComposer } from './components/PromptComposer';
import { ResponseCard } from './components/ResponseCard';
import { AIModel, ChatMessage, AIConfig } from './types';

const DEFAULT_CODE = `<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { background: #020617; display: flex; align-items: center; justify-content: center; min-height: 100vh; margin: 0; color: white; font-family: sans-serif; overflow: hidden; }
    .glass {
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(24px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      padding: 3rem;
      border-radius: 2rem;
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.8);
      text-align: center;
    }
    .glow {
      position: absolute;
      width: 300px;
      height: 300px;
      background: radial-gradient(circle, rgba(59, 130, 246, 0.3) 0%, transparent 70%);
      filter: blur(40px);
