    }
  </style>
</head>
<body>
  <div class="glow" style="top: 10%; left: 10%;"></div>
  <div class="glow" style="bottom: 10%; right: 10%; background: radial-gradient(circle, rgba(139, 92, 246, 0.3) 0%, transparent 70%);"></div>
  <div class="glass">
    <h1 class="text-6xl font-black mb-4 bg-clip-text text-transparent bg-gradient-to-r from-blue-400 via-indigo-400 to-purple-500">
      Vayu Code
    </h1>
    <p class="text-slate-400 text-lg max-w-md mx-auto">
      Studio-grade AI IDE for the next generation of design software.
    </p>
  </div>
</body>
</html>`;

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_CODE);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [config, setConfig] = useState<AIConfig>({ temperature: 0.7, topP: 0.9, maxTokens: 4096 });
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isPuterReady, setIsPuterReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkPuter = () => {
      if (window.puter) {
        setIsPuterReady(true);
      } else {
        setTimeout(checkPuter, 100);
      }
    };
    checkPuter();
  }, []);

  const handleSendMessage = async (prompt: string) => {
    if (!isPuterReady || !prompt.trim() || isGenerating) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMsg]);
    setIsGenerating(true);

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      config: { ...config },
      timestamp: Date.now(),
      isStreaming: true,
    };

    setMessages(prev => [...prev, assistantMsg]);

    try {
      const stream = await window.puter.ai.chat(prompt, {
        model: activeModel,
        temperature: config.temperature,
        top_p: config.topP,
        max_tokens: config.maxTokens,
        stream: true
      });

      let fullContent = '';
      for await (const chunk of stream) {
        fullContent += chunk;
        setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent } : m));

        // Auto-scroll as content streams
        if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollTop = scrollContainerRef.current.scrollHeight;
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false } : m));

      // Extract code
      const codeMatch = fullContent.match(/```(?:html|javascript|css|typescript|jsx|tsx)?([\s\S]*?)```/);
      if (codeMatch && codeMatch[1]) {
        // We don't auto-apply to the editor anymore to match the "fork/apply" Studio workflow, 
        // but we'll provide an "Apply" button in the ResponseCard.
      }
    } catch (error: any) {
      console.error('AI error:', error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { 
        ...m, 
        content: `Error: ${error?.message || 'Connection failed'}. Check Puter login status.`, 
        isStreaming: false 
      } : m));
    } finally {
      setIsGenerating(false);
    }
  };

  const applyCodeToIDE = (newCode: string) => {
    setCode(newCode);
  };

  const forkResponse = (msgId: string) => {
    const msg = messages.find(m => m.id === msgId);
    if (msg) {
      handleSendMessage(`Refine this output: ${msg.content.substring(0, 100)}...`);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#020617] text-slate-100 overflow-hidden font-sans">
      {/* Background Ambience */}
      <div className="fixed inset-0 pointer-events-none opacity-30">
        <div className="absolute top-0 right-0 w-[800px] h-[800px] bg-blue-600/20 blur-[160px] rounded-full -translate-y-1/2 translate-x-1/2"></div>
        <div className="absolute bottom-0 left-0 w-[600px] h-[600px] bg-purple-600/10 blur-[140px] rounded-full translate-y-1/2 -translate-x-1/2"></div>
      </div>

      <Sidebar 
        isOpen={isSidebarOpen} 
        messages={messages} 
        onToggle={() => setSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0 relative z-10">
        <Header 
          activeModel={activeModel} 
          onModelChange={setActiveModel}
          onToggleSidebar={() => setSidebarOpen(!isSidebarOpen)}
          isSidebarOpen={isSidebarOpen}
          config={config}
          onConfigChange={setConfig}
        />

        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Main Workspace (Scrollable) */}
          <div 
            ref={scrollContainerRef}
            className="flex-1 overflow-y-auto px-6 py-8 space-y-10 custom-scrollbar"
          >
            <div className="max-w-6xl mx-auto w-full">
              <PromptComposer 
                onSend={handleSendMessage} 
                isGenerating={isGenerating} 
                activeModel={activeModel}
              />
            </div>

            <div className="max-w-6xl mx-auto w-full space-y-6">
              {messages.filter(m => m.role === 'assistant').map((msg) => (
                <ResponseCard 
                  key={msg.id} 
                  message={msg} 
                  onApply={applyCodeToIDE}
                  onFork={() => forkResponse(msg.id)}
                />
              ))}
            </div>

            {/* Pad the bottom for visibility */}
            <div className="h-32"></div>
          </div>

          {/* IDE Footer Workspace (Sticky) */}
          <div className="h-[45vh] border-t border-white/10 backdrop-blur-3xl bg-black/40 p-4 gap-4 flex shrink-0">
            <div className="flex-1 flex flex-col bg-white/5 border border-white/10 rounded-2xl overflow-hidden ring-1 ring-white/5">
              <div className="px-4 py-2 bg-white/5 border-b border-white/5 flex items-center justify-between">
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-[0.2em]">Source Code</span>
                <div className="flex gap-1.5 opacity-50">
                  <div className="w-2.5 h-2.5 rounded-full bg-red-500"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-yellow-500"></div>
                  <div className="w-2.5 h-2.5 rounded-full bg-green-500"></div>
                </div>
              </div>
              <div className="flex-1">
                <Editor
                  height="100%"
                  defaultLanguage="html"
                  theme="vs-dark"
                  value={code}
                  onChange={(v) => setCode(v || '')}
                  options={{
                    minimap: { enabled: false },
                    fontSize: 13,
                    padding: { top: 12 },
                    backgroundColor: 'transparent',
                    fontFamily: "'Fira Code', monospace",
                    smoothScrolling: true,
                    lineNumbersMinChars: 3,
                    scrollBeyondLastLine: false,
                  }}
                />
              </div>
            </div>

            <div className="flex-1 bg-white rounded-2xl border border-white/10 overflow-hidden flex flex-col shadow-2xl">
              <div className="px-4 py-2 bg-slate-100 border-b border-slate-200 flex items-center justify-between">
                <span className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Live Render</span>
              </div>
              <div className="flex-1">
                <Preview code={code} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState } from 'react';

interface PromptComposerProps {
  onSend: (prompt: string) => void;
  isGenerating: boolean;
  activeModel: string;
}

export const PromptComposer: React.FC<PromptComposerProps> = ({ onSend, isGenerating, activeModel }) => {
  const [input, setInput] = useState('');

  const handleSubmit = (e?: React.FormEvent) => {
    e?.preventDefault();
    if (input.trim() && !isGenerating) {
      onSend(input);
      setInput('');
    }
  };

  const templates = [
    { label: '🎨 Glass Navbar', prompt: 'Build a responsive glassmorphism navbar using Tailwind and Framer Motion.' },
    { label: '📦 Product Card', prompt: 'Create a 3D-hover product card with frosted glass background and neon glow.' },
    { label: '🌊 Wind Effect', prompt: 'Generate a CSS-only animated wind distortion effect for a glass container.' }
  ];

  return (
    <div className="bg-white/5 backdrop-blur-2xl border border-white/10 rounded-3xl p-6 shadow-2xl ring-1 ring-white/10 transition-all focus-within:ring-white/20">
      <div className="flex flex-col gap-4">
        <textarea
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder={`Describe your design vision for ${activeModel.split('-')[0]}...`}
          className="w-full bg-transparent text-xl font-light text-slate-100 placeholder:text-slate-600 outline-none resize-none min-h-[120px] leading-relaxed"
          onKeyDown={(e) => {
            if (e.key === 'Enter' && e.metaKey) {
              handleSubmit();
            }
          }}
        />

        <div className="flex flex-wrap items-center justify-between gap-4 border-t border-white/5 pt-4">
          <div className="flex gap-2">
            {templates.map(t => (
              <button
                key={t.label}
                onClick={() => setInput(t.prompt)}
                className="px-3 py-1.5 rounded-full bg-white/5 border border-white/10 text-[11px] font-medium text-slate-400 hover:bg-white/10 hover:text-white transition-all"
              >
                {t.label}
              </button>
            ))}
          </div>

          <button
            onClick={() => handleSubmit()}
            disabled={isGenerating || !input.trim()}
            className="group flex items-center gap-3 px-8 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 hover:from-blue-500 hover:to-indigo-500 disabled:opacity-30 disabled:grayscale rounded-2xl transition-all shadow-xl shadow-blue-500/20 active:scale-95"
          >
            <span className="font-bold text-sm tracking-wide">
              {isGenerating ? 'GENERATING...' : 'GENERATE'}
            </span>
            <svg className={`w-5 h-5 ${isGenerating ? 'animate-spin' : 'group-hover:translate-x-1 transition-transform'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M14 5l7 7m0 0l-7 7m7-7H3" />
            </svg>
          </button>
        </div>
      </div>
      <div className="mt-2 text-[10px] text-slate-600 font-mono tracking-widest text-right">
        ⌘ + ENTER TO SEND
      </div>
    </div>
  );
};

