```html
<!DOCTYPE html>
<html class="h-screen w-screen overflow-hidden">
<head>
  <script src="https://js.puter.com/v2/"></script>
  <script src="https://cdn.tailwindcss.com"></script>
  <script src="https://cdnjs.cloudflare.com/ajax/libs/three.js/r128/three.min.js"></script>
  <title>Vayu Code Antigravity</title>
  <style>
    * { margin: 0; padding: 0; }
    body { 
      background: radial-gradient(ellipse at center, #0f0f23 0%, #000 70%);
      overflow: hidden;
      font-family: 'Inter', -apple-system, sans-serif;
      cursor: grab;
    }
    body:active { cursor: grabbing; }
    #ui-canvas { position: fixed; inset: 0; z-index: 100; pointer-events: none; }
  </style>
</head>
<body>
  <canvas id="antigravity" class="w-full h-full"></canvas>
  <div id="ui-canvas"></div>

  <script>
    class AntigravityIDE {
      constructor() {
        this.scene = new THREE.Scene();
        this.camera = new THREE.PerspectiveCamera(75, innerWidth / innerHeight, 0.1, 10000);
        this.renderer = new THREE.WebGLRenderer({ 
          canvas: document.getElementById('antigravity'),
          antialias: true,
          alpha: true 
        });
        this.orbs = [];
        this.raycaster = new THREE.Raycaster();
        this.mouse = new THREE.Vector2();
        this.init();
      }

      init() {
        this.renderer.setSize(innerWidth, innerHeight);
        this.renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
        this.camera.position.set(0, 0, 15);

        // Nebula background
        const nebula = new THREE.Mesh(
          new THREE.SphereGeometry(2000),
          new THREE.MeshBasicMaterial({
            map: this.createNebulaTexture(),
            side: THREE.BackSide
          })
        );
        this.scene.add(nebula);

        // Create orbital stations
        this.createPrimeOrb();
        this.createAgentCluster();
        this.createPreviewGalaxy();

        this.animate();
        this.bindControls();
      }

      createNebulaTexture() {
        const canvas = document.createElement('canvas');
        canvas.width = canvas.height = 2048;
        const ctx = canvas.getContext('2d');
        const gradient = ctx.createRadialGradient(1024, 1024, 0, 1024, 1024, 1024);
        gradient.addColorStop(0, 'rgba(120,119,198,0.3)');
        gradient.addColorStop(0.2, 'rgba(255,119,198,0.1)');
        gradient.addColorStop(1, 'rgba(0,0,50,0.8)');
        ctx.fillStyle = gradient;
        ctx.fillRect(0, 0, 2048, 2048);
        return new THREE.CanvasTexture(canvas);
      }

      createPrimeOrb() {
        const orbGroup = new THREE.Group();
        const geometry = new THREE.SphereGeometry(2.5, 64, 64);

        // Glass material with refraction
        const material = new THREE.MeshPhysicalMaterial({
          color: 0x88ccff,
          metalness: 0.1,
          roughness: 0.05,
          transmission: 0.95,
          thickness: 0.5,
          clearcoat: 1.0,
          clearcoatRoughness: 0.1
        });

        const orb = new THREE.Mesh(geometry, material);
        orb.position.set(-8, 2, 0);

        // Floating text
        const canvas = this.createTextCanvas('PRIME EDITOR');
        const textTexture = new THREE.CanvasTexture(canvas);
        const textMat = new THREE.MeshBasicMaterial({ 
          map: textTexture, 
          transparent: true, 
          opacity: 0.9 
        });
        const textOrb = new THREE.Mesh(new THREE.SphereGeometry(2.6, 32, 32), textMat);
        textOrb.position.set(-8, 2, 0);

        orbGroup.add(orb, textOrb);
        orbGroup.userData = { type: 'editor', prompt: '', code: '' };
        this.scene.add(orbGroup);
        this.orbs.push(orbGroup);
      }

      createAgentCluster() {
        const agents = ['CLAUDE', 'GEMINI', 'DEEPSEEK', 'O1'];
        const radius = 8;

        agents.forEach((agent, i) => {
          const angle = (i / agents.length) * Math.PI * 2;
          const orb = this.createAgentOrb(agent, 
            Math.cos(angle) * radius, 
            Math.sin(angle) * 2, 
            Math.sin(angle) * radius
          );
          this.orbs.push(orb);
        });
      }

      createAgentOrb(name, x, y, z) {
        const group = new THREE.Group();
        const orb = new THREE.Mesh(
          new THREE.SphereGeometry(1.8, 32, 32),
          new THREE.MeshPhysicalMaterial({
            color: new THREE.Color().setHSL((Date.now() * 0.001 + x) % 1, 0.7, 0.6),
            metalness: 0.2,
            roughness: 0.1,
            transmission: 0.9
          })
        );
        orb.position.set(x, y, z);

        group.add(orb);
        group.userData = { type: 'agent', name };
        this.scene.add(group);
        return group;
      }

      createPreviewGalaxy() {
        for (let i = 0; i < 50; i++) {
          const orb = new THREE.Mesh(
            new THREE.SphereGeometry(0.3 + Math.random() * 0.5, 16, 16),
            new THREE.MeshBasicMaterial({
              color: new THREE.Color().setHSL(Math.random(), 0.8, 0.6),
              transparent: true,
              opacity: 0.7
            })
          );
          orb.position.set(
            (Math.random() - 0.5) * 40,
            (Math.random() - 0.5) * 20,
            (Math.random() - 0.5) * 40
          );
          this.scene.add(orb);
          this.orbs.push(orb);
        }
      }

      bindControls() {
        window.addEventListener('mousemove', (e) => {
          this.mouse.x = (e.clientX / innerWidth) * 2 - 1;
          this.mouse.y = -(e.clientY / innerHeight) * 2 + 1;
        });

        window.addEventListener('click', (e) => {
          this.raycaster.setFromCamera(this.mouse, this.camera);
          const intersects = this.raycaster.intersectObjects(this.orbs);

          if (intersects.length > 0) {
            const orb = intersects[0].object.parent;
            this.selectOrb(orb);
          }
        });

        window.addEventListener('wheel', (e) => {
          this.camera.position.z += e.deltaY * 0.01;
          this.camera.position.z = Math.max(5, Math.min(50, this.camera.position.z));
        });
      }

      selectOrb(orb) {
        // Glow effect
        orb.children[0].material.emissive.setHex(0x4444ff);
        setTimeout(() => {
          orb.children[0].material.emissive.setHex(0x000000);
        }, 1000);

        if (orb.userData.type === 'agent') {
          this.executeAgent(orb.userData.name);
        }
      }

      async executeAgent(agentName) {
        const statusDiv = document.createElement('div');
        statusDiv.className = 'fixed top-4 right-4 glass-orb-status p-4 rounded-3xl text-white text-sm';
        statusDiv.textContent = `${agentName} executing...`;
        document.getElementById('ui-canvas').appendChild(statusDiv);

        // Puter.js AI execution
        try {
          const result = await puter.ai.chat('Generate glassmorphism dashboard', {
            model: agentName.toLowerCase() === 'claude' ? 'claude-3.5-sonnet' : 'gemini-2.0-flash',
            temperature: 0.8
          });

          statusDiv.textContent = `${agentName}: Complete!`;
          statusDiv.style.background = 'rgba(0,255,0,0.3)';
        } catch (e) {
          statusDiv.textContent = 'Error';
          statusDiv.style.background = 'rgba(255,0,0,0.3)';
        }

        setTimeout(() => statusDiv.remove(), 3000);
      }

      animate() {
        requestAnimationFrame(() => this.animate());

        // Orbital motion
        this.orbs.forEach((orb, i) => {
          const time = Date.now() * 0.0005 + i;
          orb.rotation.y += 0.01;
          orb.position.y += Math.sin(time) * 0.02;
        });

        // Mouse attraction
        const attractForce = 0.1;
        this.camera.position.x += (this.mouse.x * 10 - this.camera.position.x) * attractForce * 0.05;
        this.camera.position.y += (-this.mouse.y * 10 - this.camera.position.y) * attractForce * 0.05;

        this.renderer.render(this.scene, this.camera);
      }
    }

    // Launch antigravity
    puter.ready(() => {
      window.ide = new AntigravityIDE();
    });

    // Responsive
    window.addEventListener('resize', () => {
      const camera = window.ide?.camera;
      const renderer = window.ide?.renderer;
      if (camera && renderer) {
        camera.aspect = innerWidth / innerHeight;
        camera.updateProjectionMatrix();
        renderer.setSize(innerWidth, innerHeight);
      }
    });
  </script>
</body>
</html>
```

