    if (input.trim() && !isGenerating) {
      onSend(input);
      setInput('');
    }
  };

  return (
    <div className="bg-white/[0.03] backdrop-blur-[50px] border border-white/10 rounded-[3rem] p-10 shadow-[0_50px_100px_-20px_rgba(0,0,0,0.7)] ring-1 ring-white/10 transition-all hover:bg-white/[0.05]">
      <div className="flex flex-col gap-6">
        <textarea
          value={input}
          onChange={(e) => setInput(e.target.value)}
          placeholder={`Broadcast your vision to ${activeModel.split('-')[0]}...`}
          className="w-full bg-transparent text-2xl font-light text-slate-100 placeholder:text-slate-700 outline-none resize-none min-h-[140px] leading-snug"
          onKeyDown={(e) => {
            if (e.key === 'Enter' && e.metaKey) {
              handleSubmit();
            }
          }}
        />

        <div className="flex items-center justify-between border-t border-white/5 pt-6">
          <div className="flex gap-3">
             <div className="flex items-center gap-2 px-4 py-2 bg-white/5 rounded-full border border-white/10 text-[10px] text-slate-500 uppercase font-bold tracking-widest">
               <span className="w-1.5 h-1.5 rounded-full bg-indigo-500"></span>
               Spatial Pulse
             </div>
          </div>

          <button
            onClick={() => handleSubmit()}
            disabled={isGenerating || !input.trim()}
            className="group relative flex items-center gap-4 px-10 py-4 bg-gradient-to-tr from-indigo-600 to-violet-600 rounded-[2rem] transition-all hover:scale-105 active:scale-95 shadow-xl shadow-indigo-500/30 overflow-hidden"
          >
            <div className="absolute inset-0 bg-gradient-to-r from-white/0 via-white/10 to-white/0 -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
            <span className="font-black text-sm tracking-[0.2em] text-white">
              {isGenerating ? 'ORBITING...' : 'TRANSMIT'}
            </span>
            <svg className={`w-5 h-5 text-white ${isGenerating ? 'animate-spin' : ''}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" />
            </svg>
          </button>
        </div>
      </div>
    </div>
  );
};

