import React, { useState, useEffect, useRef } from 'react';
import Editor from '@monaco-editor/react';
import { Sidebar } from './components/Sidebar';
import { Preview } from './components/Preview';
import { Header } from './components/Header';
import { PromptComposer } from './components/PromptComposer';
import { ResponseCard } from './components/ResponseCard';
import { AntigravityCanvas } from './components/AntigravityCanvas';
import { AIModel, ChatMessage, AIConfig } from './types';

const DEFAULT_CODE = `<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { background: #000; color: white; min-height: 100vh; display: flex; align-items: center; justify-content: center; overflow: hidden; font-family: sans-serif; }
    .antigravity-card {
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(40px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      padding: 4rem;
      border-radius: 50%;
      width: 500px;
      height: 500px;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      box-shadow: 0 0 100px rgba(99, 102, 241, 0.2), inset 0 0 50px rgba(255, 255, 255, 0.05);
      animation: drift 20s infinite ease-in-out;
    }
    @keyframes drift {
      0%, 100% { transform: translateY(0) scale(1); }
      50% { transform: translateY(-20px) scale(1.02); }
    }
    .glow-text {
      text-shadow: 0 0 20px rgba(99, 102, 241, 0.8);
    }
  </style>
</head>
<body>
  <div class="antigravity-card text-center">
    <h1 class="text-5xl font-black mb-4 tracking-tighter glow-text">VAYU CODE</h1>
    <p class="text-indigo-300 text-sm uppercase tracking-[0.5em] font-bold">Antigravity Edition</p>
    <div class="mt-12 space-y-4 opacity-40">
      <p class="text-[10px] tracking-widest">ZERO GRAVITY ENABLED</p>
      <div class="h-px w-24 bg-white/20 mx-auto"></div>
      <p class="text-[10px] tracking-widest">SPATIAL COMPUTE ACTIVE</p>
    </div>
  </div>
</body>
</html>`;

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_CODE);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [config, setConfig] = useState<AIConfig>({ temperature: 0.8, topP: 0.9, maxTokens: 4096 });
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isPuterReady, setIsPuterReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkPuter = () => {
      if (window.puter) {
        setIsPuterReady(true);
      } else {
        setTimeout(checkPuter, 100);
      }
    };
    checkPuter();
  }, []);

  const handleSendMessage = async (prompt: string) => {
    if (!isPuterReady || !prompt.trim() || isGenerating) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMsg]);
    setIsGenerating(true);

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      config: { ...config },
      timestamp: Date.now(),
      isStreaming: true,
    };

    setMessages(prev => [...prev, assistantMsg]);

    try {
      const stream = await window.puter.ai.chat(prompt, {
        model: activeModel,
        temperature: config.temperature,
        top_p: config.topP,
        max_tokens: config.maxTokens,
        stream: true
      });

      let fullContent = '';
      for await (const chunk of stream) {
        fullContent += chunk;
        setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent } : m));

        if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollTop = scrollContainerRef.current.scrollHeight;
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false } : m));
    } catch (error: any) {
      console.error('AI error:', error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { 
        ...m, 
        content: `Orbital Error: ${error?.message || 'Signal lost'}. Ensure Puter uplink is active.`, 
        isStreaming: false 
      } : m));
    } finally {
      setIsGenerating(false);
    }
  };

  const applyCodeToIDE = (newCode: string) => {
    setCode(newCode);
  };

  return (
    <div className="flex h-screen w-full bg-black text-slate-100 overflow-hidden font-sans cursor-default">
      <AntigravityCanvas />

      <Sidebar 
        isOpen={isSidebarOpen} 
        messages={messages} 
        onToggle={() => setSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0 relative z-10">
        <Header 
          activeModel={activeModel} 
          onModelChange={setActiveModel}
          onToggleSidebar={() => setSidebarOpen(!isSidebarOpen)}
          isSidebarOpen={isSidebarOpen}
          config={config}
          onConfigChange={setConfig}
        />

        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Spatial Workspace */}
          <div 
            ref={scrollContainerRef}
            className="flex-1 overflow-y-auto px-6 py-8 space-y-12 custom-scrollbar perspective-[2000px]"
          >
            <div className="max-w-4xl mx-auto w-full transform transition-all duration-700 hover:translate-z-10">
              <PromptComposer 
                onSend={handleSendMessage} 
                isGenerating={isGenerating} 
                activeModel={activeModel}
              />
            </div>

            <div className="max-w-4xl mx-auto w-full space-y-8">
              {messages.filter(m => m.role === 'assistant').map((msg) => (
                <div key={msg.id} className="orb-float transform transition-transform duration-500 hover:scale-[1.02]">
                  <ResponseCard 
                    message={msg} 
                    onApply={applyCodeToIDE}
                    onFork={() => handleSendMessage(`Remix this output: ${msg.content.substring(0, 50)}...`)}
                  />
                </div>
              ))}
            </div>

            <div className="h-48"></div>
          </div>

          {/* Antigravity Docked Workspaces */}
          <div className="h-[40vh] border-t border-white/5 backdrop-blur-[60px] bg-black/60 p-6 gap-6 flex shrink-0 relative">
            <div className="absolute inset-x-0 -top-8 h-8 bg-gradient-to-t from-black/60 to-transparent pointer-events-none"></div>

            <div className="flex-1 flex flex-col bg-white/[0.03] border border-white/10 rounded-[2.5rem] overflow-hidden shadow-[0_-20px_60px_-15px_rgba(0,0,0,0.5)]">
              <div className="px-6 py-3 bg-white/5 border-b border-white/5 flex items-center justify-between">
                <span className="text-[9px] font-black text-indigo-400 uppercase tracking-[0.4em]">Spatial Code Editor</span>
              </div>
              <div className="flex-1">
                <Editor
                  height="100%"
                  defaultLanguage="html"
                  theme="vs-dark"
                  value={code}
                  onChange={(v) => setCode(v || '')}
                  options={{
                    minimap: { enabled: false },
                    fontSize: 13,
                    padding: { top: 16 },
                    backgroundColor: 'transparent',
                    fontFamily: "'Fira Code', monospace",
                    smoothScrolling: true,
                    lineNumbers: 'on',
                    renderLineHighlight: 'all',
                    scrollbar: { vertical: 'hidden' }
                  }}
                />
              </div>
            </div>

            <div className="flex-1 bg-white rounded-[2.5rem] border border-white/10 overflow-hidden flex flex-col shadow-2xl transition-transform hover:scale-[1.01] duration-500">
              <div className="px-6 py-3 bg-slate-900 border-b border-white/5 flex items-center justify-between">
                <span className="text-[9px] font-black text-indigo-300 uppercase tracking-[0.4em]">Holographic Preview</span>
              </div>
              <div className="flex-1">
                <Preview code={code} />
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

// Exporting the App component to fix the "no default export" error in index.tsx
export default App;

import React, { useEffect, useRef } from 'react';
// Import THREE to resolve missing reference errors
import * as THREE from 'three';

export const AntigravityCanvas: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    // Use THREE constants and classes from the imported namespace
    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({
      canvas: canvasRef.current,
      antialias: true,
      alpha: true
    });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    camera.position.z = 20;

    // Nebula Texture
    const createNebulaTexture = () => {
      const canvas = document.createElement('canvas');
      canvas.width = canvas.height = 1024;
      const ctx = canvas.getContext('2d')!;
      const gradient = ctx.createRadialGradient(512, 512, 0, 512, 512, 512);
      gradient.addColorStop(0, 'rgba(49, 46, 129, 0.4)');
      gradient.addColorStop(0.5, 'rgba(67, 56, 202, 0.1)');
      gradient.addColorStop(1, 'rgba(0, 0, 0, 0.8)');
      ctx.fillStyle = gradient;
      ctx.fillRect(0, 0, 1024, 1024);
      return new THREE.CanvasTexture(canvas);
    };

    const nebula = new THREE.Mesh(
      new THREE.SphereGeometry(100, 32, 32),
      new THREE.MeshBasicMaterial({
        map: createNebulaTexture(),
        side: THREE.BackSide
      })
    );
    scene.add(nebula);

    // Star Field
    const starGeometry = new THREE.BufferGeometry();
    const starMaterial = new THREE.PointsMaterial({ color: 0xffffff, size: 0.1 });
    const starVertices = [];
    for (let i = 0; i < 5000; i++) {
      const x = (Math.random() - 0.5) * 2000;
      const y = (Math.random() - 0.5) * 2000;
      const z = (Math.random() - 0.5) * 2000;
      starVertices.push(x, y, z);
    }
    starGeometry.setAttribute('position', new THREE.Float32BufferAttribute(starVertices, 3));
    const stars = new THREE.Points(starGeometry, starMaterial);
    scene.add(stars);

    // Decorative floating orbs
    const orbs: THREE.Mesh[] = [];
    for (let i = 0; i < 20; i++) {
      const orb = new THREE.Mesh(
        new THREE.SphereGeometry(Math.random() * 0.5 + 0.1, 16, 16),
        new THREE.MeshPhysicalMaterial({
          color: new THREE.Color().setHSL(Math.random(), 0.7, 0.5),
          transparent: true,
          opacity: 0.6,
          metalness: 0.2,
          roughness: 0.1,
          transmission: 0.9
        })
      );
      orb.position.set(
        (Math.random() - 0.5) * 40,
        (Math.random() - 0.5) * 20,
        (Math.random() - 0.5) * 40
      );
      scene.add(orb);
      orbs.push(orb);
    }

    const animate = () => {
      requestAnimationFrame(animate);
      stars.rotation.y += 0.0002;
      orbs.forEach((orb, i) => {
        const t = Date.now() * 0.0005 + i;
        orb.position.y += Math.sin(t) * 0.005;
        orb.rotation.y += 0.01;
      });
      renderer.render(scene, camera);
    };

    animate();

    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };

    window.addEventListener('resize', handleResize);
    return () => {
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, []);

  return <canvas ref={canvasRef} className="fixed inset-0 z-0 pointer-events-none" />;
};

