import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

interface AntigravityCanvasProps {
  onOrbClick?: (type: string, name: string) => void;
}

export const AntigravityCanvas: React.FC<AntigravityCanvasProps> = ({ onOrbClick }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const mouseRef = useRef(new THREE.Vector2());
  const cameraRef = useRef<THREE.PerspectiveCamera | null>(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 10000);
    cameraRef.current = camera;

    const renderer = new THREE.WebGLRenderer({
      canvas: canvasRef.current,
      antialias: true,
      alpha: true,
      powerPreference: "high-performance"
    });

    renderer.setSize(window.innerWidth, window.innerHeight);
    renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
    renderer.shadowMap.enabled = true;
    camera.position.set(0, 0, 22);

    // Cosmic Background - Starfield
    const starGeometry = new THREE.BufferGeometry();
    const starVertices = [];
    for (let i = 0; i < 8000; i++) {
      starVertices.push((Math.random() - 0.5) * 4000, (Math.random() - 0.5) * 4000, (Math.random() - 0.5) * 4000);
    }
    starGeometry.setAttribute('position', new THREE.Float32BufferAttribute(starVertices, 3));
    const stars = new THREE.Points(starGeometry, new THREE.PointsMaterial({ color: 0xffffff, size: 0.9, transparent: true, opacity: 0.4 }));
    scene.add(stars);

    // Nebula Effect
    const createNebula = () => {
      const canvas = document.createElement('canvas');
      canvas.width = 1024; canvas.height = 1024;
      const ctx = canvas.getContext('2d')!;
      const grad = ctx.createRadialGradient(512, 512, 0, 512, 512, 512);
      grad.addColorStop(0, 'rgba(59, 130, 246, 0.15)');
      grad.addColorStop(0.4, 'rgba(139, 92, 246, 0.05)');
      grad.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = grad;
      ctx.fillRect(0, 0, 1024, 1024);
      return new THREE.CanvasTexture(canvas);
    };
    const nebula = new THREE.Mesh(new THREE.SphereGeometry(300, 32, 32), new THREE.MeshBasicMaterial({ map: createNebula(), side: THREE.BackSide, transparent: true }));
    scene.add(nebula);

    // Interactive Orbs
    const orbs: THREE.Group[] = [];
    const raycaster = new THREE.Raycaster();

    const createOrb = (radius: number, color: number, x: number, y: number, z: number, type: string, name: string) => {
      const group = new THREE.Group();
      const material = new THREE.MeshPhysicalMaterial({
        color,
        metalness: 0.2,
        roughness: 0.1,
        transmission: 0.98,
        thickness: 1.0,
        clearcoat: 1.0,
        emissive: color,
        emissiveIntensity: 0.1
      });
      const mesh = new THREE.Mesh(new THREE.SphereGeometry(radius, 64, 64), material);
      mesh.castShadow = true;
      group.add(mesh);
      group.position.set(x, y, z);
      group.userData = { type, name };
      scene.add(group);
      orbs.push(group);
      return group;
    };

    // Strategic Orb Placement
    createOrb(4, 0x3b82f6, -14, 4, 0, 'editor', 'Prime Source');
    createOrb(2.8, 0xec4899, 12, 6, -5, 'ai-cursor', 'Neural Flux');
    createOrb(2.4, 0x10b981, 0, -10, 2, 'download', 'Archive Link');

    // Agent Galaxy - Floating around the periphery
    const agentColors = [0x8b5cf6, 0x3b82f6, 0xf43f5e, 0x10b981];
    const agentNames = ['Claude 3.5', 'Gemini 2.0', 'DeepSeek v2', 'GPT-4o'];
    agentNames.forEach((name, i) => {
      const angle = (i / agentNames.length) * Math.PI * 2;
      const r = 24;
      const x = Math.cos(angle) * r;
      const z = Math.sin(angle) * r;
      createOrb(1.8, agentColors[i], x, Math.sin(i * 1.5) * 4, z, 'agent', name);
    });

    // Lights
    const ambientLight = new THREE.AmbientLight(0xffffff, 0.5);
    scene.add(ambientLight);
    const pointLight = new THREE.PointLight(0x6366f1, 2);
    pointLight.position.set(30, 30, 30);
    scene.add(pointLight);

    const animate = () => {
      requestAnimationFrame(animate);
      const time = Date.now() * 0.0004;

      stars.rotation.y += 0.0001;
      nebula.rotation.y += 0.00005;

      orbs.forEach((orb, i) => {
        orb.position.y += Math.sin(time + i * 0.5) * 0.012;
        orb.rotation.y += 0.004;
      });

      // Smooth camera sway
      if (cameraRef.current) {
        cameraRef.current.position.x += (mouseRef.current.x * 6 - cameraRef.current.position.x) * 0.04;
        cameraRef.current.position.y += (-mouseRef.current.y * 6 - cameraRef.current.position.y) * 0.04;
        cameraRef.current.lookAt(0, 0, 0);
      }

      renderer.render(scene, camera);
    };

    animate();

    const handleMouseMove = (e: MouseEvent) => {
      mouseRef.current.x = (e.clientX / window.innerWidth) * 2 - 1;
      mouseRef.current.y = -(e.clientY / window.innerHeight) * 2 + 1;
    };

    const handleClick = (e: MouseEvent) => {
      if (!cameraRef.current) return;
      raycaster.setFromCamera(mouseRef.current, cameraRef.current);
      const intersects = raycaster.intersectObjects(scene.children, true);
      if (intersects.length > 0) {
        let target = intersects[0].object;
        while (target.parent && !target.userData.type) target = target.parent;
        if (target.userData.type && onOrbClick) {
          onOrbClick(target.userData.type, target.userData.name);
        }
      }
    };

    const handleResize = () => {
      if (cameraRef.current) {
        cameraRef.current.aspect = window.innerWidth / window.innerHeight;
        cameraRef.current.updateProjectionMatrix();
        renderer.setSize(window.innerWidth, window.innerHeight);
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('click', handleClick);
    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('click', handleClick);
      window.removeEventListener('resize', handleResize);
      renderer.dispose();
    };
  }, [onOrbClick]);

  return <canvas ref={canvasRef} className="fixed inset-0 z-0 pointer-events-none" />;
};

import React, { useState, useEffect, useRef } from 'react';
