// Global JSZip declaration for TypeScript
declare const JSZip: any;

const DEFAULT_CODE = `<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { 
      background: radial-gradient(circle at top, #1e1e2e, #0f0f1b);
      color: white; min-height: 100vh; display: flex; align-items: center; justify-content: center; overflow: hidden; font-family: sans-serif; 
    }
