      <p class="text-[9px] tracking-widest font-medium">60FPS SPATIAL ENGINE</p>
      <p class="text-[9px] tracking-widest font-medium">NEURAL ARCHITECTURE v2.5</p>
    </div>
  </div>
</body>
</html>`;

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_CODE);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [config, setConfig] = useState<AIConfig>({ temperature: 0.85, topP: 0.9, maxTokens: 4096 });
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isSidebarOpen, setSidebarOpen] = useState(false);
  const [isPuterReady, setIsPuterReady] = useState(false);
  const [isGenerating, setIsGenerating] = useState(false);
  const [notification, setNotification] = useState<{title: string, sub: string} | null>(null);

  const scrollContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const checkPuter = () => {
      if (window.puter) {
        setIsPuterReady(true);
      } else {
        setTimeout(checkPuter, 100);
      }
    };
    checkPuter();
  }, []);

  const showNotification = (title: string, sub: string) => {
    setNotification({ title, sub });
    setTimeout(() => setNotification(null), 4000);
  };

  const handleSendMessage = async (prompt: string) => {
    if (!isPuterReady || !prompt.trim() || isGenerating) return;

    const userMsg: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMsg]);
    setIsGenerating(true);

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      config: { ...config },
      timestamp: Date.now(),
      isStreaming: true,
    };

    setMessages(prev => [...prev, assistantMsg]);

    try {
      const stream = await window.puter.ai.chat(prompt, {
        model: activeModel,
        temperature: config.temperature,
        top_p: config.topP,
        max_tokens: config.maxTokens,
        stream: true
      });

      let fullContent = '';
      for await (const chunk of stream) {
        fullContent += chunk;
        setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent } : m));

        if (scrollContainerRef.current) {
          scrollContainerRef.current.scrollTop = scrollContainerRef.current.scrollHeight;
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false } : m));
    } catch (error: any) {
      console.error('AI error:', error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { 
        ...m, 
        content: `Connection Interrupted: ${error?.message || 'Neural link failed'}.`, 
        isStreaming: false 
      } : m));
    } finally {
      setIsGenerating(false);
    }
  };

  const downloadProject = async () => {
    showNotification('📦 Preparing Archive', 'Bundling spatial source code...');
    const zip = new JSZip();
    zip.file('index.html', code);
    zip.file('metadata.json', JSON.stringify({ name: "Vayu Export", description: "Generated via Cursor AI Edition" }));

    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = 'vayu-cursor-project.zip';
    link.click();
    URL.revokeObjectURL(url);
    showNotification('🎉 Project Exported', 'vayu-cursor-project.zip ready.');
  };

  const handleOrbClick = (type: string, name: string) => {
    switch (type) {
      case 'download':
        downloadProject();
        break;
      case 'ai-cursor':
        handleSendMessage("Execute Cursor AI inline optimization on the current source code. Make it smoother and more professional.");
        break;
      case 'agent':
        setActiveModel(name.toLowerCase().includes('claude') ? AIModel.CLAUDE : 
                       name.toLowerCase().includes('gemini') ? AIModel.GEMINI : 
                       name.toLowerCase().includes('deepseek') ? AIModel.DEEPSEEK : AIModel.GPT4);
        showNotification(`${name} Linked`, `Active model switched to ${name}.`);
        break;
      default:
        showNotification(name, `Type: ${type.toUpperCase()}`);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#020617] text-slate-100 overflow-hidden font-sans cursor-default">
      <AntigravityCanvas onOrbClick={handleOrbClick} />

      {notification && (
        <div className="fixed bottom-12 right-12 z-[100] glass-cursor px-8 py-4 rounded-2xl shadow-2xl ai-fadein max-w-sm pointer-events-none">
          <div className="font-bold text-lg mb-1">{notification.title}</div>
          <div className="text-sm opacity-70">{notification.sub}</div>
        </div>
      )}

      <Sidebar 
        isOpen={isSidebarOpen} 
        messages={messages} 
        onToggle={() => setSidebarOpen(false)}
      />

      <div className="flex-1 flex flex-col min-w-0 relative z-10">
        <Header 
          activeModel={activeModel} 
          onModelChange={setActiveModel}
          onToggleSidebar={() => setSidebarOpen(!isSidebarOpen)}
          isSidebarOpen={isSidebarOpen}
          config={config}
          onConfigChange={setConfig}
        />

        <div className="flex-1 flex flex-col overflow-hidden">
          {/* Main Feed Section (Upper Half) */}
          <div 
            ref={scrollContainerRef}
            className="flex-1 overflow-y-auto px-10 py-12 space-y-12 custom-scrollbar transition-all duration-500 ease-in-out"
          >
            <div className="max-w-4xl mx-auto w-full">
              <PromptComposer 
                onSend={handleSendMessage} 
                isGenerating={isGenerating} 
                activeModel={activeModel}
              />
            </div>

            <div className="max-w-4xl mx-auto w-full space-y-10">
              {messages.filter(m => m.role === 'assistant').map((msg) => (
                <div key={msg.id} className="ai-fadein">
                  <ResponseCard 
                    message={msg} 
                    onApply={(newCode) => {
                      setCode(newCode);
                      showNotification('Integrated', 'Code applied to IDE workspace.');
                    }}
                    onFork={() => handleSendMessage(`Iterate on this further: ${msg.content.substring(0, 40)}...`)}
                  />
                </div>
              ))}
            </div>
            <div className="h-48"></div>
          </div>

          {/* Vertical Columns Workspace (Lower Half) */}
          <div className="h-[48vh] border-t border-white/5 backdrop-blur-[64px] bg-black/40 flex shrink-0 relative overflow-hidden group/dock">
            {/* Ambient Shadow Overlay */}
            <div className="absolute inset-x-0 -top-12 h-12 bg-gradient-to-t from-black/40 to-transparent pointer-events-none z-10"></div>

            {/* Split View Columns */}
            <div className="flex w-full h-full p-6 gap-6 transition-all duration-700 ease-out transform">

              {/* Code Column (Left) */}
              <div className="flex-1 flex flex-col glass-cursor rounded-[2rem] overflow-hidden shadow-2xl group/editor transition-all duration-500 hover:scale-[1.002] hover:bg-white/[0.07]">
                <div className="px-6 py-3 bg-white/5 border-b border-white/5 flex items-center justify-between">
