                    <span className="text-[9px] font-black text-slate-400 uppercase tracking-[0.3em]">Source Engine</span>
                  </div>
                </div>
                <div className="flex-1 relative">
                  <Editor
                    height="100%"
                    defaultLanguage="html"
                    theme="vs-dark"
                    value={code}
                    onChange={(v) => setCode(v || '')}
                    options={{
                      minimap: { enabled: false },
                      fontSize: 13,
                      padding: { top: 20 },
                      backgroundColor: 'transparent',
                      fontFamily: "'Fira Code', monospace",
                      smoothScrolling: true,
                      lineNumbers: 'on',
                      renderLineHighlight: 'all',
                      scrollbar: { vertical: 'hidden', horizontal: 'hidden' },
                      cursorSmoothCaretAnimation: true,
                      cursorBlinking: 'smooth',
                      wordWrap: 'on',
                      overviewRulerLanes: 0,
                      hideCursorInOverviewRuler: true
                    }}
                  />
                </div>
              </div>

              {/* Preview Column (Right) */}
              <div className="flex-1 flex flex-col bg-white rounded-[2rem] border border-white/10 overflow-hidden shadow-[0_40px_100px_-20px_rgba(0,0,0,0.9)] transition-all duration-500 hover:scale-[1.002]">
                <div className="px-6 py-3 bg-slate-950 border-b border-white/5 flex items-center justify-between">
                  <div className="flex items-center gap-2">
                    <span className="text-[9px] font-black text-blue-400 uppercase tracking-[0.3em]">Holographic Output</span>
                  </div>
                  <div className="flex gap-1 opacity-20">
                    <div className="w-1.5 h-1.5 rounded-full bg-slate-400"></div>
                    <div className="w-1.5 h-1.5 rounded-full bg-slate-400"></div>
                    <div className="w-1.5 h-1.5 rounded-full bg-slate-400"></div>
                  </div>
                </div>
                <div className="flex-1 bg-white">
                  <Preview code={code} />
                </div>
              </div>

            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

