import React, { useState, useEffect, useRef } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { PromptComposer } from './components/PromptComposer';
import { ResponseCard } from './components/ResponseCard';
import { AntigravityCanvas } from './components/AntigravityCanvas';
import { AIModel, ChatMessage, AIConfig } from './types';

declare const Matter: any;
declare const JSZip: any;

const DEFAULT_CODE = `<!DOCTYPE html>
<html>
<head>
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { background: #000; color: #fff; height: 100vh; display: flex; align-items: center; justify-content: center; overflow: hidden; font-family: sans-serif; }
    .neon-text { font-size: 5rem; font-weight: 900; letter-spacing: -0.05em; text-shadow: 0 0 20px #3b82f6; }
  </style>
</head>
<body>
  <h1 class="neon-text">VAYU</h1>
</body>
</html>`;

const App: React.FC = () => {
  const [code, setCode] = useState<string>(DEFAULT_CODE);
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [isGenerating, setIsGenerating] = useState(false);
  const [gravityEnabled, setGravityEnabled] = useState(false);

  const engineRef = useRef<any>(null);
  const bodiesRef = useRef<{ [key: string]: any }>({});
  const containerRef = useRef<HTMLDivElement>(null);

  // Initialize Physics
  useEffect(() => {
    const { Engine, Render, Runner, Bodies, Composite, Mouse, MouseConstraint, Events } = Matter;

    const engine = Engine.create();
    engine.gravity.y = 0; // Default to Zero-G
    engineRef.current = engine;

    const width = window.innerWidth;
    const height = window.innerHeight;

    // Boundaries
    const ground = Bodies.rectangle(width / 2, height + 50, width, 100, { isStatic: true });
    const ceiling = Bodies.rectangle(width / 2, -50, width, 100, { isStatic: true });
    const leftWall = Bodies.rectangle(-50, height / 2, 100, height, { isStatic: true });
    const rightWall = Bodies.rectangle(width + 50, height / 2, 100, height, { isStatic: true });

    Composite.add(engine.world, [ground, ceiling, leftWall, rightWall]);

    // Mouse control
    const mouse = Mouse.create(document.body);
    const mouseConstraint = MouseConstraint.create(engine, {
      mouse: mouse,
      constraint: {
        stiffness: 0.2,
        render: { visible: false }
      }
    });
    Composite.add(engine.world, mouseConstraint);

    const runner = Runner.create();
    Runner.run(runner, engine);

    const updateLoop = () => {
      Object.entries(bodiesRef.current).forEach(([id, body]) => {
        const element = document.getElementById(id);
        if (element) {
          element.style.transform = `translate(${body.position.x - body.renderWidth / 2}px, ${body.position.y - body.renderHeight / 2}px) rotate(${body.angle}rad)`;
        }
      });
      requestAnimationFrame(updateLoop);
    };
    updateLoop();

    return () => {
      Engine.clear(engine);
      Runner.stop(runner);
    };
  }, []);

  // Panel Registration
  const registerPanel = (id: string, x: number, y: number, w: number, h: number) => {
    if (!engineRef.current || bodiesRef.current[id]) return;
    const { Bodies, Composite } = Matter;
    const body = Bodies.rectangle(x + w / 2, y + h / 2, w, h, {
      chamfer: { radius: 24 },
      restitution: 0.6,
      friction: 0.1,
      frictionAir: 0.05
    });
    body.renderWidth = w;
    body.renderHeight = h;
    bodiesRef.current[id] = body;
    Composite.add(engineRef.current.world, body);
  };

  const toggleGravity = () => {
    if (!engineRef.current) return;
    const newGravity = !gravityEnabled;
    setGravityEnabled(newGravity);
    engineRef.current.gravity.y = newGravity ? 1 : 0;

    // If floating, give them a little push
    if (!newGravity) {
      Object.values(bodiesRef.current).forEach(body => {
        Matter.Body.applyForce(body, body.position, {
          x: (Math.random() - 0.5) * 0.05,
          y: (Math.random() - 0.5) * 0.05
        });
      });
    }
  };

  const handleSendMessage = async (prompt: string) => {
    if (!window.puter || !prompt.trim() || isGenerating) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: prompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setIsGenerating(true);

    const assistantId = (Date.now() + 1).toString();
    try {
      const res = await window.puter.ai.chat(prompt, { model: 'gemini-2.0-flash', stream: true });
      let fullContent = '';
      for await (const chunk of res) {
        fullContent += chunk;
        setMessages(prev => {
          const exists = prev.find(m => m.id === assistantId);
          if (exists) return prev.map(m => m.id === assistantId ? { ...m, content: fullContent } : m);
          return [...prev, { id: assistantId, role: 'assistant', content: fullContent, timestamp: Date.now(), isStreaming: true }];
        });
      }
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false } : m));
    } catch (e) {
      console.error(e);
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="relative w-full h-screen overflow-hidden bg-black select-none">
      <AntigravityCanvas />

      {/* Physics Management Layer */}
      <div ref={containerRef} className="physics-container">

        {/* Header Panel */}
        <div 
          id="header-panel"
          className="glass-physics w-[400px] p-6 flex flex-col items-center gap-4 cursor-grab active:cursor-grabbing"
          ref={() => registerPanel('header-panel', window.innerWidth / 2 - 200, 100, 400, 120)}
        >
          <div className="flex items-center gap-4">
            <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-black text-xl">V</div>
            <h1 className="text-xl font-bold tracking-tighter">VAYU CODE</h1>
          </div>
          <button 
            onClick={toggleGravity}
            className={`px-6 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest transition-all ${gravityEnabled ? 'bg-red-500/20 text-red-400' : 'bg-blue-500/20 text-blue-400 border border-blue-500/30'}`}
          >
            {gravityEnabled ? 'Restore Gravity' : 'Antigravity Mode'}
          </button>
        </div>

        {/* Editor Panel */}
        <div 
          id="editor-panel"
          className="glass-physics w-[600px] h-[400px] flex flex-col overflow-hidden cursor-grab active:cursor-grabbing"
          ref={() => registerPanel('editor-panel', 100, 300, 600, 400)}
        >
          <div className="px-6 py-3 bg-white/5 border-b border-white/10 text-[9px] font-black uppercase tracking-widest opacity-50">Source Engine</div>
          <div className="flex-1 pointer-events-auto">
            <Editor
              height="100%"
              defaultLanguage="html"
              theme="vs-dark"
              value={code}
              onChange={(v) => setCode(v || '')}
              options={{ minimap: { enabled: false }, fontSize: 12, backgroundColor: 'transparent', padding: { top: 20 } }}
            />
          </div>
        </div>

        {/* Preview Panel */}
        <div 
          id="preview-panel"
          className="glass-physics w-[500px] h-[350px] flex flex-col overflow-hidden bg-white cursor-grab active:cursor-grabbing"
          ref={() => registerPanel('preview-panel', 800, 200, 500, 350)}
        >
          <div className="px-6 py-3 bg-slate-950 border-b border-white/10 text-[9px] font-black uppercase tracking-widest text-blue-400">Live Hologram</div>
          <div className="flex-1 pointer-events-auto">
            <Preview code={code} />
          </div>
        </div>

        {/* Prompt Panel */}
        <div 
          id="prompt-panel"
          className="glass-physics w-[450px] p-8 flex flex-col gap-6 cursor-grab active:cursor-grabbing"
          ref={() => registerPanel('prompt-panel', window.innerWidth / 2 - 225, window.innerHeight - 250, 450, 200)}
        >
          <textarea 
            placeholder="Ask AI to modify reality..."
            className="bg-transparent border-none outline-none text-xl font-light resize-none h-24 pointer-events-auto"
            onKeyDown={(e) => {
              if (e.key === 'Enter' && e.metaKey) handleSendMessage((e.target as any).value);
            }}
          />
          <div className="text-[9px] font-black uppercase tracking-[0.4em] opacity-30 text-center">Neural Uplink Ready</div>
        </div>

        {/* Message Cards (Dynamic) */}
        {messages.filter(m => m.role === 'assistant').map((msg, i) => {
          const id = `msg-${msg.id}`;
          return (
            <div 
              key={msg.id}
              id={id}
              className="glass-physics w-[350px] p-6 cursor-grab active:cursor-grabbing ai-fadein"
              ref={() => registerPanel(id, 50 + (i * 20), 50 + (i * 20), 350, 200)}
            >
              <div className="text-[10px] font-bold text-blue-400 mb-2 uppercase tracking-widest">Agent Result</div>
              <div className="text-xs opacity-70 line-clamp-4 leading-relaxed">{msg.content}</div>
              {msg.content.includes('```') && (
                <button 
                  onClick={() => {
                    const codeBlock = msg.content.match(/```(?:html)?([\s\S]*?)```/)?.[1];
                    if (codeBlock) setCode(codeBlock.trim());
                  }}
                  className="mt-4 w-full py-2 bg-blue-600 rounded-xl text-[10px] font-black uppercase tracking-widest pointer-events-auto"
                >
                  Apply Patch
                </button>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

export const AntigravityCanvas: React.FC = () => {
  const canvasRef = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    if (!canvasRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    const renderer = new THREE.WebGLRenderer({ canvas: canvasRef.current, antialias: true, alpha: true });

    renderer.setSize(window.innerWidth, window.innerHeight);
    camera.position.z = 50;

    // Stars
    const starGeo = new THREE.BufferGeometry();
    const starPos = [];
    for (let i = 0; i < 5000; i++) {
      starPos.push((Math.random() - 0.5) * 2000, (Math.random() - 0.5) * 2000, (Math.random() - 0.5) * 2000);
    }
    starGeo.setAttribute('position', new THREE.Float32BufferAttribute(starPos, 3));
    const starMat = new THREE.PointsMaterial({ color: 0xffffff, size: 0.7, transparent: true, opacity: 0.5 });
    const stars = new THREE.Points(starGeo, starMat);
    scene.add(stars);

    // Floating Grid
    const grid = new THREE.GridHelper(2000, 50, 0x3b82f6, 0x111111);
    grid.position.y = -100;
    scene.add(grid);

    const animate = () => {
      requestAnimationFrame(animate);
      stars.rotation.y += 0.0002;
      renderer.render(scene, camera);
    };
    animate();

    const handleResize = () => {
      camera.aspect = window.innerWidth / window.innerHeight;
      camera.updateProjectionMatrix();
      renderer.setSize(window.innerWidth, window.innerHeight);
    };
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, []);

  return <canvas ref={canvasRef} className="fixed inset-0 z-0 pointer-events-none" />;
};

