  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [isPreviewVisible, setIsPreviewVisible] = useState(true);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');

  const chatEndRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const handleSendMessage = async () => {
    if (!prompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const stream = await window.puter.ai.chat(prompt, {
        model: activeModel,
        stream: true
      });

      let fullContent = '';
      for await (const chunk of stream) {
        fullContent += chunk;
        setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent } : m));
      }
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false } : m));
    } catch (error) {
      console.error('AI Chat Error:', error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: 'Failed to generate response.', isStreaming: false } : m));
    } finally {
      setIsGenerating(false);
    }
  };

  const applyCode = (newCode: string) => {
    setCode(newCode);
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm">
      {/* Activity Bar (Narrow Left) */}
      <div className="w-12 flex flex-col items-center py-4 bg-[#05070a] border-r border-white/5 gap-4">
        <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-black text-white text-lg mb-4">V</div>
        <button 
          onClick={() => setActiveSidebarTab('chat')}
          className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-white/5' : 'text-slate-500 hover:text-slate-300'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
        </button>
        <button 
          onClick={() => setActiveSidebarTab('files')}
          className={`p-2 rounded-lg transition-colors ${activeSidebarTab === 'files' ? 'text-blue-400 bg-white/5' : 'text-slate-500 hover:text-slate-300'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
        </button>
      </div>

      {/* Sidebar (Chat / Explorer) */}
      <div className="w-80 flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 border-b border-white/5 font-bold uppercase tracking-widest text-[10px] text-slate-500 flex justify-between items-center">
          <span>{activeSidebarTab === 'chat' ? 'AI CHAT' : 'EXPLORER'}</span>
          <select 
            value={activeModel}
            onChange={(e) => setActiveModel(e.target.value as AIModel)}
            className="bg-transparent text-blue-400 outline-none cursor-pointer"
          >
            <option value={AIModel.GEMINI}>Gemini 2.0</option>
            <option value={AIModel.GPT4}>GPT-4o</option>
            <option value={AIModel.CLAUDE}>Claude 3.5</option>
          </select>
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden">
            <div className="flex-1 overflow-y-auto p-4 space-y-4 custom-scrollbar">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-6 text-slate-500 gap-4">
                  <div className="p-4 bg-white/5 rounded-2xl">
                    <svg className="w-10 h-10 opacity-20" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  </div>
                  <p className="text-xs">Ask Vayu to build, debug or refine your design.</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[90%] p-3 rounded-xl text-sm leading-relaxed ${
                    msg.role === 'user' ? 'ai-bubble-user text-slate-200' : 'ai-bubble-assistant text-slate-200'
                  }`}>
                    {msg.content.split('```')[0]}
                    {msg.content.includes('```') && (
                      <button 
                        onClick={() => {
                          const match = msg.content.match(/```(?:html|css|js)?([\s\S]*?)```/);
                          if (match) applyCode(match[1].trim());
                        }}
                        className="mt-3 w-full py-1.5 bg-blue-600/20 hover:bg-blue-600/40 text-blue-400 rounded-lg text-[10px] font-bold uppercase tracking-widest transition-all"
                      >
                        Apply Code Changes
                      </button>
                    )}
                  </div>
                  <span className="text-[9px] text-slate-600 uppercase tracking-tighter">
                    {msg.role === 'user' ? 'YOU' : msg.model?.split('-')[0].toUpperCase()} • {new Date(msg.timestamp).toLocaleTimeString([], {hour: '2-digit', minute:'2-digit'})}
                  </span>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            {/* Composer */}
            <div className="p-4 border-t border-white/5">
              <div className="relative cursor-input-glow transition-all bg-white/[0.03] border border-white/10 rounded-xl p-3">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSendMessage();
                    }
                  }}
                  placeholder="Ask Vayu..."
                  className="w-full bg-transparent outline-none resize-none text-sm min-h-[60px] max-h-[200px]"
                />
                <div className="flex justify-between items-center mt-2">
                  <span className="text-[9px] text-slate-600 font-bold uppercase tracking-widest">Shift+Enter for new line</span>
                  <button 
                    onClick={handleSendMessage}
                    disabled={isGenerating || !prompt.trim()}
                    className={`p-2 rounded-lg transition-all ${isGenerating || !prompt.trim() ? 'text-slate-700' : 'text-blue-500 hover:bg-blue-500/10'}`}
                  >
                    <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 5l7 7-7 7M5 5l7 7-7 7" /></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 p-4 text-slate-500 italic text-xs">Explorer functionality coming soon...</div>
        )}
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0">
        {/* Top Header */}
        <div className="h-10 px-4 flex items-center justify-between bg-[#0b0e14] border-b border-white/5">
          <div className="flex items-center gap-4">
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">index.html</span>
          </div>
          <div className="flex items-center gap-2">
            <button 
              onClick={() => setIsPreviewVisible(!isPreviewVisible)}
              className={`px-3 py-1 rounded text-[10px] font-bold uppercase transition-all ${isPreviewVisible ? 'bg-blue-500/10 text-blue-400' : 'bg-white/5 text-slate-500'}`}
            >
              {isPreviewVisible ? 'Hide Preview' : 'Show Preview'}
            </button>
          </div>
        </div>

        {/* Editor and Preview Split */}
        <div className="flex-1 flex overflow-hidden">
          {/* Editor Column */}
          <div className="flex-1 flex flex-col relative border-r border-white/5">
            <Editor
              height="100%"
              defaultLanguage="html"
              theme="vs-dark"
              value={code}
              onChange={(v) => setCode(v || '')}
              options={{
                minimap: { enabled: false },
                fontSize: 13,
                fontFamily: "'Fira Code', monospace",
                backgroundColor: '#0b0e14',
                padding: { top: 16 },
                lineNumbers: 'on',
                renderLineHighlight: 'all',
                scrollBeyondLastLine: false,
                automaticLayout: true,
              }}
            />
          </div>

          {/* Preview Column */}
          {isPreviewVisible && (
            <div className="flex-1 flex flex-col bg-white">
              <Preview code={code} />
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default App;

export enum AIModel {
  GEMINI = 'gemini-2.0-flash',
  GPT4 = 'gpt-4o',
  CLAUDE = 'claude-3.5-sonnet',
  DEEPSEEK = 'deepseek-v2',
  LLAMA = 'llama-3.1-70b'
}

export interface AIConfig {
  temperature: number;
  topP: number;
  maxTokens: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: AIModel;
  config?: AIConfig;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'idle';
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #020617;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
    }
    .glow { text-shadow: 0 0 20px rgba(59, 130, 246, 0.5); }
    .glass {
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 24px;
      padding: 3rem;
    }
  </style>
</head>
<body>
  <div class="glass text-center animate-pulse">
    <h1 class="text-6xl font-black mb-4 glow">VAYU</h1>
    <p class="text-blue-400 font-mono tracking-widest text-sm uppercase">Neural Project Interface</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  useEffect(() => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  const parseAndApplyFiles = (text: string) => {
    // Regex to find patterns like [FILE: path.ext] ```lang ... ```
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)```/g;
    let match;
    const newFiles = [...files];
    let changed = false;

    while ((match = fileRegex.exec(text)) !== null) {
      const path = match[1].trim();
      const content = match[2].trim();
      const language = path.split('.').pop() || 'plaintext';

      const existingIndex = newFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (newFiles[existingIndex].content !== content) {
          newFiles[existingIndex] = { path, content, language };
          changed = true;
        }
      } else {
        newFiles.push({ path, content, language });
        changed = true;
      }
    }

    if (changed) {
      setFiles(newFiles);
    }
  };

  const handleSendMessage = async () => {
    if (!prompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
      status: 'analyzing'
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemPrompt = `You are a high-performance web engineering agent. 
      When asked to build or modify a task:
      1. Briefly analyze the requirements.
      2. If files need to be created or updated, output them using the exact format:
         [FILE: filename.ext]
         \`\`\`language
         code content
         \`\`\`
      Always prioritize clean, modular code. Use index.html as the primary entry point.`;

      const stream = await window.puter.ai.chat(`${systemPrompt}\n\nTask: ${prompt}`, {
        model: activeModel,
        stream: true
      });

      let fullContent = '';
      let hasStartedCoding = false;

      for await (const chunk of stream) {
        fullContent += chunk;

        // Check if we've reached a file definition to switch status
        if (!hasStartedCoding && fullContent.includes('[FILE:')) {
          hasStartedCoding = true;
          setCurrentStatus('coding');
        }

        setMessages(prev => prev.map(m => m.id === assistantId ? { 
          ...m, 
          content: fullContent,
          status: hasStartedCoding ? 'coding' : 'analyzing'
        } : m));

        // Periodically parse to keep the UI in sync
        parseAndApplyFiles(fullContent);
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error) {
      console.error('AI Chat Error:', error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: 'Neural connection lost. Please retry.', isStreaming: false } : m));
      setCurrentStatus('idle');
    } finally {
      setIsGenerating(false);
    }
  };

  const getFullProjectPreview = () => {
    // Basic bundler: injects other files into index.html if possible
    // For this simple version, we assume index.html is the root and we just render it.
    // In a real IDE, we'd handle CSS/JS links.
    const indexFile = files.find(f => f.path === 'index.html') || INITIAL_FILES[0];
    return indexFile.content;
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm">
      {/* Activity Bar */}
      <div className="w-14 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-6">
        <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white text-xl mb-4 shadow-lg shadow-blue-900/20">V</div>
        <button 
          onClick={() => setActiveSidebarTab('chat')}
          className={`p-3 rounded-xl transition-all duration-300 ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_10px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
        </button>
        <button 
          onClick={() => setActiveSidebarTab('files')}
          className={`p-3 rounded-xl transition-all duration-300 ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_10px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}
        >
          <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
        </button>
      </div>

      {/* Sidebar */}
      <div className="w-80 flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden transition-all duration-500">
        <div className="p-4 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[10px] text-slate-500 flex justify-between items-center">
          <span>{activeSidebarTab === 'chat' ? 'Intelligence' : 'Filesystem'}</span>
          {activeSidebarTab === 'chat' && (
            <select 
              value={activeModel}
              onChange={(e) => setActiveModel(e.target.value as AIModel)}
              className="bg-transparent text-blue-400 outline-none cursor-pointer hover:text-blue-300 transition-colors"
            >
              <option value={AIModel.GEMINI}>Gemini 2.0</option>
              <option value={AIModel.GPT4}>GPT-4o</option>
              <option value={AIModel.CLAUDE}>Claude 3.5</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div className="flex-1 overflow-y-auto p-4 space-y-6 custom-scrollbar pb-32">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 text-slate-500 gap-6 opacity-40">
                  <div className="w-16 h-16 bg-white/5 rounded-3xl flex items-center justify-center animate-pulse">
                    <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1.5" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  </div>
                  <div className="space-y-2">
                    <p className="text-xs font-bold tracking-widest uppercase">Agent Standby</p>
                    <p className="text-[10px] leading-relaxed">Ready to generate components, full apps, or optimize architectures.</p>
                  </div>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-3 animate-fade-in ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-sm leading-relaxed transition-all duration-500 shadow-xl ${
                    msg.role === 'user' ? 'ai-bubble-user text-slate-100' : 'ai-bubble-assistant text-slate-200 glass-panel'
                  }`}>
                    {/* Status Indicator for Assistant */}
                    {msg.role === 'assistant' && msg.isStreaming && (
                      <div className="flex items-center gap-2 mb-3">
                        <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-ping"></div>
                        <span className="text-[9px] font-black uppercase tracking-widest text-blue-400">
                          {msg.status === 'analyzing' ? 'Analyzing Logic...' : 'Synthesizing Files...'}
                        </span>
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-light tracking-wide">
                      {msg.content.split('[FILE:')[0]}
                    </div>
                  </div>
                  <span className="text-[8px] text-slate-600 font-black uppercase tracking-[0.2em] px-2">
                    {msg.role === 'user' ? 'USER_UPLINK' : `MODEL_CORE // ${msg.model?.split('-')[0].toUpperCase()}`}
                  </span>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            {/* Composer */}
            <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent">
              <div className="relative cursor-input-glow transition-all bg-[#151921] border border-white/5 rounded-2xl p-4 shadow-2xl">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSendMessage();
                    }
                  }}
                  placeholder="Describe your vision..."
                  className="w-full bg-transparent outline-none resize-none text-sm min-h-[50px] max-h-[150px] placeholder:text-slate-600"
                />
                <div className="flex justify-between items-center mt-3 border-t border-white/5 pt-3">
                  <div className="flex gap-2">
                    <div className={`w-2 h-2 rounded-full transition-all duration-500 ${currentStatus === 'analyzing' ? 'bg-amber-500 shadow-[0_0_8px_#f59e0b]' : currentStatus === 'coding' ? 'bg-green-500 shadow-[0_0_8px_#22c55e]' : 'bg-slate-700'}`}></div>
                    <span className="text-[8px] text-slate-500 font-bold uppercase tracking-widest">
                      {currentStatus === 'idle' ? 'System Ready' : currentStatus.toUpperCase()}
                    </span>
                  </div>
                  <button 
                    onClick={handleSendMessage}
                    disabled={isGenerating || !prompt.trim()}
                    className={`flex items-center gap-2 px-4 py-1.5 rounded-lg transition-all duration-300 font-black text-[10px] uppercase tracking-widest ${isGenerating || !prompt.trim() ? 'bg-white/5 text-slate-700' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-lg shadow-blue-900/40'}`}
                  >
                    <span>{isGenerating ? 'Processing' : 'Transmit'}</span>
                    <svg className="w-3 h-3" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M13 5l7 7-7 7" /></svg>
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-2 custom-scrollbar">
            {files.map(file => (
              <button
                key={file.path}
                onClick={() => setActiveFilePath(file.path)}
                className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-xs transition-all duration-200 group ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border border-blue-400/20 shadow-lg shadow-blue-900/10' : 'hover:bg-white/5 text-slate-400'}`}
              >
                <svg className={`w-4 h-4 transition-transform duration-300 ${activeFilePath === file.path ? 'scale-110' : 'opacity-40'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                </svg>
                <span className="flex-1 text-left truncate font-medium">{file.path}</span>
