      const existingIndex = currentFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (currentFiles[existingIndex].content !== content) {
          currentFiles[existingIndex] = { ...currentFiles[existingIndex], content };
          hasUpdates = true;
        }
      } else {
        currentFiles.push({ path, content, language });
        hasUpdates = true;
      }
    }

