        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.25em] text-[10px] text-slate-500 flex justify-between items-center">
          <span className="flex items-center gap-2">
             <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse"></div>
             {activeSidebarTab === 'chat' ? 'Neural Link' : 'Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select 
              value={activeModel}
              onChange={(e) => setActiveModel(e.target.value as AIModel)}
              className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none"
            >
              <option value={AIModel.GEMINI}>Gemini 2.0</option>
              <option value={AIModel.GPT4}>GPT-4o</option>
              <option value={AIModel.CLAUDE}>Claude 3.5</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-32">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 text-slate-500 gap-6 opacity-40">
                  <div className="w-20 h-20 bg-white/5 rounded-[2rem] flex items-center justify-center border border-white/10">
                    <svg className="w-10 h-10" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  </div>
                  <div className="space-y-2">
                    <p className="text-[11px] font-black tracking-widest uppercase">System Standby</p>
                    <p className="text-[10px] leading-relaxed">Ready to engineer your requirements.</p>
                  </div>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] leading-relaxed shadow-xl ${
                    msg.role === 'user' ? 'bg-blue-600 text-white' : 'bg-[#151921] text-slate-200 border border-white/5'
                  }`}>
                    {msg.role === 'assistant' && msg.isStreaming && (
                      <div className="flex items-center gap-2 mb-2">
                        <div className={`w-1.5 h-1.5 rounded-full animate-ping ${msg.status === 'analyzing' ? 'bg-amber-400' : 'bg-green-400'}`}></div>
                        <span className={`text-[9px] font-black uppercase tracking-widest ${msg.status === 'analyzing' ? 'text-amber-400' : 'text-green-400'}`}>
                          {msg.status === 'analyzing' ? 'Thinking' : 'Synthesizing'}
                        </span>
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-light tracking-wide">
                      {msg.content.split('[FILE:')[0].trim()}
                    </div>
                  </div>
                  <span className="text-[8px] text-slate-600 font-black uppercase tracking-[0.2em] px-2">
                    {msg.role === 'user' ? 'User' : 'Vayu'}
                  </span>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-5 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent">
              <div className="relative bg-[#1a1f29] border border-white/10 rounded-2xl p-4 shadow-2xl">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSendMessage();
                    }
                  }}
                  placeholder="Ask Vayu to build..."
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[150px] placeholder:text-slate-600"
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full transition-all duration-500 ${currentStatus === 'analyzing' ? 'bg-amber-400' : currentStatus === 'coding' ? 'bg-green-400' : 'bg-slate-700'}`}></div>
                    <span className="text-[9px] text-slate-500 font-black uppercase tracking-widest">{currentStatus}</span>
                  </div>
                  <button 
                    onClick={handleSendMessage}
                    disabled={isGenerating || !prompt.trim()}
                    className={`px-5 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${isGenerating || !prompt.trim() ? 'opacity-30' : 'bg-blue-600 hover:bg-blue-500 text-white active:scale-95'}`}
                  >
                    {isGenerating ? 'Working...' : 'Submit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1 custom-scrollbar">
            {files.map(file => (
              <button
                key={file.path}
                onClick={() => setActiveFilePath(file.path)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs transition-all duration-200 relative border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/30' : 'hover:bg-white/5 text-slate-400 border-transparent'}`}
              >
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-600'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                </svg>
                <span className="flex-1 text-left truncate font-bold">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Content Workspace */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-[0.2em]">{activeFile.path}</span>
            <span className="text-[10px] text-slate-600 font-mono italic">Ready</span>
          </div>
          <div className="flex items-center gap-2">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
             <span className="text-[9px] font-black text-green-500 uppercase tracking-widest">Neural Sync</span>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          {/* Editor */}
          <div className="flex-1 flex flex-col border-r border-white/5 relative">
            <Editor
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              onChange={(v) => {
                const newFiles = [...files];
                const index = newFiles.findIndex(f => f.path === activeFilePath);
                if (index > -1) {
                  newFiles[index].content = v || '';
                  setFiles(newFiles);
                }
              }}
              options={{
                minimap: { enabled: false },
                fontSize: 14,
                fontFamily: "'Fira Code', monospace",
                backgroundColor: '#0b0e14',
                padding: { top: 20 },
                lineNumbers: 'on',
                automaticLayout: true,
                cursorBlinking: 'smooth',
                smoothScrolling: true,
                renderLineHighlight: 'all',
                scrollbar: { vertical: 'hidden', horizontal: 'hidden' }
              }}
            />
          </div>

          {/* Preview */}
          <div className="flex-1 flex flex-col bg-white">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .glow { text-shadow: 0 0 20px rgba(59, 130, 246, 0.5); }
    .glass {
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 24px;
      padding: 3rem;
      text-align: center;
    }
  </style>
</head>
<body>
  <div class="glass animate-in fade-in zoom-in duration-700">
    <h1 class="text-7xl font-black mb-4 glow tracking-tighter">VAYU</h1>
    <p class="text-blue-400 font-mono tracking-[0.3em] text-xs uppercase opacity-80">Neural Project Interface</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [showScrollButton, setShowScrollButton] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';

    let bundled = index;
    if (style && bundled.includes('</head>')) {
      bundled = bundled.replace('</head>', `<style>${style}</style></head>`);
    } else if (style) {
       bundled = `<style>${style}</style>` + bundled;
    }

    if (script && bundled.includes('</body>')) {
      bundled = bundled.replace('</body>', `<script>${script}</script></body>`);
    } else if (script) {
      bundled = bundled + `<script>${script}</script>`;
    }
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isGenerating]);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    setShowScrollButton(scrollHeight - scrollTop - clientHeight > 100);
  };

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)```/g;
    let match;
    let newFiles = [...files];
    let hasUpdates = false;

    while ((match = fileRegex.exec(text)) !== null) {
      const path = match[1].trim();
      const content = match[2].trim();
      const language = path.split('.').pop() || 'plaintext';

      const existingIndex = newFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (newFiles[existingIndex].content !== content) {
          newFiles[existingIndex] = { ...newFiles[existingIndex], content };
          hasUpdates = true;
        }
      } else {
        newFiles.push({ path, content, language });
        hasUpdates = true;
      }
    }

    if (hasUpdates) {
      setFiles(newFiles);
    }
  };

  const handleSendMessage = async () => {
    if (!prompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: prompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
      status: 'analyzing'
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const chatHistory = messages.slice(-10).map(m => `${m.role === 'user' ? 'User' : 'Vayu'}: ${m.content}`).join('\n');

      const systemInstruction = `You are Vayu, a world-class AI Software Engineer powered by Puter.js.
      You have deep access to Puter's cloud capabilities: puter.ai, puter.fs, puter.kv, and puter.auth.

      CRITICAL OPERATION RULES:
      1. Analyze the project comprehensively before coding.
      2. You MUST use this precise multi-file output format:
         [FILE: path/filename.ext]
         \`\`\`language
         code
         \`\`\`
      3. Always update index.html to reflect new scripts or styles.
      4. If user asks for complex data storage, mention puter.kv. If for user accounts, mention puter.auth.
      5. Deliver production-ready, highly aesthetic code.`;

      const stream = await window.puter.ai.chat(`${systemInstruction}\n\nPROJECT_STATE:\n${files.map(f => f.path).join(', ')}\n\nHISTORY:\n${chatHistory}\n\nTASK: ${prompt}`, {
        model: activeModel,
        stream: true
      });

      let fullContent = '';
      let detectedCoding = false;

      for await (const chunk of stream) {
        fullContent += chunk;

        if (!detectedCoding && (fullContent.includes('[FILE:') || fullContent.includes('```'))) {
          detectedCoding = true;
          setCurrentStatus('coding');
        }

        setMessages(prev => prev.map(m => m.id === assistantId ? { 
          ...m, 
          content: fullContent,
          status: detectedCoding ? 'coding' : 'analyzing'
        } : m));

        if (detectedCoding) {
           parseAndApplyFiles(fullContent);
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error) {
      console.error('Core Logic Failure:', error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: 'Neural link synchronization failed. Please re-establish uplink.', isStreaming: false } : m));
      setCurrentStatus('idle');
    } finally {
      setIsGenerating(false);
    }
  };

  const handleOpenSearch = () => {
    window.open('https://spark-ai-search.pages.dev/', '_blank');
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 hover:scale-105 transition-transform cursor-pointer">V</div>
        <div className="flex flex-col gap-4">
          <button 
            onClick={() => setActiveSidebarTab('chat')}
            className={`p-3 rounded-xl transition-all duration-300 ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}
            title="Intelligence Chat"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button 
            onClick={() => setActiveSidebarTab('files')}
            className={`p-3 rounded-xl transition-all duration-300 ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}
            title="Filesystem Explorer"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <button 
            onClick={handleOpenSearch}
            className="p-3 rounded-xl transition-all duration-300 text-slate-500 hover:text-blue-400 hover:bg-blue-400/10"
            title="Neural Search"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Content */}
      <div className="w-80 flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.25em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Link' : 'Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select 
              value={activeModel}
              onChange={(e) => setActiveModel(e.target.value as AIModel)}
              className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10 transition-colors"
            >
              <option value={AIModel.GEMINI}>Gemini 2.0</option>
              <option value={AIModel.GPT4}>GPT-4o</option>
              <option value={AIModel.CLAUDE}>Claude 3.5</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div 
              ref={chatContainerRef}
              onScroll={handleScroll}
              className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-32 scroll-smooth"
            >
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 text-slate-500 gap-6 opacity-40 animate-pulse">
                  <div className="w-20 h-20 bg-blue-500/5 rounded-[2.5rem] flex items-center justify-center border border-blue-500/10 shadow-2xl shadow-blue-500/5">
                    <svg className="w-10 h-10 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="1" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                  </div>
                  <div className="space-y-3">
                    <p className="text-[11px] font-black tracking-widest uppercase">System Standby</p>
                    <p className="text-[10px] leading-relaxed max-w-[180px]">Vayu is ready. Describe the software architecture you want to build.</p>
                  </div>
                </div>
              )}
              {messages.map((msg, idx) => (
                <div 
                  key={msg.id} 
                  className={`flex flex-col gap-2 animate-fade-in ${msg.role === 'user' ? 'items-end' : 'items-start'}`}
                  style={{ animationDelay: `${idx * 0.05}s` }}
                >
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] leading-relaxed shadow-2xl border transition-all duration-300 ${
                    msg.role === 'user' 
                      ? 'bg-blue-600/90 text-white border-blue-400/30' 
                      : 'bg-[#151921]/80 backdrop-blur-xl text-slate-200 border-white/5'
                  }`}>
                    {msg.role === 'assistant' && msg.isStreaming && (
                      <div className="flex items-center gap-2 mb-3 px-1">
                        <div className={`w-1.5 h-1.5 rounded-full animate-ping ${msg.status === 'analyzing' ? 'bg-amber-400' : 'bg-green-400'}`}></div>
                        <span className={`text-[10px] font-black uppercase tracking-widest ${msg.status === 'analyzing' ? 'text-amber-400' : 'text-green-400'}`}>
                          {msg.status === 'analyzing' ? 'Analyzing requirements' : 'Synthesizing code'}
                        </span>
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-light tracking-wide">
                      {msg.content.split('[FILE:')[0].trim()}
                    </div>
                  </div>
                  <span className="text-[8px] text-slate-600 font-black uppercase tracking-[0.2em] px-2 flex items-center gap-1">
                    {msg.role === 'user' ? (
                      <>
                        <svg className="w-2 h-2" fill="currentColor" viewBox="0 0 20 20"><path fillRule="evenodd" d="M10 9a3 3 0 100-6 3 3 0 000 6zm-7 9a7 7 0 1114 0H3z" clipRule="evenodd"/></svg>
                        Uplink User
                      </>
                    ) : (
                      <>
                        <svg className="w-2 h-2 text-blue-500" fill="currentColor" viewBox="0 0 20 20"><path d="M11 3a1 1 0 10-2 0v1a1 1 0 102 0V3zM5.884 6.924a1 1 0 10-1.414-1.414l-.707.707a1 1 0 101.414 1.414l.707-.707zm11.314 0a1 1 0 00-1.414-1.414l-.707.707a1 1 0 101.414 1.414l.707-.707zM5 11a1 1 0 11-2 0 1 1 0 012 0zm12 1a1 1 0 100-2 1 1 0 000 2zM8.94 17.874a1 1 0 101.415 0 1 1 0 00-1.415 0zM5.884 17.076a1 1 0 10-1.414 1.414l.707.707a1 1 0 101.414-1.414l-.707-.707zm11.314 0a1 1 0 01-1.414 1.414l-.707-.707a1 1 0 111.414-1.414l.707.707z"/></svg>
                        Vayu Core
                      </>
                    )}
                  </span>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            {/* Scroll Down Button */}
            {showScrollButton && (
              <button 
                onClick={scrollToBottom}
                className="absolute bottom-32 left-1/2 -translate-x-1/2 p-2 bg-blue-600 rounded-full shadow-2xl border border-blue-400/50 hover:bg-blue-500 transition-all animate-bounce z-10"
              >
                <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 14l-7 7-7-7" /></svg>
              </button>
            )}

            {/* Composer Area */}
            <div className="absolute bottom-0 left-0 right-0 p-5 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent">
              <div className="relative bg-[#1a1f29] border border-white/10 rounded-2xl p-4 shadow-2xl focus-within:ring-2 focus-within:ring-blue-500/20 transition-all">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === 'Enter' && !e.shiftKey) {
                      e.preventDefault();
                      handleSendMessage();
                    }
                  }}
                  placeholder="Ask Vayu to build..."
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[150px] placeholder:text-slate-600 font-light"
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full transition-all duration-700 ${currentStatus === 'analyzing' ? 'bg-amber-400 shadow-[0_0_12px_#fbbf24]' : currentStatus === 'coding' ? 'bg-green-400 shadow-[0_0_12px_#4ade80]' : 'bg-slate-700'}`}></div>
                    <span className="text-[9px] text-slate-500 font-black uppercase tracking-widest">{currentStatus === 'idle' ? 'Ready' : currentStatus}</span>
                  </div>
                  <button 
                    onClick={handleSendMessage}
                    disabled={isGenerating || !prompt.trim()}
                    className={`px-5 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed' : 'bg-blue-600 hover:bg-blue-500 text-white shadow-xl shadow-blue-500/20 active:scale-95'}`}
                  >
                    {isGenerating ? 'Synthesizing...' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1 custom-scrollbar">
            {files.map(file => (
              <button
                key={file.path}
                onClick={() => setActiveFilePath(file.path)}
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs transition-all duration-200 relative border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/30' : 'hover:bg-white/5 text-slate-400 border-transparent'}`}
              >
                <div className={`w-1 h-5 absolute left-0 rounded-r-full bg-blue-500 transition-opacity ${activeFilePath === file.path ? 'opacity-100' : 'opacity-0'}`}></div>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-600'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" />
                </svg>
                <span className="flex-1 text-left truncate font-bold tracking-tight">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Workspace */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5">
          <div className="flex items-center gap-6">
            <div className="flex items-center gap-3">
              <span className="text-[11px] font-black text-blue-400 uppercase tracking-[0.2em]">{activeFile.path}</span>
              <div className="px-2 py-0.5 bg-white/5 rounded text-[8px] font-black text-slate-500 uppercase tracking-widest">{activeFile.language}</div>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 px-3 py-1 bg-green-500/5 border border-green-500/10 rounded-full">
               <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
               <span className="text-[9px] font-black text-green-500 uppercase tracking-widest">Environment Synced</span>
             </div>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          {/* Code Editor */}
          <div className="flex-1 flex flex-col border-r border-white/5 relative bg-[#0b0e14]">
            <Editor
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              onChange={(v) => {
                const newFiles = [...files];
                const index = newFiles.findIndex(f => f.path === activeFilePath);
                if (index > -1) {
                  newFiles[index].content = v || '';
                  setFiles(newFiles);
                }
              }}
              options={{
                minimap: { enabled: false },
                fontSize: 14,
                fontFamily: "'Fira Code', monospace",
                backgroundColor: '#0b0e14',
                padding: { top: 24 },
                lineNumbers: 'on',
                glyphMargin: false,
                folding: true,
                lineDecorationsWidth: 0,
                lineNumbersMinChars: 3,
                automaticLayout: true,
                cursorBlinking: 'smooth',
                smoothScrolling: true,
                renderLineHighlight: 'all',
                scrollbar: {
                  vertical: 'hidden',
                  horizontal: 'hidden'
                }
              }}
            />
          </div>

          {/* Live Preview Pane */}
          <div className="flex-1 flex flex-col bg-white">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

export enum AIModel {
  GEMINI_PRO = 'gemini-2.0-flash',
  GPT_O4 = 'gpt-4o',
  CLAUDE_3_7 = 'claude-3-7-sonnet',
  DEEPSEEK_V3 = 'deepseek-v3',
  CODEX = 'code-llama-34b',
}

export interface AIConfig {
  temperature: number;
  topP: number;
  maxTokens: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: string;
  config?: AIConfig;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'idle';
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
    JSZip: any;
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .glow { text-shadow: 0 0 20px rgba(59, 130, 246, 0.5); }
    .glass {
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(12px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 24px;
      padding: 3rem;
      text-align: center;
    }
  </style>
</head>
<body>
  <div class="glass animate-in fade-in zoom-in duration-700">
    <h1 class="text-7xl font-black mb-4 glow tracking-tighter">VAYU</h1>
    <p class="text-blue-400 font-mono tracking-[0.3em] text-xs uppercase opacity-80">Neural IDE</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_PRO);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [showScrollButton, setShowScrollButton] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';

    let bundled = index;
    if (style) {
      if (bundled.includes('</head>')) {
        bundled = bundled.replace('</head>', `<style>${style}</style></head>`);
      } else {
        bundled = `<style>${style}</style>` + bundled;
      }
    }

    if (script) {
      if (bundled.includes('</body>')) {
        bundled = bundled.replace('</body>', `<script>${script}</script></body>`);
      } else {
        bundled = bundled + `<script>${script}</script>`;
      }
    }
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isGenerating]);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    setShowScrollButton(scrollHeight - scrollTop - clientHeight > 100);
  };

  const scrollToBottom = () => {
    chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  const handleCopyCode = (code: string) => {
    navigator.clipboard.writeText(code);
  };

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => {
      zip.file(f.path, f.content);
    });
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `vayu-project-${Date.now()}.zip`;
    link.click();
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)```/g;
    let match;
    let newFiles = [...files];
    let hasUpdates = false;

    while ((match = fileRegex.exec(text)) !== null) {
      const path = match[1].trim();
      const content = match[2].trim();
      const language = path.split('.').pop() || 'plaintext';

      const existingIndex = newFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (newFiles[existingIndex].content !== content) {
          newFiles[existingIndex] = { ...newFiles[existingIndex], content };
          hasUpdates = true;
        }
      } else {
        newFiles.push({ path, content, language });
        hasUpdates = true;
      }
    }

    if (hasUpdates) {
      setFiles(newFiles);
    }
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: currentPrompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
      status: 'analyzing'
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemInstruction = `You are Vayu, a world-class AI Software Engineer powered by Puter.js.
      Puter capabilities: puter.ai (chat/logic), puter.fs (cloud files), puter.kv (db), puter.auth (users).

      FORMATTING RULES:
      1. Explain your approach briefly.
      2. Provide FULL file content using the block format:
         [FILE: path/filename.ext]
         \`\`\`language
         code content
         \`\`\`
      3. Update index.html, style.css, and script.js as needed for the GUI to render correctly.
      4. Support multi-file project structures automatically.`;

      const stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, {
        model: activeModel,
        stream: true
      });

      let fullContent = '';
      let detectedCoding = false;

      for await (const chunk of stream) {
        fullContent += chunk;
        if (!detectedCoding && (fullContent.includes('[FILE:') || fullContent.includes('```'))) {
          detectedCoding = true;
          setCurrentStatus('coding');
        }
        setMessages(prev => prev.map(m => m.id === assistantId ? { 
          ...m, 
          content: fullContent,
          status: detectedCoding ? 'coding' : 'analyzing'
        } : m));
        if (detectedCoding) parseAndApplyFiles(fullContent);
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error) {
      console.error(error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: 'Error in synthesis.', isStreaming: false } : m));
      setCurrentStatus('idle');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-blue-600 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-inner' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <button onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')} className="p-3 rounded-xl transition-all text-slate-500 hover:text-blue-400 hover:bg-blue-400/10">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
          <button onClick={handleDownload} className="p-3 rounded-xl transition-all text-slate-500 hover:text-green-400 hover:bg-green-400/10" title="Download Zip">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Content */}
      <div className="w-96 flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Network' : 'Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select 
              value={activeModel}
              onChange={(e) => setActiveModel(e.target.value)}
              className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10"
            >
              <option value={AIModel.GEMINI_PRO}>Gemini 2.0</option>
              <option value={AIModel.CLAUDE_3_7}>Claude 3.7</option>
              <option value={AIModel.GPT_O4}>GPT o4</option>
              <option value={AIModel.DEEPSEEK_V3}>DeepSeek V3</option>
              <option value={AIModel.CODEX}>Codex</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} onScroll={handleScroll} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-32">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 text-slate-500 opacity-40 animate-pulse">
                  <div className="w-16 h-16 bg-blue-500/5 rounded-2xl flex items-center justify-center border border-blue-500/10 mb-4">
                    <svg className="w-8 h-8 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <p className="text-[10px] font-black uppercase tracking-widest">Awaiting Command</p>
                </div>
              )}
              {messages.map((msg, idx) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-2xl border transition-all ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30' : 'bg-[#151921] text-slate-200 border-white/5'
                  }`}>
                    {msg.role === 'assistant' && msg.isStreaming && (
                      <div className="flex items-center gap-2 mb-3 text-[10px] font-black uppercase text-blue-400">
                        <div className="w-1.5 h-1.5 rounded-full bg-blue-400 animate-ping"></div>
                        {msg.status}
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-light">
                      {msg.content.split('[FILE:')[0].split('```').map((part, pIdx) => {
                        if (pIdx % 2 === 1) { // This is a code block
                          return (
                            <div key={pIdx} className="my-3 rounded-lg overflow-hidden bg-black/40 border border-white/5 group relative">
                              <div className="flex justify-between items-center px-3 py-1.5 bg-white/5 border-b border-white/5">
                                <span className="text-[9px] uppercase font-black text-slate-500 tracking-widest">Snippet</span>
                                <div className="flex gap-2">
                                  <button onClick={() => handleCopyCode(part)} className="p-1 hover:text-blue-400 transition-colors" title="Copy">
                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" /></svg>
                                  </button>
                                  <button onClick={() => handleSendMessage(`Explain this code: ${part}`)} className="p-1 hover:text-amber-400 transition-colors" title="Debug">
                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 8v4m0 4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
                                  </button>
                                </div>
                              </div>
                              <pre className="p-3 text-[11px] font-mono overflow-x-auto custom-scrollbar text-blue-100"><code>{part}</code></pre>
                            </div>
                          );
                        }
                        return part;
                      })}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            {showScrollButton && (
              <button onClick={scrollToBottom} className="absolute bottom-32 left-1/2 -translate-x-1/2 p-2 bg-blue-600 rounded-full shadow-2xl border border-blue-400 animate-bounce">
                <svg className="w-4 h-4 text-white" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="3" d="M19 14l-7 7-7-7" /></svg>
              </button>
            )}

            <div className="absolute bottom-0 left-0 right-0 p-5 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent">
              <div className="bg-[#1a1f29] border border-white/10 rounded-2xl p-4 shadow-2xl ring-1 ring-white/5">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                  placeholder="Describe your software..."
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[150px] placeholder:text-slate-700"
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest">{currentStatus}</span>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-5 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${isGenerating ? 'opacity-20' : 'bg-blue-600 text-white hover:bg-blue-500'}`}>
                    Transmit
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs transition-all relative border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/30' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <div className={`w-1 h-5 absolute left-0 rounded-r-full bg-blue-500 ${activeFilePath === file.path ? 'opacity-100' : 'opacity-0'}`}></div>
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-bold">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Workspace */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5">
          <div className="flex items-center gap-3">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            <div className="px-2 py-0.5 bg-blue-500/10 rounded text-[8px] font-black text-blue-400 uppercase">{activeFile.language}</div>
          </div>
          <div className="flex items-center gap-4 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10">
            <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
            Environment Synced
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 flex flex-col border-r border-white/5 bg-[#0b0e14]">
            <Editor
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              onChange={(v) => {
                const newFiles = [...files];
                const index = newFiles.findIndex(f => f.path === activeFilePath);
                if (index > -1) {
                  newFiles[index].content = v || '';
                  setFiles(newFiles);
                }
              }}
              options={{ minimap: { enabled: false }, fontSize: 14, fontFamily: "'Fira Code', monospace", backgroundColor: '#0b0e14', padding: { top: 24 }, lineNumbers: 'on', cursorBlinking: 'smooth', automaticLayout: true }}
            />
          </div>
          <div className="flex-1 flex flex-col bg-white">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

