                  <p className="text-[10px] leading-relaxed max-w-[220px]">Define the logic and aesthetics of your next cloud application.</p>
                </div>
              )}
              {messages.map((msg, idx) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-2xl border transition-all duration-500 ${
