                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                  placeholder="Ask Vayu to design and code..."
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[160px] placeholder:text-slate-700 font-light"
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full transition-all duration-700 ${currentStatus === 'analyzing' ? 'bg-amber-400 shadow-[0_0_10px_#fbbf24]' : currentStatus === 'coding' ? 'bg-green-400 shadow-[0_0_10px_#4ade80]' : 'bg-slate-700'}`}></div>
                    <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20 active:scale-95'}`}>
                    {isGenerating ? 'Synthesizing...' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1 custom-scrollbar">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs transition-all relative border group ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/30' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <div className={`w-1 h-5 absolute left-0 rounded-r-full bg-blue-500 transition-opacity ${activeFilePath === file.path ? 'opacity-100' : 'opacity-0'}`}></div>
                <svg className={`w-4 h-4 transition-colors ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700 group-hover:text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" />
                </svg>
                <span className="flex-1 text-left truncate font-bold tracking-tight">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Workspace */}
      <div className="flex-1 flex flex-col min-w-0">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5">
          <div className="flex items-center gap-4">
            <div className="flex items-center gap-3">
              <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
              <div className="px-2 py-0.5 bg-blue-500/10 rounded text-[8px] font-black text-blue-400 uppercase tracking-tighter">{activeFile.language}</div>
            </div>
          </div>
          <div className="flex items-center gap-4">
             <div className="flex items-center gap-2 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10 shadow-inner">
               <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_#10b981]"></div>
               Neural Sync Active
             </div>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 flex flex-col border-r border-white/5 bg-[#0b0e14] relative">
            <Editor
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              onChange={(v) => {
                const newFiles = [...files];
                const index = newFiles.findIndex(f => f.path === activeFilePath);
                if (index > -1) {
                  newFiles[index].content = v || '';
                  setFiles(newFiles);
                }
              }}
              options={{
                minimap: { enabled: false },
                fontSize: 14,
                fontFamily: "'Fira Code', monospace",
                backgroundColor: '#0b0e14',
                padding: { top: 24 },
                lineNumbers: 'on',
                cursorBlinking: 'smooth',
                automaticLayout: true,
                smoothScrolling: true,
                cursorSmoothCaretAnimation: true,
                renderLineHighlight: 'all',
                scrollbar: {
                  vertical: 'hidden',
                  horizontal: 'hidden'
                }
              }}
            />
          </div>
          <div className="flex-1 flex flex-col bg-white overflow-hidden shadow-2xl">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .vayu-container {
      position: relative;
      padding: 4rem;
      border-radius: 2rem;
      background: rgba(255, 255, 255, 0.02);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.05em;
      filter: drop-shadow(0 0 15px rgba(59, 130, 246, 0.3));
    }
    .pulse-dot {
      width: 8px;
      height: 8px;
      background: #3b82f6;
      border-radius: 50%;
      animation: pulse 2s infinite;
    }
    @keyframes pulse {
      0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.7); }
      70% { transform: scale(1); box-shadow: 0 0 0 10px rgba(59, 130, 246, 0); }
      100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0); }
    }
  </style>
</head>
<body>
  <div class="vayu-container">
    <h1 class="vayu-logo">VAYU</h1>
    <div class="flex items-center gap-3 justify-center mt-4">
      <div class="pulse-dot"></div>
      <span class="text-xs font-mono uppercase tracking-widest text-slate-500">Neural Environment Active</span>
    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.CLAUDE_3_7);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [showScrollButton, setShowScrollButton] = useState(false);
  const [isPuterAuth, setIsPuterAuth] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  // Check Auth on Mount
  useEffect(() => {
    const checkAuth = async () => {
      if (window.puter) {
        const signedIn = await window.puter.auth.isSignedIn();
        setIsPuterAuth(signedIn);
      }
    };
    checkAuth();
  }, []);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';

    let bundled = index;
    if (style) {
      bundled = bundled.includes('</head>') 
        ? bundled.replace('</head>', `<style>${style}</style></head>`)
        : `<style>${style}</style>` + bundled;
    }
    if (script) {
      bundled = bundled.includes('</body>')
        ? bundled.replace('</body>', `<script>${script}</script></body>`)
        : bundled + `<script>${script}</script>`;
    }
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isGenerating]);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    setShowScrollButton(scrollHeight - scrollTop - clientHeight > 100);
  };

  const scrollToBottom = () => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });

  const handleCopyCode = (code: string) => navigator.clipboard.writeText(code);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `vayu-project-${Date.now()}.zip`;
    link.click();
  };

  const handleAuth = async () => {
    try {
      await window.puter.auth.signIn();
      setIsPuterAuth(true);
    } catch (e) {
      console.error("Auth failed", e);
    }
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)```/g;
    let match;
    let newFiles = [...files];
    let hasUpdates = false;

    while ((match = fileRegex.exec(text)) !== null) {
      const path = match[1].trim();
      const content = match[2].trim();
      const language = path.split('.').pop() || 'plaintext';

      const existingIndex = newFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (newFiles[existingIndex].content !== content) {
          newFiles[existingIndex] = { ...newFiles[existingIndex], content };
          hasUpdates = true;
        }
      } else {
        newFiles.push({ path, content, language });
        hasUpdates = true;
      }
    }
    if (hasUpdates) setFiles(newFiles);
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    if (!isPuterAuth) {
      await handleAuth();
      if (!await window.puter.auth.isSignedIn()) return;
    }

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: currentPrompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
      status: 'analyzing'
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemInstruction = `You are Vayu, a cloud-native AI IDE powered by Puter.js.
      Integrate: puter.ai, puter.fs, puter.kv, puter.auth.
      Format: [FILE: path/filename.ext] \`\`\`language code \`\`\`.`;

      let stream;
      try {
        console.log(`Uplink to Puter: ${activeModel}`);
        stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, {
          model: activeModel,
          stream: true
        });
      } catch (err: any) {
        console.warn("Primary Model Unavailable. Activating Fallback GPT-4o.", err);
        stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, {
          model: 'gpt-4o',
          stream: true
        });
      }

      let fullContent = '';
      let detectedCoding = false;

      // DEFENSE: Check if stream is actually an async iterable
      if (stream && typeof stream[Symbol.asyncIterator] === 'function') {
        for await (const chunk of stream) {
          const text = typeof chunk === 'string' ? chunk : (chunk as any).text || (chunk as any).message?.content || "";
          fullContent += text;

          if (!detectedCoding && (fullContent.includes('[FILE:') || fullContent.includes('```'))) {
            detectedCoding = true;
            setCurrentStatus('coding');
          }

          setMessages(prev => prev.map(m => m.id === assistantId ? { 
            ...m, 
            content: fullContent,
            status: detectedCoding ? 'coding' : 'analyzing'
          } : m));

          if (detectedCoding) parseAndApplyFiles(fullContent);
        }
      } else {
        // Fallback for non-streaming response object
        const content = (stream as any)?.message?.content || (stream as any)?.toString() || "";
        fullContent = content;
        setMessages(prev => prev.map(m => m.id === assistantId ? { 
          ...m, 
          content: content,
          isStreaming: false,
          status: 'idle'
        } : m));
        parseAndApplyFiles(content);
      }

      if (window.puter.print) window.puter.print(fullContent);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error: any) {
      console.error("Transmission Error:", error);
      const errorMsg = error.status === 401 ? "Uplink Unauthorized. Please re-authenticate." : (error.message || "Neural bridge disruption.");
      setMessages(prev => prev.map(m => m.id === assistantId ? { 
        ...m, content: errorMsg, isStreaming: false, error: errorMsg 
      } : m));
      setCurrentStatus('idle');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 active:scale-95 transition-transform cursor-pointer">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_10px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_10px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={handleDownload} className="p-3 rounded-xl transition-all text-slate-500 hover:text-green-400 hover:bg-green-400/10" title="Export Project (Zip)">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Content */}
      <div className="w-[440px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/80 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse shadow-[0_0_10px_#3b82f6]' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Puter Neural Node' : 'Workspace'}
          </span>
          {activeSidebarTab === 'chat' && (
            <div className="relative flex items-center gap-2">
              {!isPuterAuth && (
                <button onClick={handleAuth} className="px-2 py-1 bg-amber-500/20 text-amber-500 text-[8px] font-black rounded border border-amber-500/30 hover:bg-amber-500/30 transition-all uppercase tracking-tighter">Login</button>
              )}
              <select 
                value={activeModel}
                onChange={(e) => setActiveModel(e.target.value)}
                className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10 transition-colors cursor-pointer appearance-none pr-6"
              >
                <option value={AIModel.CLAUDE_3_7}>Claude 3.7</option>
                <option value={AIModel.GPT_4O}>GPT-4o</option>
                <option value={AIModel.GEMINI_PRO}>Gemini 2.0</option>
                <option value={AIModel.DEEPSEEK}>DeepSeek V3</option>
              </select>
              <svg className="w-3 h-3 absolute right-2 pointer-events-none text-slate-600" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 9l-7 7-7-7" strokeWidth="2"/></svg>
            </div>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} onScroll={handleScroll} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-36 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 text-slate-500 opacity-50">
                  <div className="w-20 h-20 bg-blue-500/5 rounded-3xl flex items-center justify-center border border-blue-500/10 mb-6">
                    <svg className="w-10 h-10 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-xs font-black uppercase tracking-widest text-slate-300">Uplink Ready</h3>
                  <p className="text-[10px] mt-2 leading-relaxed">System ready for synthesis.</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-2xl border transition-all ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30' : 'bg-[#1a1f29] text-slate-200 border-white/5'
                  }`}>
                    <div className="whitespace-pre-wrap font-light leading-relaxed">
                      {msg.content.split('[FILE:')[0].split('```').map((part, pIdx) => {
                        if (pIdx % 2 === 1) {
                          return (
                            <div key={pIdx} className="my-4 rounded-xl overflow-hidden bg-[#05070a] border border-white/10 group/snippet relative shadow-inner">
                              <div className="flex justify-between items-center px-4 py-2 bg-white/5 border-b border-white/5">
                                <span className="text-[9px] uppercase font-black text-slate-500 tracking-widest">Snippet</span>
                                <div className="flex gap-3">
                                  <button onClick={() => handleCopyCode(part)} className="text-slate-500 hover:text-blue-400 transition-colors"><svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" strokeWidth="2"/></svg></button>
                                </div>
                              </div>
                              <pre className="p-4 text-[11px] font-mono overflow-x-auto custom-scrollbar text-blue-200"><code>{part}</code></pre>
                            </div>
                          );
                        }
                        return part;
                      })}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-5 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent">
              <div className="bg-[#1a1f29]/95 backdrop-blur-xl border border-white/10 rounded-2xl p-4 shadow-2xl ring-1 ring-white/5">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                  placeholder="Design complex software..."
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[160px] placeholder:text-slate-700 font-light"
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full ${currentStatus === 'analyzing' ? 'bg-amber-400' : currentStatus === 'coding' ? 'bg-green-400' : 'bg-slate-700'}`}></div>
                    <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20 active:scale-95'}`}>
                    Transmit
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs transition-all border group ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/30' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-bold">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      <div className="flex-1 flex flex-col min-w-0">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5">
          <div className="flex items-center gap-3"><span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span></div>
          <div className="flex items-center gap-2 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10">
            <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_8px_#10b981]"></div>Neural Sync Active
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 bg-[#0b0e14]">
            <Editor
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              onChange={(v) => {
                const newFiles = [...files];
                const index = newFiles.findIndex(f => f.path === activeFilePath);
                if (index > -1) {
                  newFiles[index].content = v || '';
                  setFiles(newFiles);
                }
              }}
              options={{ minimap: { enabled: false }, fontSize: 14, fontFamily: "'Fira Code', monospace", backgroundColor: '#0b0e14', padding: { top: 24 }, lineNumbers: 'on', automaticLayout: true }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl"><Preview code={bundledCode} /></div>
        </div>
      </div>
    </div>
  );
};

export default App;

export enum AIModel {
  CLAUDE_3_7 = 'claude-3-7-sonnet',
  GPT_4O = 'gpt-4o',
  GEMINI_2_0 = 'gemini-2.0-flash',
}

export interface AIConfig {
  temperature: number;
  topP: number;
  maxTokens: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: string;
  config?: AIConfig;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'idle';
  error?: string;
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
    JSZip: any;
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .vayu-container {
      position: relative;
      padding: 4rem;
      border-radius: 2rem;
      background: rgba(255, 255, 255, 0.02);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.05em;
      filter: drop-shadow(0 0 15px rgba(59, 130, 246, 0.3));
    }
    .pulse-dot {
      width: 8px;
      height: 8px;
      background: #3b82f6;
      border-radius: 50%;
      animation: pulse 2s infinite;
    }
    @keyframes pulse {
      0% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0.7); }
      70% { transform: scale(1); box-shadow: 0 0 0 10px rgba(59, 130, 246, 0); }
      100% { transform: scale(0.95); box-shadow: 0 0 0 0 rgba(59, 130, 246, 0); }
    }
  </style>
</head>
<body>
  <div class="vayu-container">
    <h1 class="vayu-logo">VAYU</h1>
    <div class="flex items-center gap-3 justify-center mt-4">
      <div class="pulse-dot"></div>
      <span class="text-xs font-mono uppercase tracking-widest text-slate-500">Neural Environment Active</span>
    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.CLAUDE_3_7);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [showScrollButton, setShowScrollButton] = useState(false);
  const [isPuterAuth, setIsPuterAuth] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  // Auth synchronization on mount and periodically
  useEffect(() => {
    const checkAuth = async () => {
      if (window.puter) {
        try {
          const signedIn = await window.puter.auth.isSignedIn();
          setIsPuterAuth(signedIn);
        } catch (e) {
          console.warn("Puter auth check failed", e);
        }
      }
    };
    checkAuth();
    const interval = setInterval(checkAuth, 30000);
    return () => clearInterval(interval);
  }, []);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';

    let bundled = index;
    if (style) {
      bundled = bundled.includes('</head>') 
        ? bundled.replace('</head>', `<style>${style}</style></head>`)
        : `<style>${style}</style>` + bundled;
    }
    if (script) {
      bundled = bundled.includes('</body>')
        ? bundled.replace('</body>', `<script>${script}</script></body>`)
        : bundled + `<script>${script}</script>`;
    }
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isGenerating]);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    setShowScrollButton(scrollHeight - scrollTop - clientHeight > 100);
  };

  const scrollToBottom = () => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });

  const handleCopyCode = (code: string) => navigator.clipboard.writeText(code);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `vayu-project-${Date.now()}.zip`;
    link.click();
  };

  const handleAuth = async () => {
    try {
      await window.puter.auth.signIn();
      setIsPuterAuth(true);
    } catch (e) {
      console.error("Auth failed", e);
    }
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)```/g;
    let match;
    let newFiles = [...files];
    let hasUpdates = false;

    while ((match = fileRegex.exec(text)) !== null) {
      const path = match[1].trim();
      const content = match[2].trim();
      const language = path.split('.').pop() || 'plaintext';

      const existingIndex = newFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (newFiles[existingIndex].content !== content) {
          newFiles[existingIndex] = { ...newFiles[existingIndex], content };
          hasUpdates = true;
        }
      } else {
        newFiles.push({ path, content, language });
        hasUpdates = true;
      }
    }
    if (hasUpdates) setFiles(newFiles);
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    // Proactive Unauthorized check
    if (!isPuterAuth) {
      const signedIn = await window.puter.auth.isSignedIn();
      if (!signedIn) {
        await handleAuth();
        const secondCheck = await window.puter.auth.isSignedIn();
        if (!secondCheck) return;
      }
      setIsPuterAuth(true);
    }

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: currentPrompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
      status: 'analyzing'
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemInstruction = `You are Vayu, a world-class browser-based IDE engineer.
      Current environment uses Puter.js modules (puter.ai, puter.fs, puter.kv, puter.auth).

      CRITICAL FORMATTING RULES:
      1. Be concise but architecturally sound.
      2. Provide FULL file updates using this exact tag: [FILE: filename.ext] followed by a code block.
      3. For any data logic, suggest using puter.kv for persistence.
      4. Ensure index.html, style.css, and script.js are synchronized if modified.`;

      let stream;
      const modelToUse = activeModel;

      const callAIApi = async (modelName: string) => {
        return await window.puter.ai.chat(`${systemInstruction}\n\nUser Task: ${currentPrompt}`, {
          model: modelName,
          stream: true
        });
      };

      try {
        stream = await callAIApi(modelToUse);
      } catch (err: any) {
        // Handle 401 specifically
        if (err.status === 401 || err.message?.toLowerCase().includes('unauthorized')) {
          setIsPuterAuth(false);
          await handleAuth();
          stream = await callAIApi(modelToUse);
        } else {
          console.warn(`Model ${modelToUse} failed, attempting fallback to gpt-4o`, err);
          stream = await callAIApi('gpt-4o');
        }
      }

      let fullContent = '';
      let detectedCoding = false;

      // Smooth Handling of Stream vs Object responses
      if (stream && typeof stream[Symbol.asyncIterator] === 'function') {
        for await (const chunk of stream) {
          const text = typeof chunk === 'string' 
            ? chunk 
            : (chunk as any).text || (chunk as any).message?.content || (chunk as any).delta || "";

          fullContent += text;

          if (!detectedCoding && (fullContent.includes('[FILE:') || fullContent.includes('```'))) {
            detectedCoding = true;
            setCurrentStatus('coding');
          }

          setMessages(prev => prev.map(m => m.id === assistantId ? { 
            ...m, 
            content: fullContent,
            status: detectedCoding ? 'coding' : 'analyzing'
          } : m));

          // Batch updates periodically for performance
          if (detectedCoding && fullContent.length % 50 === 0) {
            parseAndApplyFiles(fullContent);
          }
        }
        // Final parse to ensure accuracy
        parseAndApplyFiles(fullContent);
      } else {
        // Handle Static Object Response
        const content = (stream as any)?.message?.content || (stream as any)?.toString() || "The neural link returned an empty response.";
        fullContent = content;
        setMessages(prev => prev.map(m => m.id === assistantId ? { 
          ...m, 
          content: content,
          isStreaming: false,
          status: 'idle'
        } : m));
        parseAndApplyFiles(content);
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error: any) {
      console.error("IDE Uplink Error:", error);
      const errorMsg = error.status === 401 
        ? "Access Revoked. Please refresh or login to Puter.js." 
        : (error.message || "A neural synchronization error occurred.");

      setMessages(prev => prev.map(m => m.id === assistantId ? { 
        ...m, content: errorMsg, isStreaming: false, error: errorMsg 
      } : m));
      setCurrentStatus('idle');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar - Opaque & Slim */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 hover:scale-105 active:scale-95 transition-all cursor-pointer ring-1 ring-white/10">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.15)] ring-1 ring-blue-500/30' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.15)] ring-1 ring-blue-500/30' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={handleDownload} className="p-3 rounded-xl transition-all text-slate-500 hover:text-green-400 hover:bg-green-400/10" title="Export Manifest">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar - Glassmorphism */}
      <div className="w-[440px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/80 backdrop-blur-md sticky top-0 z-10">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse shadow-[0_0_10px_#3b82f6]' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Synthesis' : 'Source Assets'}
          </span>
          {activeSidebarTab === 'chat' && (
            <div className="relative flex items-center gap-2">
              {!isPuterAuth && (
                <button onClick={handleAuth} className="px-2 py-0.5 bg-amber-500/10 text-amber-500 text-[8px] font-black rounded border border-amber-500/20 hover:bg-amber-500/20 transition-all uppercase tracking-tighter">Auth Required</button>
              )}
              <div className="relative group">
                <select 
                  value={activeModel}
                  onChange={(e) => setActiveModel(e.target.value)}
                  className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10 transition-colors cursor-pointer appearance-none pr-6 font-bold"
                >
                  <option value={AIModel.CLAUDE_3_7}>Claude 3.7 Sonnet</option>
                  <option value={AIModel.GPT_4O}>GPT-4o Omnimodel</option>
                  <option value={AIModel.GEMINI_2_0}>Gemini 2.0 Flash</option>
                </select>
                <svg className="w-3 h-3 absolute right-2 top-1/2 -translate-y-1/2 pointer-events-none text-blue-500/50" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 9l-7 7-7-7" strokeWidth="2"/></svg>
              </div>
            </div>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative bg-[#0b0e14]">
            <div ref={chatContainerRef} onScroll={handleScroll} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-40 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-40 select-none">
                  <div className="w-20 h-20 bg-blue-500/5 rounded-3xl flex items-center justify-center border border-blue-500/10 mb-6 animate-pulse">
                    <svg className="w-10 h-10 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-xs font-black uppercase tracking-widest text-slate-300">Neural Sync Active</h3>
                  <p className="text-[10px] mt-2 leading-relaxed max-w-[250px]">Instruct the model to generate, debug, or optimize your design software infrastructure.</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-2xl border transition-all duration-300 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30' : 'bg-[#1a1f29] text-slate-200 border-white/5'
                  }`}>
                    {msg.error && (
                      <div className="flex items-center gap-2 mb-2 p-2 bg-red-500/10 border border-red-500/20 rounded-lg text-[10px] text-red-400 font-bold uppercase tracking-tighter">
                        <svg className="w-3 h-3" fill="currentColor" viewBox="0 0 20 20"><path d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z"/></svg>
                        Neural Bridge Error
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-light leading-relaxed">
                      {msg.content.split('[FILE:')[0].split('```').map((part, pIdx) => {
                        if (pIdx % 2 === 1) {
                          return (
                            <div key={pIdx} className="my-4 rounded-xl overflow-hidden bg-[#05070a] border border-white/10 group/snippet relative shadow-2xl ring-1 ring-white/5">
                              <div className="flex justify-between items-center px-4 py-2 bg-white/5 border-b border-white/5">
                                <span className="text-[9px] uppercase font-black text-slate-500 tracking-widest">Logic Node</span>
                                <div className="flex gap-3">
                                  <button onClick={() => handleCopyCode(part)} className="text-slate-500 hover:text-blue-400 transition-colors" title="Copy Content">
                                    <svg className="w-3.5 h-3.5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" strokeWidth="2"/></svg>
                                  </button>
                                </div>
                              </div>
                              <pre className="p-4 text-[11px] font-mono overflow-x-auto custom-scrollbar text-blue-200 bg-[#05070a]"><code>{part}</code></pre>
                            </div>
                          );
                        }
                        return part;
                      })}
                    </div>
                  </div>
                  <span className="text-[8px] text-slate-600 font-black uppercase tracking-[0.2em] px-2 opacity-0 group-hover:opacity-100 transition-opacity">
                    {msg.role === 'user' ? 'Terminal Uplink' : 'Vayu Core'}
                  </span>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            {/* Prompt Area */}
            <div className="absolute bottom-0 left-0 right-0 p-5 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent pointer-events-none">
              <div className="bg-[#1a1f29]/95 backdrop-blur-2xl border border-white/10 rounded-2xl p-4 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.6)] ring-1 ring-white/5 pointer-events-auto">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                  placeholder="Ask Vayu to design high-performance assets..."
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[160px] placeholder:text-slate-700 font-light"
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-2">
                    <div className={`w-2 h-2 rounded-full transition-all duration-500 ${currentStatus === 'analyzing' ? 'bg-amber-400 shadow-[0_0_10px_#fbbf24]' : currentStatus === 'coding' ? 'bg-green-400 shadow-[0_0_10px_#4ade80]' : 'bg-slate-700'}`}></div>
                    <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest">{currentStatus === 'idle' ? 'System Ready' : currentStatus}</span>
                  </div>
                  <button 
                    onClick={() => handleSendMessage()} 
                    disabled={isGenerating || !prompt.trim()} 
                    className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-widest transition-all ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20 active:scale-95 ring-1 ring-blue-400/30'}`}
                  >
                    {isGenerating ? 'Synthesizing...' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1 bg-[#0b0e14]">
            {files.map(file => (
              <button 
                key={file.path} 
                onClick={() => setActiveFilePath(file.path)} 
                className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs transition-all border group relative ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/30 shadow-[inset_0_0_10px_rgba(59,130,246,0.05)]' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}
              >
