const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.CLAUDE_3_7);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [showScrollButton, setShowScrollButton] = useState(false);
  const [isPuterAuth, setIsPuterAuth] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  useEffect(() => {
    const checkAuth = async () => {
      if (window.puter) {
        try {
          const signedIn = await window.puter.auth.isSignedIn();
          setIsPuterAuth(signedIn);
        } catch (e) {
          console.warn("Puter auth check failed", e);
        }
      }
    };
    checkAuth();
    const interval = setInterval(checkAuth, 30000);
    return () => clearInterval(interval);
  }, []);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';

    let bundled = index;
    if (style) {
      bundled = bundled.includes('</head>') 
        ? bundled.replace('</head>', `<style>${style}</style></head>`)
        : `<style>${style}</style>` + bundled;
    }
    if (script) {
      bundled = bundled.includes('</body>')
        ? bundled.replace('</body>', `<script>${script}</script></body>`)
        : bundled + `<script>${script}</script>`;
    }
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isGenerating]);

  const handleScroll = (e: React.UIEvent<HTMLDivElement>) => {
    const { scrollTop, scrollHeight, clientHeight } = e.currentTarget;
    setShowScrollButton(scrollHeight - scrollTop - clientHeight > 100);
  };

  const scrollToBottom = () => chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  const handleCopyCode = (code: string) => navigator.clipboard.writeText(code);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `vayu-project-${Date.now()}.zip`;
    link.click();
  };

  const handleAuth = async () => {
    try {
      await window.puter.auth.signIn();
      setIsPuterAuth(true);
    } catch (e) {
      console.error("Auth failed", e);
    }
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)```/g;
    let match;
    let newFiles = [...files];
    let hasUpdates = false;

    while ((match = fileRegex.exec(text)) !== null) {
      const path = match[1].trim();
      const content = match[2].trim();
      const language = path.split('.').pop() || 'plaintext';

      const existingIndex = newFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (newFiles[existingIndex].content !== content) {
          newFiles[existingIndex] = { ...newFiles[existingIndex], content };
          hasUpdates = true;
        }
      } else {
        newFiles.push({ path, content, language });
        hasUpdates = true;
      }
    }
    if (hasUpdates) setFiles(newFiles);
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    if (!isPuterAuth) {
      const signedIn = await window.puter.auth.isSignedIn();
      if (!signedIn) {
        await handleAuth();
        if (!await window.puter.auth.isSignedIn()) return;
      }
      setIsPuterAuth(true);
    }

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: currentPrompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
      status: 'analyzing'
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemInstruction = `You are Vayu, a world-class browser IDE.
      Provide FULL file updates with [FILE: filename.ext] followed by code.
      Suggest puter.kv for storage and puter.auth for security.`;

      let stream;
      const callApi = async (m: string) => window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, { model: m, stream: true });

      try {
        stream = await callApi(activeModel);
      } catch (err: any) {
        if (err.status === 401) {
          setIsPuterAuth(false);
          await handleAuth();
          stream = await callApi(activeModel);
        } else {
          console.warn("Fallback to gpt-4o", err);
          stream = await callApi('gpt-4o');
        }
      }

      let fullContent = '';
      let detectedCoding = false;

      // Handle stream iteration robustly
      if (stream && typeof stream[Symbol.asyncIterator] === 'function') {
        for await (const chunk of stream) {
          const text = typeof chunk === 'string' ? chunk : (chunk as any).text || (chunk as any).message?.content || "";
          fullContent += text;

          if (!detectedCoding && (fullContent.includes('[FILE:') || fullContent.includes('```'))) {
            detectedCoding = true;
            setCurrentStatus('coding');
          }

          setMessages(prev => prev.map(m => m.id === assistantId ? { 
            ...m, content: fullContent, status: detectedCoding ? 'coding' : 'analyzing'
          } : m));

          if (detectedCoding && fullContent.length % 40 === 0) parseAndApplyFiles(fullContent);
        }
        parseAndApplyFiles(fullContent);
      } else {
        const content = (stream as any)?.message?.content || (stream as any)?.toString() || "";
        fullContent = content;
        setMessages(prev => prev.map(m => m.id === assistantId ? { 
          ...m, content: content, isStreaming: false, status: 'idle'
        } : m));
        parseAndApplyFiles(content);
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error: any) {
      console.error("Neural Error:", error);
      const errorMsg = error.status === 401 ? "Unauthorized access. Please login." : (error.message || "Uplink disruption.");
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: errorMsg, isStreaming: false, error: errorMsg } : m));
      setCurrentStatus('idle');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 active:scale-95 transition-all cursor-pointer ring-1 ring-white/10">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={handleDownload} className="p-3 rounded-xl transition-all text-slate-500 hover:text-green-400 hover:bg-green-400/10" title="Export Manifest">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Content */}
      <div className="w-[440px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/80 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Synthesis' : 'Workspace'}
          </span>
          {activeSidebarTab === 'chat' && (
            <div className="relative flex items-center gap-2">
              {!isPuterAuth && (
