import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

interface HoloOrbProps {
  active: boolean;
  onToggle: () => void;
}

export const HoloOrb: React.FC<HoloOrbProps> = ({ active, onToggle }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  // Fixed: Added initial value undefined to satisfy the useRef signature that expects at least 1 argument in some TS environments.
  const requestRef = useRef<number | undefined>(undefined);
  const mouseRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);
    camera.position.z = 2.5;

    const renderer = new THREE.WebGLRenderer({ 
      alpha: true, 
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setSize(200, 200);
    containerRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Outer Glow Sphere
    const sphereGeo = new THREE.SphereGeometry(1, 32, 32);
    const sphereMat = new THREE.MeshPhongMaterial({
      color: 0x3b82f6,
      transparent: true,
      opacity: 0.15,
      wireframe: true,
      emissive: 0x3b82f6,
      emissiveIntensity: 0.5
    });
    const sphere = new THREE.Mesh(sphereGeo, sphereMat);
    scene.add(sphere);

    // Inner Core
    const coreGeo = new THREE.IcosahedronGeometry(0.5, 2);
    const coreMat = new THREE.MeshPhongMaterial({
      color: 0x6366f1,
      emissive: 0x818cf8,
      emissiveIntensity: 1,
      flatShading: true
    });
    const core = new THREE.Mesh(coreGeo, coreMat);
    scene.add(core);

    // Orbiting Particles
    const particlesGeo = new THREE.BufferGeometry();
    const posArr = new Float32Array(300 * 3);
    for (let i = 0; i < 900; i++) {
      posArr[i] = (Math.random() - 0.5) * 4;
    }
    particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArr, 3));
    const particlesMat = new THREE.PointsMaterial({
      size: 0.015,
      color: 0x60a5fa,
      transparent: true,
      opacity: 0.8
    });
    const particleSystem = new THREE.Points(particlesGeo, particlesMat);
    scene.add(particleSystem);

    const light = new THREE.PointLight(0xffffff, 1, 100);
    light.position.set(5, 5, 5);
    scene.add(light);
    scene.add(new THREE.AmbientLight(0x404040));

    const animate = () => {
      requestRef.current = requestAnimationFrame(animate);

      sphere.rotation.y += 0.005;
      sphere.rotation.x += 0.002;
      core.rotation.y -= 0.015;

      // React to mouse gestures
      sphere.position.x += (mouseRef.current.x * 0.5 - sphere.position.x) * 0.05;
      sphere.position.y += (mouseRef.current.y * -0.5 - sphere.position.y) * 0.05;

      core.scale.setScalar(1 + Math.sin(Date.now() * 0.005) * 0.1);
      particleSystem.rotation.y += 0.001;

      renderer.render(scene, camera);
    };

    animate();

    const handleMouseMove = (e: MouseEvent) => {
      const rect = containerRef.current?.getBoundingClientRect();
      if (rect) {
        mouseRef.current = {
          x: ((e.clientX - rect.left) / rect.width) * 2 - 1,
          y: ((e.clientY - rect.top) / rect.height) * 2 - 1
        };
      }
    };

    window.addEventListener('mousemove', handleMouseMove);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      if (rendererRef.current) {
        containerRef.current?.removeChild(rendererRef.current.domElement);
        rendererRef.current.dispose();
      }
    };
  }, []);

  return (
    <div className="absolute bottom-6 right-6 z-50 flex flex-col items-center gap-4 group">
      <div 
        ref={containerRef}
        onClick={onToggle}
        className={`w-40 h-40 rounded-full cursor-pointer transition-all duration-700 
          ${active ? 'scale-125' : 'scale-100 opacity-80 hover:opacity-100'}
          filter drop-shadow-[0_0_30px_rgba(59,130,246,0.3)]
        `}
      />

      <div className={`flex flex-col items-center gap-2 transition-all duration-500 transform 
        ${active ? 'translate-y-0 opacity-100' : 'translate-y-10 opacity-0 pointer-events-none'}`}>
        <div className="bg-black/60 backdrop-blur-xl border border-white/10 p-4 rounded-2xl flex flex-col gap-3 shadow-2xl">
          <p className="text-[10px] font-black uppercase tracking-widest text-blue-400 text-center">Neural Interface</p>
          <div className="flex gap-2">
            <button 
              onClick={(e) => { e.stopPropagation(); alert("Generating USDZ for Apple AR..."); }}
              className="px-3 py-1.5 bg-blue-500/20 hover:bg-blue-500/40 border border-blue-500/30 rounded-lg text-[9px] font-bold text-blue-200 transition-all"
            >
              Export USDZ
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); alert("Preparing Vision Pro Spatial Preview..."); }}
              className="px-3 py-1.5 bg-purple-500/20 hover:bg-purple-500/40 border border-purple-500/30 rounded-lg text-[9px] font-bold text-purple-200 transition-all"
            >
              Spatial Sync
            </button>
          </div>
        </div>
      </div>

      {!active && (
        <div className="absolute -top-10 left-1/2 -translate-x-1/2 whitespace-nowrap bg-blue-500 text-white text-[10px] font-bold px-3 py-1 rounded-full opacity-0 group-hover:opacity-100 transition-opacity pointer-events-none">
          Holo-Preview
        </div>
      )}
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
