      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
