import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';

interface HoloOrbProps {
  active: boolean;
  onToggle: () => void;
}

export const HoloOrb: React.FC<HoloOrbProps> = ({ active, onToggle }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const requestRef = useRef<number | undefined>(undefined);
  const mouseRef = useRef({ x: 0, y: 0 });
  const targetMouseRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);
    camera.position.z = 2.5;

    const renderer = new THREE.WebGLRenderer({ 
      alpha: true, 
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setSize(200, 200);
    containerRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    // Outer Glow Sphere
    const sphereGeo = new THREE.SphereGeometry(1, 32, 32);
    const sphereMat = new THREE.MeshPhongMaterial({
      color: 0x3b82f6,
      transparent: true,
      opacity: 0.15,
      wireframe: true,
      emissive: 0x3b82f6,
      emissiveIntensity: 0.6
    });
    const sphere = new THREE.Mesh(sphereGeo, sphereMat);
    scene.add(sphere);

    // Inner Core
    const coreGeo = new THREE.IcosahedronGeometry(0.5, 2);
    const coreMat = new THREE.MeshPhongMaterial({
      color: 0x6366f1,
      emissive: 0x818cf8,
      emissiveIntensity: 1.2,
      flatShading: true
    });
    const core = new THREE.Mesh(coreGeo, coreMat);
    scene.add(core);

    // Orbiting Particles
    const particlesGeo = new THREE.BufferGeometry();
    const posArr = new Float32Array(400 * 3);
    for (let i = 0; i < 1200; i++) {
      posArr[i] = (Math.random() - 0.5) * 4;
    }
    particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArr, 3));
    const particlesMat = new THREE.PointsMaterial({
      size: 0.012,
      color: 0x60a5fa,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending
    });
    const particleSystem = new THREE.Points(particlesGeo, particlesMat);
    scene.add(particleSystem);

    const light = new THREE.PointLight(0xffffff, 1, 100);
    light.position.set(5, 5, 5);
    scene.add(light);
    scene.add(new THREE.AmbientLight(0x404040));

    const animate = () => {
      requestRef.current = requestAnimationFrame(animate);

      // Interpolate mouse for smooth follow
      mouseRef.current.x += (targetMouseRef.current.x - mouseRef.current.x) * 0.1;
      mouseRef.current.y += (targetMouseRef.current.y - mouseRef.current.y) * 0.1;

      sphere.rotation.y += 0.003 + (mouseRef.current.x * 0.02);
      sphere.rotation.x += 0.002 + (mouseRef.current.y * 0.01);
      core.rotation.y -= 0.01;
      core.rotation.z += 0.005;

      // Dynamic scaling based on mouse proximity
      const dist = Math.sqrt(mouseRef.current.x ** 2 + mouseRef.current.y ** 2);
      sphere.scale.setScalar(1 + dist * 0.1);

      // React to mouse gestures (tilting)
      scene.rotation.y = mouseRef.current.x * 0.4;
      scene.rotation.x = mouseRef.current.y * -0.4;

      core.scale.setScalar(1 + Math.sin(Date.now() * 0.004) * 0.1);
      particleSystem.rotation.y += 0.001;

      renderer.render(scene, camera);
    };

    animate();

    const handleMouseMove = (e: MouseEvent) => {
      const rect = containerRef.current?.getBoundingClientRect();
      if (rect) {
        targetMouseRef.current = {
          x: ((e.clientX - rect.left) / rect.width) * 2 - 1,
          y: ((e.clientY - rect.top) / rect.height) * 2 - 1
        };
      }
    };

    window.addEventListener('mousemove', handleMouseMove);

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      if (rendererRef.current) {
        containerRef.current?.removeChild(rendererRef.current.domElement);
        rendererRef.current.dispose();
      }
    };
  }, []);

  return (
    <div className="absolute bottom-6 right-6 z-50 flex flex-col items-center gap-4 group">
      <div 
        ref={containerRef}
        onClick={onToggle}
        className={`w-40 h-40 rounded-full cursor-pointer transition-all duration-700 
          ${active ? 'scale-125' : 'scale-100 opacity-80 hover:opacity-100'}
          filter drop-shadow-[0_0_35px_rgba(59,130,246,0.4)]
        `}
      />

      <div className={`flex flex-col items-center gap-2 transition-all duration-700 transform 
        ${active ? 'translate-y-0 scale-100 opacity-100' : 'translate-y-10 scale-90 opacity-0 pointer-events-none'}`}>
        <div className="bg-[#0b0e14]/80 backdrop-blur-2xl border border-white/10 p-5 rounded-[2rem] flex flex-col gap-4 shadow-2xl ring-1 ring-white/10 min-w-[200px]">
          <div className="flex flex-col items-center">
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400 mb-1">Spatial Engine</p>
            <div className="h-0.5 w-8 bg-blue-500/30 rounded-full"></div>
          </div>
          <div className="flex flex-col gap-2">
            <button 
              onClick={(e) => { e.stopPropagation(); alert("Preparing USDZ Binary Uplink..."); }}
              className="px-4 py-2 bg-blue-500/10 hover:bg-blue-500/20 border border-blue-500/20 rounded-xl text-[9px] font-black uppercase tracking-widest text-blue-200 transition-all hover:scale-[1.02] active:scale-95"
            >
              Export AR Asset
            </button>
            <button 
              onClick={(e) => { e.stopPropagation(); alert("Synchronizing with Apple Vision Pro..."); }}
              className="px-4 py-2 bg-purple-500/10 hover:bg-purple-500/20 border border-purple-500/20 rounded-xl text-[9px] font-black uppercase tracking-widest text-purple-200 transition-all hover:scale-[1.02] active:scale-95"
            >
              Spatial Uplink
            </button>
          </div>
        </div>
      </div>

      {!active && (
        <div className="absolute -top-12 left-1/2 -translate-x-1/2 whitespace-nowrap bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full opacity-0 group-hover:opacity-100 transition-all duration-500 pointer-events-none shadow-xl border border-blue-400/50">
          Neural Preview
        </div>
      )}
    </div>
  );
};

