    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.CLAUDE_3_5);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [isPuterAuth, setIsPuterAuth] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  useEffect(() => {
    const checkAuth = async () => {
      if (window.puter) {
        try {
          const signedIn = await window.puter.auth.isSignedIn();
          setIsPuterAuth(signedIn);
        } catch (e) {
          console.warn("Puter auth check failed", e);
        }
      }
    };
    checkAuth();
  }, []);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';

    let bundled = index;
    if (style) {
      bundled = bundled.includes('</head>') 
        ? bundled.replace('</head>', `<style>${style}</style></head>`)
        : `<style>${style}</style>` + bundled;
    }
    if (script) {
      bundled = bundled.includes('</body>')
        ? bundled.replace('</body>', `<script>${script}</script></body>`)
        : bundled + `<script>${script}</script>`;
    }
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) {
      chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
    }
  }, [messages, isGenerating]);

  const handleCopyCode = (code: string) => navigator.clipboard.writeText(code);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `vayu-project-${Date.now()}.zip`;
    link.click();
  };

  const handleAuth = async () => {
    try {
      await window.puter.auth.signIn();
      setIsPuterAuth(true);
    } catch (e) {
      console.error("Auth failed", e);
    }
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)```/g;
    let match;
    let newFiles = [...files];
    let hasUpdates = false;

    while ((match = fileRegex.exec(text)) !== null) {
      const path = match[1].trim();
      const content = match[2].trim();
      const language = path.split('.').pop() || 'plaintext';

      const existingIndex = newFiles.findIndex(f => f.path === path);
      if (existingIndex > -1) {
        if (newFiles[existingIndex].content !== content) {
          newFiles[existingIndex] = { ...newFiles[existingIndex], content };
          hasUpdates = true;
        }
      } else {
        newFiles.push({ path, content, language });
        hasUpdates = true;
      }
    }
    if (hasUpdates) setFiles(newFiles);
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    if (!isPuterAuth) {
      await handleAuth();
      if (!await window.puter.auth.isSignedIn()) return;
    }

    const userMessage: ChatMessage = {
      id: Date.now().toString(),
      role: 'user',
      content: currentPrompt,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = {
      id: assistantId,
      role: 'assistant',
      content: '',
      model: activeModel,
      timestamp: Date.now(),
      isStreaming: true,
      status: 'analyzing'
    };

    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemInstruction = `You are Vayu, an advanced browser-based AI IDE. 
CRITICAL RULES:
1. Provide full code updates using [FILE: filename.ext] followed by a code block.
2. Focus on high-quality design and functionality.
3. Suggest Puter.js native features (kv, fs, auth) where beneficial.`;

      let fullContent = '';
      let detectedCoding = false;

      // Handle Gemini via SDK, others via Puter.js
      if (activeModel.includes('gemini')) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        const response = await ai.models.generateContentStream({
          model: 'gemini-2.0-flash',
          contents: currentPrompt,
          config: { systemInstruction }
        });

        for await (const chunk of response) {
          const text = chunk.text || "";
          fullContent += text;

          if (!detectedCoding && (fullContent.includes('[FILE:') || fullContent.includes('```'))) {
            detectedCoding = true;
            setCurrentStatus('coding');
          }

          setMessages(prev => prev.map(m => m.id === assistantId ? { 
            ...m, content: fullContent, status: detectedCoding ? 'coding' : 'analyzing'
          } : m));

          if (detectedCoding && fullContent.length % 50 === 0) parseAndApplyFiles(fullContent);
        }
      } else {
        const stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, {
          model: activeModel,
          stream: true
        });

        if (stream && typeof stream[Symbol.asyncIterator] === 'function') {
          for await (const chunk of stream) {
            const text = typeof chunk === 'string' ? chunk : (chunk as any).text || (chunk as any).message?.content || "";
            fullContent += text;

            if (!detectedCoding && (fullContent.includes('[FILE:') || fullContent.includes('```'))) {
              detectedCoding = true;
              setCurrentStatus('coding');
            }

            setMessages(prev => prev.map(m => m.id === assistantId ? { 
              ...m, content: fullContent, status: detectedCoding ? 'coding' : 'analyzing'
            } : m));

            if (detectedCoding && fullContent.length % 50 === 0) parseAndApplyFiles(fullContent);
          }
        } else {
          fullContent = (stream as any)?.message?.content || (stream as any)?.toString() || "";
        }
      }

      parseAndApplyFiles(fullContent);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error: any) {
      console.error("Neural Error:", error);
      const errorMsg = error.message || "Uplink disruption.";
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: errorMsg, isStreaming: false, error: errorMsg } : m));
      setCurrentStatus('idle');
    } finally {
      setIsGenerating(false);
    }
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar (Left Section) */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 active:scale-95 transition-all cursor-pointer ring-1 ring-white/10">V</div>
        <div className="flex flex-col gap-6">
          <button 
            onClick={() => setActiveSidebarTab('chat')} 
            className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}
            title="AI Neural Link"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button 
            onClick={() => setActiveSidebarTab('files')} 
            className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}
            title="Explorer"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>

          <div className="h-px w-8 bg-white/5 mx-auto"></div>

          {/* SEARCH INTEGRATION REQUESTED */}
          <button 
            onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')}
            className="p-3 rounded-xl transition-all text-slate-500 hover:text-blue-400 hover:bg-blue-400/10"
            title="Deep Neural Search"
          >
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
            </svg>
          </button>

          <button onClick={handleDownload} className="p-3 rounded-xl transition-all text-slate-500 hover:text-green-400 hover:bg-green-400/10" title="Export Deployment">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Primary Sidebar Content */}
      <div className="w-[440px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/80 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Synthesis' : 'Workspace'}
          </span>
          {activeSidebarTab === 'chat' && (
            <div className="relative flex items-center gap-2">
              {!isPuterAuth && (
                <button onClick={handleAuth} className="px-2 py-0.5 bg-amber-500/10 text-amber-500 text-[8px] font-black rounded border border-amber-500/20 hover:bg-amber-500/20 uppercase transition-all">Login</button>
              )}
              <select 
                value={activeModel}
                onChange={(e) => setActiveModel(e.target.value)}
                className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10 transition-colors appearance-none pr-6 cursor-pointer font-bold"
              >
                <option value={AIModel.CLAUDE_3_5}>Claude 3.5 Sonnet</option>
                <option value={AIModel.GPT_4O}>GPT-4o</option>
                <option value={AIModel.GEMINI_2_0}>Gemini 2.0 Flash</option>
              </select>
              <svg className="w-3 h-3 absolute right-2 pointer-events-none text-blue-500/50" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M19 9l-7 7-7-7" strokeWidth="2.5"/></svg>
            </div>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-44 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center p-8 opacity-40 select-none animate-fade-in">
                  <div className="w-24 h-24 bg-blue-500/5 rounded-[2.5rem] flex items-center justify-center border border-blue-500/10 mb-8 animate-pulse shadow-[0_0_50px_rgba(59,130,246,0.1)]">
                    <svg className="w-12 h-12 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.2"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-400">Core Link Established</h3>
                  <p className="text-[11px] mt-4 leading-relaxed max-w-[280px] text-slate-500 font-medium italic">"Architect software using the power of multi-modal intelligence."</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[92%] p-5 rounded-[2rem] text-[13.5px] shadow-2xl border transition-all duration-700 hover:scale-[1.01] ${
                    msg.role === 'user' 
                      ? 'bg-blue-600/90 backdrop-blur-md text-white border-blue-400/30 rounded-br-none' 
                      : 'bg-white/5 backdrop-blur-2xl text-slate-200 border-white/10 rounded-bl-none shadow-[inset_0_0_20px_rgba(255,255,255,0.02)]'
                  }`}>
                    <div className="whitespace-pre-wrap font-normal leading-relaxed">
                      {msg.content.split('[FILE:').map((filePart, fIdx) => {
                        if (fIdx === 0) return filePart.split('```').map((part, pIdx) => {
                          if (pIdx % 2 === 1) {
                            return (
                              <div key={pIdx} className="my-5 rounded-2xl overflow-hidden bg-black/50 border border-white/10 group/snippet relative shadow-2xl">
                                <div className="flex justify-between items-center px-4 py-2 bg-white/5 border-b border-white/5 backdrop-blur-md">
                                  <span className="text-[9px] uppercase font-black text-slate-500 tracking-widest flex items-center gap-2">
                                     <div className="w-1.5 h-1.5 rounded-full bg-blue-500 animate-pulse"></div> Source Fragment
                                  </span>
                                  <button onClick={() => handleCopyCode(part)} className="text-slate-500 hover:text-blue-400 transition-all transform active:scale-90" title="Copy Content">
                                    <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" strokeWidth="2"/></svg>
                                  </button>
                                </div>
                                <pre className="p-4 text-[11px] font-mono overflow-x-auto custom-scrollbar text-blue-100 bg-transparent"><code>{part}</code></pre>
                              </div>
                            );
                          }
                          return part;
                        });
                        return null;
                      })}
                    </div>
                  </div>
                  <span className="text-[8.5px] text-slate-600 font-black uppercase tracking-[0.25em] px-4 opacity-0 group-hover:opacity-100 transition-all duration-500">
                    {msg.role === 'user' ? 'Terminal User' : `Vayu Node - ${msg.model || activeModel}`}
                  </span>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            {/* Input Composer */}
            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/95 backdrop-blur-3xl border border-white/10 rounded-[2.5rem] p-4 shadow-[0_25px_60px_rgba(0,0,0,0.6)] ring-1 ring-white/10 focus-within:ring-blue-500/40 transition-all duration-700 pointer-events-auto">
                <textarea
                  value={prompt}
                  onChange={(e) => setPrompt(e.target.value)}
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                  placeholder="Ask Vayu to build software..."
                  className="w-full bg-transparent outline-none resize-none text-[13.5px] min-h-[50px] max-h-[160px] placeholder:text-slate-700 font-medium px-4 py-2"
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-3 ml-2">
                    <div className={`w-2 h-2 rounded-full transition-all duration-1000 ${currentStatus === 'analyzing' ? 'bg-amber-400 shadow-[0_0_15px_#fbbf24]' : currentStatus === 'coding' ? 'bg-blue-400 shadow-[0_0_15px_#3b82f6]' : 'bg-slate-700'}`}></div>
                    <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest select-none">{currentStatus}</span>
                  </div>
                  <button 
                    onClick={() => handleSendMessage()} 
                    disabled={isGenerating || !prompt.trim()} 
                    className={`px-8 py-3 rounded-2xl font-black text-[10.5px] uppercase tracking-[0.2em] transition-all transform active:scale-95 ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-2xl shadow-blue-500/30 border border-blue-400/40'}`}
                  >
                    {isGenerating ? 'Synthesizing' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-2 bg-[#0b0e14]">
            {files.map(file => (
              <button 
                key={file.path} 
                onClick={() => setActiveFilePath(file.path)} 
                className={`w-full flex items-center gap-4 px-6 py-5 rounded-2xl text-[12.5px] transition-all border group relative overflow-hidden ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/30 shadow-inner' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}
              >
                <div className={`absolute left-0 w-1.5 h-8 bg-blue-500 rounded-r-full transition-all duration-700 ${activeFilePath === file.path ? 'opacity-100 scale-100' : 'opacity-0 scale-0'}`}></div>
                <svg className={`w-4.5 h-4.5 transition-all ${activeFilePath === file.path ? 'text-blue-400 scale-110' : 'text-slate-700 group-hover:text-slate-400'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2.5" /></svg>
                <span className="flex-1 text-left truncate font-bold tracking-tight">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Editor & Preview Section */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14]">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 sticky top-0 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            <div className="px-3 py-1 bg-blue-500/10 text-[9px] font-black text-blue-400/70 rounded-lg border border-blue-500/20 uppercase tracking-widest">{activeFile.language}</div>
          </div>
          <div className="flex items-center gap-4 select-none">
             <div className="flex items-center gap-3 text-[9.5px] font-black uppercase text-green-500 bg-green-500/5 px-4 py-1.5 rounded-full border border-green-500/15 shadow-inner transition-all hover:border-green-500/30">
               <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_12px_#10b981]"></div>
               Environment Synced
             </div>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden group">
            <Editor
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              onChange={(v) => {
                const newFiles = [...files];
                const index = newFiles.findIndex(f => f.path === activeFilePath);
                if (index > -1) {
                  newFiles[index].content = v || '';
                  setFiles(newFiles);
                }
              }}
              options={{ 
                minimap: { enabled: false }, 
                fontSize: 14.5, 
                fontFamily: "'Fira Code', monospace", 
                backgroundColor: '#0b0e14', 
                padding: { top: 32 }, 
                lineNumbers: 'on', 
                automaticLayout: true, 
                cursorBlinking: 'smooth', 
                cursorSmoothCaretAnimation: true, 
                smoothScrolling: true,
                renderLineHighlight: 'all',
                scrollBeyondLastLine: false,
                fixedOverflowWidgets: true,
                fontLigatures: true,
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef } from 'react';
import * as THREE from 'three';

interface HoloOrbProps {
  active: boolean;
  onToggle: () => void;
}

export const HoloOrb: React.FC<HoloOrbProps> = ({ active, onToggle }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const rendererRef = useRef<THREE.WebGLRenderer | null>(null);
  const requestRef = useRef<number | undefined>(undefined);
  const mouseRef = useRef({ x: 0, y: 0 });
  const targetMouseRef = useRef({ x: 0, y: 0 });

  useEffect(() => {
    if (!containerRef.current) return;

    const scene = new THREE.Scene();
    const camera = new THREE.PerspectiveCamera(75, 1, 0.1, 1000);
    camera.position.z = 2.5;

    const renderer = new THREE.WebGLRenderer({ 
      alpha: true, 
      antialias: true,
      powerPreference: "high-performance"
    });
    renderer.setSize(200, 200);
    containerRef.current.appendChild(renderer.domElement);
    rendererRef.current = renderer;

    const sphereGeo = new THREE.SphereGeometry(1, 32, 32);
    const sphereMat = new THREE.MeshPhongMaterial({
      color: 0x3b82f6,
      transparent: true,
      opacity: 0.15,
      wireframe: true,
      emissive: 0x3b82f6,
      emissiveIntensity: 0.6
    });
    const sphere = new THREE.Mesh(sphereGeo, sphereMat);
    scene.add(sphere);

    const coreGeo = new THREE.IcosahedronGeometry(0.5, 2);
    const coreMat = new THREE.MeshPhongMaterial({
      color: 0x6366f1,
      emissive: 0x818cf8,
      emissiveIntensity: 1.2,
      flatShading: true
    });
    const core = new THREE.Mesh(coreGeo, coreMat);
    scene.add(core);

    const particlesGeo = new THREE.BufferGeometry();
    const posArr = new Float32Array(400 * 3);
    for (let i = 0; i < 1200; i++) posArr[i] = (Math.random() - 0.5) * 4;
    particlesGeo.setAttribute('position', new THREE.BufferAttribute(posArr, 3));
    const particlesMat = new THREE.PointsMaterial({
      size: 0.012,
      color: 0x60a5fa,
      transparent: true,
      opacity: 0.8,
      blending: THREE.AdditiveBlending
    });
    const particleSystem = new THREE.Points(particlesGeo, particlesMat);
    scene.add(particleSystem);

    const light = new THREE.PointLight(0xffffff, 1, 100);
    light.position.set(5, 5, 5);
    scene.add(light);
    scene.add(new THREE.AmbientLight(0x404040));

    const animate = () => {
      requestRef.current = requestAnimationFrame(animate);
      mouseRef.current.x += (targetMouseRef.current.x - mouseRef.current.x) * 0.1;
      mouseRef.current.y += (targetMouseRef.current.y - mouseRef.current.y) * 0.1;

      sphere.rotation.y += 0.003 + (mouseRef.current.x * 0.02);
      sphere.rotation.x += 0.002 + (mouseRef.current.y * 0.01);
      core.rotation.y -= 0.01;
      core.rotation.z += 0.005;

      const dist = Math.sqrt(mouseRef.current.x ** 2 + mouseRef.current.y ** 2);
      sphere.scale.setScalar(1 + dist * 0.1);
      scene.rotation.y = mouseRef.current.x * 0.4;
      scene.rotation.x = mouseRef.current.y * -0.4;

      core.scale.setScalar(1 + Math.sin(Date.now() * 0.004) * 0.1);
      particleSystem.rotation.y += 0.001;
      renderer.render(scene, camera);
    };

    animate();

    const handleMouseMove = (e: MouseEvent) => {
      const rect = containerRef.current?.getBoundingClientRect();
      if (rect) {
        targetMouseRef.current = {
          x: ((e.clientX - rect.left) / rect.width) * 2 - 1,
          y: ((e.clientY - rect.top) / rect.height) * 2 - 1
        };
      }
    };

    window.addEventListener('mousemove', handleMouseMove);
    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      if (requestRef.current) cancelAnimationFrame(requestRef.current);
      if (rendererRef.current) {
        containerRef.current?.removeChild(rendererRef.current.domElement);
        rendererRef.current.dispose();
      }
    };
  }, []);

  return (
    <div className="absolute bottom-6 right-6 z-50 flex flex-col items-center gap-4 group">
      <div ref={containerRef} onClick={onToggle} className={`w-40 h-40 rounded-full cursor-pointer transition-all duration-700 ${active ? 'scale-125' : 'scale-100 opacity-80 hover:opacity-100'} filter drop-shadow-[0_0_35px_rgba(59,130,246,0.4)]`} />
      <div className={`flex flex-col items-center gap-2 transition-all duration-700 transform ${active ? 'translate-y-0 scale-100 opacity-100' : 'translate-y-10 scale-90 opacity-0 pointer-events-none'}`}>
        <div className="bg-[#0b0e14]/80 backdrop-blur-2xl border border-white/10 p-5 rounded-[2rem] flex flex-col gap-4 shadow-2xl ring-1 ring-white/10 min-w-[200px]">
          <div className="flex flex-col items-center">
            <p className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400 mb-1">Neural Engine</p>
            <div className="h-0.5 w-8 bg-blue-500/30 rounded-full"></div>
          </div>
          <div className="flex flex-col gap-2">
            <button onClick={(e) => { e.stopPropagation(); alert("Preparing Spatial AR Build..."); }} className="px-4 py-2 bg-blue-500/10 hover:bg-blue-500/20 border border-blue-500/20 rounded-xl text-[9px] font-black uppercase tracking-widest text-blue-200 transition-all hover:scale-[1.02] active:scale-95">AR Manifest</button>
            <button onClick={(e) => { e.stopPropagation(); alert("Spatial Sync: Initiated..."); }} className="px-4 py-2 bg-purple-500/10 hover:bg-purple-500/20 border border-purple-500/20 rounded-xl text-[9px] font-black uppercase tracking-widest text-purple-200 transition-all hover:scale-[1.02] active:scale-95">Spatial Link</button>
          </div>
        </div>
      </div>
      {!active && (
        <div className="absolute -top-12 left-1/2 -translate-x-1/2 whitespace-nowrap bg-blue-600 text-white text-[10px] font-black uppercase tracking-widest px-4 py-1.5 rounded-full opacity-0 group-hover:opacity-100 transition-all duration-500 pointer-events-none shadow-xl border border-blue-400/50">Neural Preview</div>
      )}
    </div>
  );
};

