import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .vayu-container {
      position: relative;
      padding: 4rem;
      border-radius: 2rem;
      background: rgba(255, 255, 255, 0.02);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.05em;
      filter: drop-shadow(0 0 15px rgba(59, 130, 246, 0.3));
    }
  </style>
</head>
<body>
  <div class="vayu-container">
    <h1 class="vayu-logo">VAYU</h1>
    <div class="flex items-center gap-3 justify-center mt-4">
      <span class="text-xs font-mono uppercase tracking-widest text-slate-500">Neural Environment Active</span>
    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_2_0);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [isPuterAuth, setIsPuterAuth] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  // Fix Puter.js Auth Error
  useEffect(() => {
    const initPuter = async () => {
      if (window.puter) {
        try {
          // Some environments might return a boolean, others a promise. 
          // Async/await handles both gracefully.
          const signedIn = await window.puter.auth.isSignedIn();
          setIsPuterAuth(!!signedIn);
        } catch (e) {
          console.error("Puter Auth initialization error:", e);
        }
      }
    };
    initPuter();
  }, []);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';
    let bundled = index;
    if (style) bundled = bundled.includes('</head>') ? bundled.replace('</head>', `<style>${style}</style></head>`) : `<style>${style}</style>` + bundled;
    if (script) bundled = bundled.includes('</body>') ? bundled.replace('</body>', `<script>${script}</script></body>`) : bundled + `<script>${script}</script>`;
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  const handleCopyCode = (code: string) => navigator.clipboard.writeText(code);

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ path, content, language: path.split('.').pop() || 'plaintext' });
          updated = true;
          // Auto-switch to new file if it's the first time we see it
          if (path.includes('index.html') || path.includes('style.css') || path.includes('script.js')) {
            // we don't switch inside setState, we handle it after
          }
        }
      }
      return updated ? newFiles : currentFiles;
    });
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: currentPrompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemInstruction = `You are Vayu IDE, a highly advanced browser-based development environment.
Your primary directive is to architect and refine code for the user.
CURRENT WORKSPACE FILES: ${files.map(f => f.path).join(', ')}

STRICT FORMATTING RULE:
To update or create a file, you MUST use the following format exactly:
[FILE: filename.ext]
\`\`\`language
// code goes here
\`\`\`

ALWAYS provide the full content of the file to ensure the IDE updates correctly.
Be extremely accurate. If requested to refine, look for bugs or design improvements.
Maintain conversational memory to understand previous steps.`;

      let fullContent = '';
      if (activeModel.includes('gemini')) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        if (!chatInstanceRef.current) {
          chatInstanceRef.current = ai.chats.create({
            model: 'gemini-3-flash-preview',
            config: { systemInstruction }
          });
        }

        const response = await chatInstanceRef.current.sendMessageStream({ message: currentPrompt });
        for await (const chunk of response) {
          fullContent += chunk.text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      } else {
        // Fallback for Puter.js models
        const stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, { model: activeModel, stream: true });
        for await (const chunk of stream) {
          fullContent += (typeof chunk === 'string' ? chunk : chunk.text || chunk.message?.content || "");
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error: any) {
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: error.message || "Neural link failure.", isStreaming: false, error: "Sync failed." } : m));
    } finally {
      setIsGenerating(false);
    }
  };

  const renderCodeWithActions = (snippet: string, fileName?: string) => (
    <div className="my-5 rounded-xl overflow-hidden bg-slate-950/50 border border-white/10 group/snippet relative shadow-xl backdrop-blur-sm">
      <div className="flex justify-between items-center px-4 py-2 bg-white/5 border-b border-white/5">
        <span className="text-[10px] uppercase font-bold text-slate-400 tracking-wider flex items-center gap-2">
           <div className="w-1.5 h-1.5 rounded-full bg-blue-500"></div> 
           {fileName || "Code Fragment"}
        </span>
        <div className="flex items-center gap-2.5">
          <button 
            onClick={() => handleSendMessage(`Debug this code specifically:\n\`\`\`\n${snippet}\n\`\`\``)} 
            className="text-slate-500 hover:text-amber-400 transition-colors p-1" 
            title="Debug Code"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" strokeWidth="2.5"/></svg>
          </button>
          <button 
            onClick={() => handleSendMessage(`Refine and optimize this part:\n\`\`\`\n${snippet}\n\`\`\``)} 
            className="text-slate-500 hover:text-emerald-400 transition-colors p-1" 
            title="Refine Code"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" strokeWidth="2.5"/></svg>
          </button>
          <button 
            onClick={() => handleCopyCode(snippet)} 
            className="text-slate-500 hover:text-blue-400 transition-colors p-1" 
            title="Copy to Clipboard"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" strokeWidth="2.5"/></svg>
          </button>
        </div>
      </div>
      <pre className="p-4 text-[12px] font-mono overflow-x-auto custom-scrollbar text-blue-100/90 leading-relaxed"><code>{snippet}</code></pre>
    </div>
  );

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 ring-1 ring-white/10">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')} className="p-3 rounded-xl transition-all text-slate-500 hover:text-blue-400 hover:bg-blue-400/10" title="Neural Search">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Content */}
      <div className="w-[440px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/80 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Link' : 'Workspace Assets'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10 transition-colors cursor-pointer appearance-none pr-6 font-bold">
              <option value={AIModel.GEMINI_2_0}>Gemini 2.0 Flash</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5 Sonnet</option>
              <option value={AIModel.GPT_4O}>GPT-4o</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-44 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-40 select-none animate-fade-in">
                  <div className="w-20 h-20 bg-blue-500/5 rounded-3xl flex items-center justify-center border border-blue-500/10 mb-6">
                    <svg className="w-10 h-10 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.2"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.3em] text-blue-400">Puter Neural Link Ready</h3>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-5 rounded-2xl text-[13.5px] shadow-lg border transition-all duration-300 ${
                    msg.role === 'user' ? 'bg-blue-600/90 backdrop-blur-md text-white border-blue-400/30 rounded-br-none' : 'bg-white/5 backdrop-blur-2xl text-slate-200 border-white/10 rounded-bl-none'
                  }`}>
                    <div className="whitespace-pre-wrap font-normal leading-relaxed">
                      {msg.content.includes('[FILE:') ? msg.content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part, i) => {
                        const fileMatch = msg.content.match(/\[FILE:\s*([a-zA-Z0-9._\-/]+)\]/g);
                        const fileName = fileMatch?.[i-1]?.replace('[FILE: ', '').replace(']', '');
                        return part.split('```').map((snippet, sIdx) => {
                          if (sIdx % 2 === 1) return renderCodeWithActions(snippet, fileName);
                          return snippet;
                        });
                      }) : msg.content.split('```').map((part, pIdx) => {
                        if (pIdx % 2 === 1) return renderCodeWithActions(part);
                        return part;
                      })}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/90 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/95 backdrop-blur-3xl border border-white/10 rounded-3xl p-4 shadow-2xl ring-1 ring-white/10 focus-within:ring-blue-500/40 transition-all duration-700 pointer-events-auto">
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} 
                  placeholder="Ask Vayu to architect software..." 
                  className="w-full bg-transparent outline-none resize-none text-[13.5px] min-h-[50px] max-h-[160px] placeholder:text-slate-600 font-medium px-4 py-2" 
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-3 ml-2">
                    <div className={`w-2 h-2 rounded-full transition-all duration-1000 ${currentStatus === 'analyzing' ? 'bg-amber-400' : currentStatus === 'coding' ? 'bg-blue-400' : 'bg-slate-700'}`}></div>
                    <span className="text-[9px] text-slate-600 font-black uppercase tracking-widest">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-8 py-2.5 rounded-xl font-black text-[10.5px] uppercase tracking-[0.2em] transition-all transform active:scale-95 ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-xl shadow-blue-500/20'}`}>
                    {isGenerating ? 'Synthesizing' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1 bg-[#0b0e14]">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[12px] transition-all border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-medium">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Editor & Preview */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14]">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            <div className="px-3 py-1 bg-blue-500/10 text-[9px] font-black text-blue-400/70 rounded-lg border border-blue-500/20 uppercase tracking-widest">{activeFile.language}</div>
          </div>
          <div className="flex items-center gap-3 text-[9.5px] font-black uppercase text-green-500 bg-green-500/5 px-4 py-1.5 rounded-full border border-green-500/15">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div> Synchronized
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden">
            <Editor 
              height="100%" 
              path={activeFile.path} 
              language={activeFile.language} 
              theme="vs-dark" 
              value={activeFile.content} 
              // Fix: cursorSmoothCaretAnimation should be 'on' (string) instead of true (boolean)
              options={{ minimap: { enabled: false }, fontSize: 14.5, fontFamily: "'Fira Code', monospace", backgroundColor: '#0b0e14', padding: { top: 32 }, lineNumbers: 'on', automaticLayout: true, cursorBlinking: 'smooth', cursorSmoothCaretAnimation: 'on', smoothScrolling: true, renderLineHighlight: 'all', scrollBeyondLastLine: false }} 
              onChange={(val) => {
                setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .vayu-container {
      position: relative;
      padding: 4rem;
      border-radius: 2rem;
      background: rgba(255, 255, 255, 0.02);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.05em;
      filter: drop-shadow(0 0 15px rgba(59, 130, 246, 0.3));
    }
  </style>
</head>
<body>
  <div class="vayu-container">
    <h1 class="vayu-logo">VAYU</h1>
    <div class="flex items-center gap-3 justify-center mt-4">
      <span class="text-xs font-mono uppercase tracking-widest text-slate-500">Neural Environment Active</span>
    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_2_0);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [isPuterAuth, setIsPuterAuth] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const filesRef = useRef<FileEntry[]>(INITIAL_FILES);

  // Sync ref for AI context
  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  useEffect(() => {
    const initPuter = async () => {
      if (window.puter) {
        try {
          const signedIn = await window.puter.auth.isSignedIn();
          setIsPuterAuth(!!signedIn);
        } catch (e) {
          console.error("Puter Auth initialization error:", e);
        }
      }
    };
    initPuter();
  }, []);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';
    let bundled = index;
    if (style) bundled = bundled.includes('</head>') ? bundled.replace('</head>', `<style>${style}</style></head>`) : `<style>${style}</style>` + bundled;
    if (script) bundled = bundled.includes('</body>') ? bundled.replace('</body>', `<script>${script}</script></body>`) : bundled + `<script>${script}</script>`;
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  const handleCopyCode = (code: string) => navigator.clipboard.writeText(code);

  const parseAndApplyFiles = (text: string) => {
    // Robust regex to handle partial blocks during streaming
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ path, content, language: path.split('.').pop() || 'plaintext' });
          updated = true;
        }
      }
      return updated ? newFiles : currentFiles;
    });
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: currentPrompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      // Create a contextual snapshot of current workspace for the AI
      const workspaceContext = filesRef.current.map(f => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');

      const systemInstruction = `You are Vayu IDE, a world-class browser-based IDE powered by advanced AI. 
Like Cursor and Google AI Studio, you have deep awareness of the entire project.

WORKSPACE CONTEXT:
${workspaceContext}

USER OBJECTIVE:
Help the user build, debug, and optimize code within this workspace.

STRICT OUTPUT PROTOCOL:
1. When generating or modifying files, you MUST use this header: [FILE: path/to/file.ext]
2. Followed immediately by a markdown code block containing the FULL content of that file.
3. If you suggest multiple files, repeat the pattern for each.
4. Maintain a professional, concise, and technical tone.
5. If the user asks for a change, analyze existing code first, then provide updated versions.

Your responses should be accurate, performant, and follow best practices.`;

      let fullContent = '';
      if (activeModel.includes('gemini')) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Re-initialize or maintain chat instance for conversational memory
        if (!chatInstanceRef.current) {
          chatInstanceRef.current = ai.chats.create({
            model: 'gemini-3-flash-preview',
            config: { systemInstruction }
          });
        }

        const response = await chatInstanceRef.current.sendMessageStream({ message: currentPrompt });
        for await (const chunk of response) {
          fullContent += chunk.text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      } else {
        // Puter AI models - usually single turn, but we wrap in context
        const contextPrompt = `CONTEXT:\n${workspaceContext}\n\nUSER REQUEST:\n${currentPrompt}`;
        const stream = await window.puter.ai.chat(`${systemInstruction}\n\n${contextPrompt}`, { model: activeModel, stream: true });
        for await (const chunk of stream) {
          fullContent += (typeof chunk === 'string' ? chunk : chunk.text || chunk.message?.content || "");
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error: any) {
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: error.message || "Uplink disruption.", isStreaming: false, error: "Sync failed." } : m));
    } finally {
      setIsGenerating(false);
    }
  };

  const renderCodeWithActions = (snippet: string, fileName?: string) => (
    <div className="my-5 rounded-xl overflow-hidden bg-[#05070a]/80 border border-white/10 group/snippet relative shadow-2xl backdrop-blur-sm">
      <div className="flex justify-between items-center px-4 py-2.5 bg-white/5 border-b border-white/5">
        <span className="text-[10px] uppercase font-bold text-blue-400 tracking-wider flex items-center gap-2">
           <div className="w-1.5 h-1.5 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]"></div> 
           {fileName || "Buffer"}
        </span>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => handleSendMessage(`Analyze and fix potential bugs in this snippet:\n\`\`\`\n${snippet}\n\`\`\``)} 
            className="text-slate-400 hover:text-amber-400 transition-all p-1.5 hover:bg-white/5 rounded-lg" 
            title="Deep Debug"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" strokeWidth="2"/></svg>
          </button>
          <button 
            onClick={() => handleSendMessage(`Refactor and optimize this logic for performance and readability:\n\`\`\`\n${snippet}\n\`\`\``)} 
            className="text-slate-400 hover:text-emerald-400 transition-all p-1.5 hover:bg-white/5 rounded-lg" 
            title="Optimize"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" strokeWidth="2"/></svg>
          </button>
          <button 
            onClick={() => handleCopyCode(snippet)} 
            className="text-slate-400 hover:text-blue-400 transition-all p-1.5 hover:bg-white/5 rounded-lg" 
            title="Copy"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" strokeWidth="2"/></svg>
          </button>
        </div>
      </div>
      <pre className="p-4 text-[12px] font-mono overflow-x-auto custom-scrollbar text-blue-100/90 leading-relaxed bg-[#05070a]"><code>{snippet}</code></pre>
    </div>
  );

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 ring-1 ring-white/10 select-none">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')} className="p-3 rounded-xl transition-all text-slate-500 hover:text-blue-400 hover:bg-blue-400/10" title="Neural Search">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[420px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.15em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/50 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse shadow-[0_0_8px_#3b82f6]' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Architect Neural Link' : 'Workspace Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10 transition-colors cursor-pointer appearance-none pr-6 font-bold uppercase tracking-widest">
              <option value={AIModel.GEMINI_2_0}>Gemini 2.0 Flash</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5 Sonnet</option>
              <option value={AIModel.GPT_4O}>GPT-4o</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-44 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 select-none animate-fade-in">
                  <div className="w-16 h-16 bg-blue-500/5 rounded-2xl flex items-center justify-center border border-blue-500/10 mb-4">
                    <svg className="w-8 h-8 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400">Contextual Engine Ready</h3>
                  <p className="text-[11px] mt-2 max-w-[200px] leading-relaxed">"Build high-performance software with native Puter.js intelligence."</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-lg border transition-all duration-300 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 rounded-br-none' : 'bg-white/5 backdrop-blur-md text-slate-200 border-white/10 rounded-bl-none'
                  }`}>
                    <div className="whitespace-pre-wrap font-normal leading-relaxed">
                      {msg.content.includes('[FILE:') ? msg.content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part, i) => {
                        const fileMatch = msg.content.match(/\[FILE:\s*([a-zA-Z0-9._\-/]+)\]/g);
                        const fileName = fileMatch?.[i-1]?.replace('[FILE: ', '').replace(']', '');
                        return part.split('```').map((snippet, sIdx) => {
                          if (sIdx % 2 === 1) return renderCodeWithActions(snippet, fileName);
                          return snippet;
                        });
                      }) : msg.content.split('```').map((part, pIdx) => {
                        if (pIdx % 2 === 1) return renderCodeWithActions(part);
                        return part;
                      })}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/95 backdrop-blur-2xl border border-white/10 rounded-2xl p-3.5 shadow-2xl ring-1 ring-white/10 focus-within:ring-blue-500/40 transition-all duration-500 pointer-events-auto">
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} 
                  placeholder="Ask Vayu to build, fix, or optimize..." 
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[44px] max-h-[140px] placeholder:text-slate-600 font-medium px-3 py-1.5" 
                />
                <div className="flex justify-between items-center mt-2.5 pt-2.5 border-t border-white/5">
                  <div className="flex items-center gap-2.5 ml-1.5">
                    <div className={`w-1.5 h-1.5 rounded-full transition-all duration-700 ${currentStatus === 'analyzing' ? 'bg-amber-400' : currentStatus === 'coding' ? 'bg-blue-400 animate-pulse' : 'bg-slate-700'}`}></div>
                    <span className="text-[8.5px] text-slate-500 font-bold uppercase tracking-widest select-none">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-[0.15em] transition-all transform active:scale-95 ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20'}`}>
                    {isGenerating ? 'Uplinking' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1.5 bg-[#0b0e14]">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[12px] transition-all border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-medium">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Editor & Preview Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14]">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 sticky top-0 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            <div className="px-2.5 py-0.5 bg-blue-500/10 text-[8px] font-black text-blue-400/70 rounded border border-blue-500/20 uppercase tracking-tighter">{activeFile.language}</div>
          </div>
          <div className="flex items-center gap-2.5 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div> Local Sync Active
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden">
            <Editor 
              height="100%" 
              path={activeFile.path} 
              language={activeFile.language} 
              theme="vs-dark" 
              value={activeFile.content} 
              options={{ 
                minimap: { enabled: false }, 
                fontSize: 14, 
                fontFamily: "'Fira Code', monospace", 
                backgroundColor: '#0b0e14', 
                padding: { top: 32 }, 
                lineNumbers: 'on', 
                automaticLayout: true, 
                cursorBlinking: 'smooth', 
                cursorSmoothCaretAnimation: 'on', 
                smoothScrolling: true, 
                renderLineHighlight: 'all', 
                scrollBeyondLastLine: false,
                fontLigatures: true,
                letterSpacing: 0.5
              }} 
              onChange={(val) => {
                setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

export enum AIModel {
  CLAUDE_3_5 = 'claude-3-5-sonnet',
  GPT_4O = 'gpt-4o',
  GEMINI_3_PRO = 'gemini-3-pro-preview',
}

export interface AIConfig {
  temperature: number;
  topP: number;
  maxTokens: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: string;
  config?: AIConfig;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'idle';
  error?: string;
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
    JSZip: any;
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .vayu-container {
      position: relative;
      padding: 4rem;
      border-radius: 2rem;
      background: rgba(255, 255, 255, 0.02);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.05em;
      filter: drop-shadow(0 0 15px rgba(59, 130, 246, 0.3));
    }
  </style>
</head>
<body>
  <div class="vayu-container">
    <h1 class="vayu-logo">VAYU</h1>
    <div class="flex items-center gap-3 justify-center mt-4">
      <span class="text-xs font-mono uppercase tracking-widest text-slate-500">Neural Environment Active</span>
    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  // Update to Gemini 3 Pro for coding tasks
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_3_PRO);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [isPuterAuth, setIsPuterAuth] = useState(false);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const filesRef = useRef<FileEntry[]>(INITIAL_FILES);

  // Sync ref for AI context
  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  useEffect(() => {
    const initPuter = async () => {
      if (window.puter) {
        try {
          const signedIn = await window.puter.auth.isSignedIn();
          setIsPuterAuth(!!signedIn);
        } catch (e) {
          console.error("Puter Auth initialization error:", e);
        }
      }
    };
    initPuter();
  }, []);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';
    let bundled = index;
    if (style) bundled = bundled.includes('</head>') ? bundled.replace('</head>', `<style>${style}</style></head>`) : `<style>${style}</style>` + bundled;
    if (script) bundled = bundled.includes('</body>') ? bundled.replace('</body>', `<script>${script}</script></body>`) : bundled + `<script>${script}</script>`;
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  const handleCopyCode = (code: string) => navigator.clipboard.writeText(code);

  const parseAndApplyFiles = (text: string) => {
    // Robust regex to handle partial blocks during streaming
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ path, content, language: path.split('.').pop() || 'plaintext' });
          updated = true;
        }
      }
      return updated ? newFiles : currentFiles;
    });
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: currentPrompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      // Create a contextual snapshot of current workspace for the AI
      const workspaceContext = filesRef.current.map(f => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');

      const systemInstruction = `You are Vayu IDE, a world-class browser-based IDE powered by advanced AI. 
Like Cursor and Google AI Studio, you have deep awareness of the entire project.

WORKSPACE CONTEXT:
${workspaceContext}

USER OBJECTIVE:
Help the user build, debug, and optimize code within this workspace.

STRICT OUTPUT PROTOCOL:
1. When generating or modifying files, you MUST use this header: [FILE: path/to/file.ext]
2. Followed immediately by a markdown code block containing the FULL content of that file.
3. If you suggest multiple files, repeat the pattern for each.
4. Maintain a professional, concise, and technical tone.
5. If the user asks for a change, analyze existing code first, then provide updated versions.

Your responses should be accurate, performant, and follow best practices.`;

      let fullContent = '';
      if (activeModel.includes('gemini')) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

        // Re-initialize or maintain chat instance for conversational memory with Gemini 3 Pro
        if (!chatInstanceRef.current) {
          chatInstanceRef.current = ai.chats.create({
            model: 'gemini-3-pro-preview',
            config: { systemInstruction }
          });
        }

        const response = await chatInstanceRef.current.sendMessageStream({ message: currentPrompt });
        for await (const chunk of response) {
          fullContent += chunk.text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      } else {
        // Puter AI models - usually single turn, but we wrap in context
        const contextPrompt = `CONTEXT:\n${workspaceContext}\n\nUSER REQUEST:\n${currentPrompt}`;
        const stream = await window.puter.ai.chat(`${systemInstruction}\n\n${contextPrompt}`, { model: activeModel, stream: true });
        for await (const chunk of stream) {
          fullContent += (typeof chunk === 'string' ? chunk : chunk.text || chunk.message?.content || "");
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
    } catch (error: any) {
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: error.message || "Uplink disruption.", isStreaming: false, error: "Sync failed." } : m));
    } finally {
      setIsGenerating(false);
    }
  };

  const renderCodeWithActions = (snippet: string, fileName?: string) => (
    <div className="my-5 rounded-xl overflow-hidden bg-[#05070a]/80 border border-white/10 group/snippet relative shadow-2xl backdrop-blur-sm">
      <div className="flex justify-between items-center px-4 py-2.5 bg-white/5 border-b border-white/5">
        <span className="text-[10px] uppercase font-bold text-blue-400 tracking-wider flex items-center gap-2">
           <div className="w-1.5 h-1.5 rounded-full bg-blue-500 shadow-[0_0_8px_rgba(59,130,246,0.5)]"></div> 
           {fileName || "Buffer"}
        </span>
        <div className="flex items-center gap-3">
          <button 
            onClick={() => handleSendMessage(`Analyze and fix potential bugs in this snippet:\n\`\`\`\n${snippet}\n\`\`\``)} 
            className="text-slate-400 hover:text-amber-400 transition-all p-1.5 hover:bg-white/5 rounded-lg" 
            title="Deep Debug"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" strokeWidth="2"/></svg>
          </button>
          <button 
            onClick={() => handleSendMessage(`Refactor and optimize this logic for performance and readability:\n\`\`\`\n${snippet}\n\`\`\``)} 
            className="text-slate-400 hover:text-emerald-400 transition-all p-1.5 hover:bg-white/5 rounded-lg" 
            title="Optimize"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M5 3v4M3 5h4M6 17v4m-2-2h4m5-16l2.286 6.857L21 12l-7.714 2.143L11 21l-2.286-6.857L1 12l7.714-2.143L11 3z" strokeWidth="2"/></svg>
          </button>
          <button 
            onClick={() => handleCopyCode(snippet)} 
            className="text-slate-400 hover:text-blue-400 transition-all p-1.5 hover:bg-white/5 rounded-lg" 
            title="Copy"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M8 7v8a2 2 0 002 2h6M8 7V5a2 2 0 012-2h4.586a1 1 0 01.707.293l4.414 4.414a1 1 0 01.293.707V15a2 2 0 01-2 2h-2M8 7H6a2 2 0 00-2 2v10a2 2 0 002 2h8a2 2 0 002-2v-2" strokeWidth="2"/></svg>
          </button>
        </div>
      </div>
      <pre className="p-4 text-[12px] font-mono overflow-x-auto custom-scrollbar text-blue-100/90 leading-relaxed bg-[#05070a]"><code>{snippet}</code></pre>
    </div>
  );

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 ring-1 ring-white/10 select-none">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 shadow-[inset_0_0_15px_rgba(59,130,246,0.1)]' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')} className="p-3 rounded-xl transition-all text-slate-500 hover:text-blue-400 hover:bg-blue-400/10" title="Neural Search">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[420px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.15em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/50 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse shadow-[0_0_8px_#3b82f6]' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Architect Neural Link' : 'Workspace Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none hover:bg-white/10 transition-colors cursor-pointer appearance-none pr-6 font-bold uppercase tracking-widest">
              <option value={AIModel.GEMINI_3_PRO}>Gemini 3 Pro</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5 Sonnet</option>
              <option value={AIModel.GPT_4O}>GPT-4o</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-44 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 select-none animate-fade-in">
                  <div className="w-16 h-16 bg-blue-500/5 rounded-2xl flex items-center justify-center border border-blue-500/10 mb-4">
                    <svg className="w-8 h-8 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400">Contextual Engine Ready</h3>
                  <p className="text-[11px] mt-2 max-w-[200px] leading-relaxed">"Build high-performance software with native Puter.js intelligence."</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-lg border transition-all duration-300 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 rounded-br-none' : 'bg-white/5 backdrop-blur-md text-slate-200 border-white/10 rounded-bl-none'
                  }`}>
                    <div className="whitespace-pre-wrap font-normal leading-relaxed">
                      {msg.content.includes('[FILE:') ? msg.content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part, i) => {
                        const fileMatch = msg.content.match(/\[FILE:\s*([a-zA-Z0-9._\-/]+)\]/g);
                        const fileName = fileMatch?.[i-1]?.replace('[FILE: ', '').replace(']', '');
                        return part.split('```').map((snippet, sIdx) => {
                          if (sIdx % 2 === 1) return renderCodeWithActions(snippet, fileName);
                          return snippet;
                        });
                      }) : msg.content.split('```').map((part, pIdx) => {
                        if (pIdx % 2 === 1) return renderCodeWithActions(part);
                        return part;
                      })}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/95 backdrop-blur-2xl border border-white/10 rounded-2xl p-3.5 shadow-2xl ring-1 ring-white/10 focus-within:ring-blue-500/40 transition-all duration-500 pointer-events-auto">
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} 
                  placeholder="Ask Vayu to build, fix, or optimize..." 
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[44px] max-h-[140px] placeholder:text-slate-600 font-medium px-3 py-1.5" 
                />
                <div className="flex justify-between items-center mt-2.5 pt-2.5 border-t border-white/5">
                  <div className="flex items-center gap-2.5 ml-1.5">
                    <div className={`w-1.5 h-1.5 rounded-full transition-all duration-700 ${currentStatus === 'analyzing' ? 'bg-amber-400' : currentStatus === 'coding' ? 'bg-blue-400 animate-pulse' : 'bg-slate-700'}`}></div>
                    <span className="text-[8.5px] text-slate-500 font-bold uppercase tracking-widest select-none">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-[0.15em] transition-all transform active:scale-95 ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20'}`}>
                    {isGenerating ? 'Uplinking' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1.5 bg-[#0b0e14]">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[12px] transition-all border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-medium">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Editor & Preview Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14]">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 sticky top-0 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            <div className="px-2.5 py-0.5 bg-blue-500/10 text-[8px] font-black text-blue-400/70 rounded border border-blue-500/20 uppercase tracking-tighter">{activeFile.language}</div>
          </div>
          <div className="flex items-center gap-2.5 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div> Local Sync Active
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden">
            <Editor 
              height="100%" 
              path={activeFile.path} 
              language={activeFile.language} 
              theme="vs-dark" 
              value={activeFile.content} 
              options={{ 
                minimap: { enabled: false }, 
                fontSize: 14, 
                fontFamily: "'Fira Code', monospace", 
                // Fix for: Object literal may only specify known properties, and 'backgroundColor' does not exist in type 'IStandaloneEditorConstructionOptions'
                padding: { top: 32 }, 
                lineNumbers: 'on', 
                automaticLayout: true, 
                cursorBlinking: 'smooth', 
                cursorSmoothCaretAnimation: 'on', 
                smoothScrolling: true, 
                renderLineHighlight: 'all', 
                scrollBeyondLastLine: false,
                fontLigatures: true,
                letterSpacing: 0.5
              }} 
              onChange={(val) => {
                setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .vayu-container {
      position: relative;
      padding: 4rem;
      border-radius: 2rem;
      background: rgba(255, 255, 255, 0.02);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.05em;
      filter: drop-shadow(0 0 15px rgba(59, 130, 246, 0.3));
    }
  </style>
</head>
<body>
  <div class="vayu-container">
    <h1 class="vayu-logo">VAYU</h1>
    <div class="flex items-center gap-3 justify-center mt-4">
      <span class="text-xs font-mono uppercase tracking-widest text-slate-500">Neural Environment Active</span>
    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_3_PRO);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [streamingFile, setStreamingFile] = useState<string | null>(null);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const filesRef = useRef<FileEntry[]>(INITIAL_FILES);

  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';
    let bundled = index;
    if (style) bundled = bundled.includes('</head>') ? bundled.replace('</head>', `<style>${style}</style></head>`) : `<style>${style}</style>` + bundled;
    if (script) bundled = bundled.includes('</body>') ? bundled.replace('</body>', `<script>${script}</script></body>`) : bundled + `<script>${script}</script>`;
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ path, content, language: path.split('.').pop() || 'plaintext' });
          updated = true;
        }
      }
      return updated ? newFiles : currentFiles;
    });

    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
    }
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: currentPrompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    setStreamingFile(null);

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      const workspaceContext = filesRef.current.map(f => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');
      const systemInstruction = `You are Vayu IDE. All code generation MUST happen in the center editor.
To write to a file, use: [FILE: path/to/file.ext]\n\`\`\`language\nFULL_FILE_CONTENT\n\`\`\`
IMPORTANT: Always provide full file content for any modified file.
The user sees the code in the center editor. Your chat response should focus on explaining changes or describing the plan.
The current workspace is:\n${workspaceContext}`;

      let fullContent = '';
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (!chatInstanceRef.current) {
        chatInstanceRef.current = ai.chats.create({
          model: 'gemini-3-pro-preview',
          config: { systemInstruction }
        });
      }

      const response = await chatInstanceRef.current.sendMessageStream({ message: currentPrompt });
      for await (const chunk of response) {
        fullContent += chunk.text;
        setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
        parseAndApplyFiles(fullContent);
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
      setStreamingFile(null);
    } catch (error: any) {
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: error.message || "Uplink disrupted.", isStreaming: false, error: "Sync failed." } : m));
      setStreamingFile(null);
    } finally {
      setIsGenerating(false);
    }
  };

  // Helper to extract conversational text (exclude code blocks for the "center only" experience)
  const getConversationalText = (content: string) => {
    return content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part, i) => {
      return part.split('```').filter((_, idx) => idx % 2 === 0).join('');
    }).join('').trim();
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30 font-inter">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 ring-1 ring-white/10 select-none">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[380px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.15em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/50 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Link' : 'Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none font-bold">
              <option value={AIModel.GEMINI_3_PRO}>Gemini 3 Pro</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-44 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 select-none">
                  <div className="w-16 h-16 bg-blue-500/5 rounded-2xl flex items-center justify-center border border-blue-500/10 mb-4">
                    <svg className="w-8 h-8 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400">Contextual Engine Ready</h3>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-lg border transition-all duration-300 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 rounded-br-none' : 'bg-white/5 backdrop-blur-md text-slate-200 border-white/10 rounded-bl-none'
                  }`}>
                    {msg.role === 'assistant' && msg.isStreaming && streamingFile && (
                      <div className="mb-3 px-3 py-2 bg-blue-500/10 border border-blue-500/20 rounded-xl flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-blue-500 animate-ping"></div>
                        <span className="text-[10px] font-black uppercase text-blue-400 tracking-tighter">Synthesizing {streamingFile}...</span>
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-normal leading-relaxed">
                      {msg.role === 'user' ? msg.content : getConversationalText(msg.content)}
                    </div>
                    {msg.role === 'assistant' && msg.content.includes('[FILE:') && !msg.isStreaming && (
                      <div className="mt-3 flex flex-wrap gap-2">
                        {Array.from(msg.content.matchAll(/\[FILE:\s*([a-zA-Z0-9._\-/]+)\]/g)).map((match, i) => (
                          <button key={i} onClick={() => setActiveFilePath(match[1])} className="px-2 py-1 bg-white/5 border border-white/10 rounded-lg text-[10px] text-slate-400 hover:text-blue-400 hover:bg-white/10 transition-all font-mono">
                            {match[1]}
                          </button>
                        ))}
                      </div>
                    )}
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/95 backdrop-blur-2xl border border-white/10 rounded-2xl p-3.5 shadow-2xl ring-1 ring-white/10 focus-within:ring-blue-500/40 transition-all duration-500 pointer-events-auto">
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} 
                  placeholder="Build, refine, or optimize..." 
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[44px] max-h-[140px] placeholder:text-slate-600 font-medium px-3 py-1.5" 
                />
                <div className="flex justify-between items-center mt-2.5 pt-2.5 border-t border-white/5">
                  <div className="flex items-center gap-2.5 ml-1.5">
                    <div className={`w-1.5 h-1.5 rounded-full transition-all duration-700 ${currentStatus === 'analyzing' ? 'bg-amber-400' : currentStatus === 'coding' ? 'bg-blue-400 animate-pulse' : 'bg-slate-700'}`}></div>
                    <span className="text-[8.5px] text-slate-500 font-bold uppercase tracking-widest select-none">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-[0.15em] transition-all transform active:scale-95 ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20'}`}>
                    {isGenerating ? 'Synthesizing' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1.5 bg-[#0b0e14]">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[12px] transition-all border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-medium">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Theatre (Editor & Preview) */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14]">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            {streamingFile === activeFile.path && (
              <div className="px-3 py-1 bg-amber-500/10 text-[9px] font-black text-amber-500 rounded border border-amber-500/20 uppercase animate-pulse">Neural Write Active</div>
            )}
          </div>
          <div className="flex items-center gap-2.5 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div> Local Sync Active
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden relative">
          {/* AI Coding Overlay */}
          {isGenerating && streamingFile === activeFile.path && (
            <div className="absolute inset-0 z-10 pointer-events-none">
               <div className="absolute inset-0 bg-blue-500/5 transition-opacity duration-1000"></div>
               <div className="absolute top-8 right-8 flex items-center gap-4 bg-[#0d1117]/90 backdrop-blur-3xl border border-blue-500/30 px-6 py-3 rounded-2xl shadow-[0_0_50px_rgba(59,130,246,0.2)]">
                  <div className="w-3 h-3 rounded-full bg-blue-500 animate-ping"></div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest leading-none">Vayu Neural Core</span>
                    <span className="text-[12px] font-mono text-white mt-1">Applying changes to {streamingFile}...</span>
                  </div>
               </div>
            </div>
          )}

          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden group">
            <Editor 
              height="100%" 
              path={activeFile.path} 
              language={activeFile.language} 
              theme="vs-dark" 
              value={activeFile.content} 
              options={{ 
                minimap: { enabled: false }, 
                fontSize: 14, 
                fontFamily: "'Fira Code', monospace", 
                padding: { top: 32 }, 
                lineNumbers: 'on', 
                automaticLayout: true, 
                cursorBlinking: 'smooth', 
                cursorSmoothCaretAnimation: 'on', 
                smoothScrolling: true, 
                renderLineHighlight: 'all', 
                scrollBeyondLastLine: false,
                fontLigatures: true,
                letterSpacing: 0.5,
                readOnly: isGenerating && streamingFile === activeFile.path
              }} 
              onChange={(val) => {
                if (!isGenerating) {
                  setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
                }
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

export enum AIModel {
  CLAUDE_3_5 = 'claude-3-5-sonnet',
  GPT_4O = 'gpt-4o',
  GEMINI_3_PRO = 'gemini-3-pro-preview',
}

export interface AIConfig {
  temperature: number;
  topP: number;
  maxTokens: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: string;
  config?: AIConfig;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'idle';
  error?: string;
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
    JSZip: any;
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .vayu-container {
      position: relative;
      padding: 4rem;
      border-radius: 2rem;
      background: rgba(255, 255, 255, 0.02);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5);
    }
    .vayu-logo {
      font-size: 5rem;
      font-weight: 900;
      background: linear-gradient(135deg, #3b82f6 0%, #8b5cf6 100%);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.05em;
      filter: drop-shadow(0 0 15px rgba(59, 130, 246, 0.3));
    }
  </style>
</head>
<body>
  <div class="vayu-container">
    <h1 class="vayu-logo">VAYU</h1>
    <div class="flex items-center gap-3 justify-center mt-4">
      <span class="text-xs font-mono uppercase tracking-widest text-slate-500">Neural Environment Active</span>
    </div>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_3_PRO);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [streamingFile, setStreamingFile] = useState<string | null>(null);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const filesRef = useRef<FileEntry[]>(INITIAL_FILES);

  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';
    let bundled = index;
    if (style) bundled = bundled.includes('</head>') ? bundled.replace('</head>', `<style>${style}</style></head>`) : `<style>${style}</style>` + bundled;
    if (script) bundled = bundled.includes('</body>') ? bundled.replace('</body>', `<script>${script}</script></body>`) : bundled + `<script>${script}</script>`;
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `vayu-project-${Date.now()}.zip`;
    link.click();
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ path, content, language: path.split('.').pop() || 'plaintext' });
          updated = true;
        }
      }
      return updated ? newFiles : currentFiles;
    });

    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
    }
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: currentPrompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    setStreamingFile(null);

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      const workspaceContext = filesRef.current.map(f => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');
      const systemInstruction = `You are Vayu IDE. All code generation MUST happen in the center editor.
To write to a file, use: [FILE: path/to/file.ext]\n\`\`\`language\nFULL_FILE_CONTENT\n\`\`\`
IMPORTANT: Always provide full file content for any modified file.
The user sees the code in the center editor. Your chat response should focus on explaining changes or describing the plan.
The current workspace is:\n${workspaceContext}`;

      let fullContent = '';

      if (activeModel.includes('gemini')) {
        const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
        if (!chatInstanceRef.current) {
          chatInstanceRef.current = ai.chats.create({
            model: 'gemini-3-pro-preview',
            config: { systemInstruction }
          });
        }
        const response = await chatInstanceRef.current.sendMessageStream({ message: currentPrompt });
        for await (const chunk of response) {
          fullContent += chunk.text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      } else {
        const stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, { model: activeModel, stream: true });
        for await (const chunk of stream) {
          fullContent += (typeof chunk === 'string' ? chunk : chunk.text || chunk.message?.content || "");
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
      setStreamingFile(null);
    } catch (error: any) {
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: error.message || "Neural link interrupted.", isStreaming: false, error: "Sync failed." } : m));
      setStreamingFile(null);
    } finally {
      setIsGenerating(false);
    }
  };

  const getConversationalText = (content: string) => {
    return content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part, i) => {
      return part.split('```').filter((_, idx) => idx % 2 === 0).join('');
    }).join('').trim();
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30 font-inter">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 ring-1 ring-white/10 select-none">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')} className="p-3 rounded-xl transition-all text-slate-500 hover:text-blue-400 hover:bg-blue-400/10" title="Neural Search">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
          <button onClick={handleDownload} className="p-3 rounded-xl transition-all text-slate-500 hover:text-emerald-400 hover:bg-emerald-400/10" title="Export Project">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[380px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.15em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/50 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Link' : 'Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none font-bold uppercase tracking-widest cursor-pointer hover:bg-white/10 transition-all">
              <option value={AIModel.GEMINI_3_PRO}>Gemini 3 Pro</option>
              <option value={AIModel.GPT_4O}>GPT-4o</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-44 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 select-none animate-fade-in">
                  <div className="w-16 h-16 bg-blue-500/5 rounded-2xl flex items-center justify-center border border-blue-500/10 mb-4">
                    <svg className="w-8 h-8 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400">Contextual Engine Ready</h3>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-lg border transition-all duration-300 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 rounded-br-none' : 'bg-white/5 backdrop-blur-md text-slate-200 border-white/10 rounded-bl-none'
                  }`}>
                    {msg.role === 'assistant' && msg.isStreaming && streamingFile && (
                      <div className="mb-3 px-3 py-2 bg-blue-500/10 border border-blue-500/20 rounded-xl flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-blue-500 animate-ping"></div>
                        <span className="text-[10px] font-black uppercase text-blue-400 tracking-tighter">Modifying {streamingFile}...</span>
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-normal leading-relaxed">
                      {msg.role === 'user' ? msg.content : getConversationalText(msg.content)}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/95 backdrop-blur-3xl border border-white/10 rounded-2xl p-3.5 shadow-2xl ring-1 ring-white/10 focus-within:ring-blue-500/50 focus-within:shadow-[0_0_40px_rgba(59,130,246,0.15)] transition-all duration-500 pointer-events-auto">
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} 
                  placeholder="Ask Vayu anything, modify, add changes, ask for anything..." 
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[44px] max-h-[140px] placeholder:text-slate-600 font-medium px-3 py-1.5" 
                />
                <div className="flex justify-between items-center mt-2.5 pt-2.5 border-t border-white/5">
                  <div className="flex items-center gap-2.5 ml-1.5">
                    <div className={`w-1.5 h-1.5 rounded-full transition-all duration-700 ${currentStatus === 'analyzing' ? 'bg-amber-400 shadow-[0_0_8px_#fbbf24]' : currentStatus === 'coding' ? 'bg-blue-400 animate-pulse shadow-[0_0_8px_#3b82f6]' : 'bg-slate-700'}`}></div>
                    <span className="text-[8.5px] text-slate-500 font-bold uppercase tracking-widest select-none">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-[0.15em] transition-all transform active:scale-95 ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20'}`}>
                    {isGenerating ? 'Uplinking' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1.5 bg-[#0b0e14]">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[12px] transition-all border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-medium">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Theatre (Editor & Preview) */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14]">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 sticky top-0 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            {streamingFile === activeFile.path && (
              <div className="px-3 py-1 bg-amber-500/10 text-[9px] font-black text-amber-500 rounded border border-amber-500/20 uppercase animate-pulse">Neural Write Active</div>
            )}
          </div>
          <div className="flex items-center gap-2.5 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div> Local Sync Active
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden relative">
          {/* AI Coding Overlay */}
          {isGenerating && streamingFile === activeFile.path && (
            <div className="absolute inset-0 z-10 pointer-events-none">
               <div className="absolute inset-0 bg-blue-500/5 transition-opacity duration-1000"></div>
               <div className="absolute top-8 right-8 flex items-center gap-4 bg-[#0d1117]/90 backdrop-blur-3xl border border-blue-500/30 px-6 py-3 rounded-2xl shadow-[0_0_50px_rgba(59,130,246,0.25)] animate-fade-in">
                  <div className="w-3 h-3 rounded-full bg-blue-500 animate-ping"></div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest leading-none">Vayu Neural Core</span>
                    <span className="text-[12px] font-mono text-white mt-1">Applying changes to {streamingFile}...</span>
                  </div>
               </div>
            </div>
          )}

          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden group">
            <Editor 
              height="100%" 
              path={activeFile.path} 
              language={activeFile.language} 
              theme="vs-dark" 
              value={activeFile.content} 
              options={{ 
                minimap: { enabled: false }, 
                fontSize: 14, 
                fontFamily: "'Fira Code', monospace", 
                padding: { top: 32 }, 
                lineNumbers: 'on', 
                automaticLayout: true, 
                cursorBlinking: 'smooth', 
                cursorSmoothCaretAnimation: 'on', 
                smoothScrolling: true, 
                renderLineHighlight: 'all', 
                scrollBeyondLastLine: false,
                fontLigatures: true,
                letterSpacing: 0.5,
                readOnly: isGenerating && streamingFile === activeFile.path
              }} 
              onChange={(val) => {
                if (!isGenerating) {
                  setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
                }
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative">
            <Preview code={bundledCode} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

