  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_3_PRO);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [streamingFile, setStreamingFile] = useState<string | null>(null);

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const filesRef = useRef<FileEntry[]>(INITIAL_FILES);

  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const bundledCode = useMemo(() => {
    const index = files.find(f => f.path === 'index.html')?.content || '';
    const style = files.find(f => f.path === 'style.css')?.content || '';
    const script = files.find(f => f.path === 'script.js')?.content || '';
    let bundled = index;
    if (style) bundled = bundled.includes('</head>') ? bundled.replace('</head>', `<style>${style}</style></head>`) : `<style>${style}</style>` + bundled;
    if (script) bundled = bundled.includes('</body>') ? bundled.replace('</body>', `<script>${script}</script></body>`) : bundled + `<script>${script}</script>`;
    return bundled;
  }, [files]);

  useEffect(() => {
    if (isGenerating) chatEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const link = document.createElement('a');
    link.href = url;
    link.download = `vayu-project-${Date.now()}.zip`;
    link.click();
  };

  const parseAndApplyFiles = (text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ path, content, language: path.split('.').pop() || 'plaintext' });
          updated = true;
        }
      }
      return updated ? newFiles : currentFiles;
    });

    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
    }
  };

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: currentPrompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    setStreamingFile(null);

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      const workspaceContext = filesRef.current.map(f => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');
      const systemInstruction = `You are Vayu IDE. All code generation MUST happen in the center editor.
To write to a file, use: [FILE: path/to/file.ext]\n\`\`\`language\nFULL_FILE_CONTENT\n\`\`\`
IMPORTANT: Always provide full file content for any modified file.
The current workspace is:\n${workspaceContext}`;

      let fullContent = '';
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (activeModel.includes('gemini')) {
        if (!chatInstanceRef.current) {
          chatInstanceRef.current = ai.chats.create({
            model: 'gemini-3-pro-preview',
            config: { systemInstruction }
          });
        }
        const response = await chatInstanceRef.current.sendMessageStream({ message: currentPrompt });
        for await (const chunk of response) {
          fullContent += chunk.text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      } else {
        const stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, { model: activeModel, stream: true });
        for await (const chunk of stream) {
          fullContent += (typeof chunk === 'string' ? chunk : chunk.text || chunk.message?.content || "");
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
      setStreamingFile(null);
    } catch (error: any) {
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: error.message || "Neural link interrupted.", isStreaming: false, error: "Sync failed." } : m));
      setStreamingFile(null);
    } finally {
      setIsGenerating(false);
    }
  };

  const getConversationalText = (content: string) => {
    return content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part, i) => {
      return part.split('```').filter((_, idx) => idx % 2 === 0).join('');
    }).join('').trim();
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30 font-inter">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#05070a] border-r border-white/5 gap-8">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 ring-1 ring-white/10 select-none">V</div>
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-500 hover:text-slate-300'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-8 bg-white/5 mx-auto"></div>
          <button onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')} className="p-3 rounded-xl transition-all text-slate-500 hover:text-blue-400 hover:bg-blue-400/10" title="Neural Search">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
          <button onClick={handleDownload} className="p-3 rounded-xl transition-all text-slate-500 hover:text-emerald-400 hover:bg-emerald-400/10" title="Export Project">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[380px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="p-4 h-14 border-b border-white/5 font-black uppercase tracking-[0.15em] text-[10px] text-slate-500 flex justify-between items-center bg-[#0d1117]/50 backdrop-blur-md">
          <span className="flex items-center gap-2">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse shadow-[0_0_8px_#3b82f6]' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Link' : 'Explorer'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded px-2 py-1 text-[9px] text-blue-400 outline-none font-bold uppercase tracking-widest cursor-pointer hover:bg-white/10 transition-all">
              <option value={AIModel.GEMINI_3_PRO}>Gemini 3 Pro</option>
              <option value={AIModel.GPT_4O}>GPT-4o</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-5 space-y-6 custom-scrollbar pb-44 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 select-none animate-fade-in">
                  <div className="w-16 h-16 bg-blue-500/5 rounded-2xl flex items-center justify-center border border-blue-500/10 mb-4">
                    <svg className="w-8 h-8 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.2em] text-blue-400">Contextual Engine Ready</h3>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-2 animate-fade-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[95%] p-4 rounded-2xl text-[13px] shadow-lg border transition-all duration-300 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 rounded-br-none' : 'bg-white/5 backdrop-blur-md text-slate-200 border-white/10 rounded-bl-none'
                  }`}>
                    {msg.role === 'assistant' && msg.isStreaming && streamingFile && (
                      <div className="mb-3 px-3 py-2 bg-blue-500/10 border border-blue-500/20 rounded-xl flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-blue-500 animate-ping"></div>
                        <span className="text-[10px] font-black uppercase text-blue-400 tracking-tighter">Modifying {streamingFile}...</span>
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-normal leading-relaxed">
                      {msg.role === 'user' ? msg.content : getConversationalText(msg.content)}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/95 backdrop-blur-3xl border border-white/10 rounded-2xl p-3.5 shadow-2xl ring-1 ring-white/10 focus-within:ring-blue-500/50 focus-within:shadow-[0_0_40px_rgba(59,130,246,0.3)] transition-all duration-500 pointer-events-auto group">
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} 
                  placeholder="Ask Vayu anything, modify, add changes, ask for anything..." 
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[44px] max-h-[140px] placeholder:text-slate-600 font-medium px-3 py-1.5" 
                />
                <div className="flex justify-between items-center mt-2.5 pt-2.5 border-t border-white/5">
                  <div className="flex items-center gap-2.5 ml-1.5">
                    <div className={`w-1.5 h-1.5 rounded-full transition-all duration-700 ${currentStatus === 'analyzing' ? 'bg-amber-400 shadow-[0_0_8px_#fbbf24]' : currentStatus === 'coding' ? 'bg-blue-400 animate-pulse shadow-[0_0_8px_#3b82f6]' : 'bg-slate-700'}`}></div>
                    <span className="text-[8.5px] text-slate-500 font-bold uppercase tracking-widest select-none">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2 rounded-xl font-black text-[10px] uppercase tracking-[0.15em] transition-all transform active:scale-95 ${isGenerating || !prompt.trim() ? 'opacity-20 cursor-not-allowed bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-lg shadow-blue-500/20'}`}>
                    {isGenerating ? 'Uplinking' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-4 space-y-1.5 bg-[#0b0e14]">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-[12px] transition-all border ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-medium">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Main Theatre (Editor & Preview) */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14]">
        <div className="h-14 px-6 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 sticky top-0 backdrop-blur-md">
          <div className="flex items-center gap-4">
            <span className="text-[11px] font-black text-blue-400 uppercase tracking-widest">{activeFile.path}</span>
            {streamingFile === activeFile.path && (
              <div className="px-3 py-1 bg-amber-500/10 text-[9px] font-black text-amber-500 rounded border border-amber-500/20 uppercase animate-pulse">Neural Write Active</div>
            )}
          </div>
          <div className="flex items-center gap-2.5 text-[9px] font-black uppercase text-green-500 bg-green-500/5 px-3 py-1 rounded-full border border-green-500/10">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div> Local Sync Active
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden relative">
          {/* AI Coding Overlay for Editor */}
          {isGenerating && streamingFile === activeFile.path && (
            <div className="absolute inset-0 z-10 pointer-events-none">
               <div className="absolute inset-0 bg-blue-500/5 transition-opacity duration-1000"></div>
               <div className="absolute top-8 right-8 flex items-center gap-4 bg-[#0d1117]/90 backdrop-blur-3xl border border-blue-500/30 px-6 py-3 rounded-2xl shadow-[0_0_50px_rgba(59,130,246,0.25)] animate-fade-in">
                  <div className="w-3 h-3 rounded-full bg-blue-500 animate-ping"></div>
                  <div className="flex flex-col">
                    <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest leading-none">Vayu Neural Core</span>
                    <span className="text-[12px] font-mono text-white mt-1">Applying changes to {streamingFile}...</span>
                  </div>
               </div>
            </div>
          )}

          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden group">
            <Editor 
              height="100%" 
              path={activeFile.path} 
              language={activeFile.language} 
              theme="vs-dark" 
              value={activeFile.content} 
              options={{ 
                minimap: { enabled: false }, 
                fontSize: 14, 
                fontFamily: "'Fira Code', monospace", 
                padding: { top: 32 }, 
                lineNumbers: 'on', 
                automaticLayout: true, 
                cursorBlinking: 'smooth', 
                cursorSmoothCaretAnimation: 'on', 
                smoothScrolling: true, 
                renderLineHighlight: 'all', 
                scrollBeyondLastLine: false,
                fontLigatures: true,
                letterSpacing: 0.5,
                readOnly: isGenerating && streamingFile === activeFile.path
              }} 
              onChange={(val) => {
                if (!isGenerating) {
                  setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
                }
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative">
            <Preview code={bundledCode} isGenerating={isGenerating} />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState } from 'react';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const [isLoadingOutput, setIsLoadingOutput] = useState(false);
  const prevIsGenerating = useRef(isGenerating);

  useEffect(() => {
    // Detect when generation finishes
    if (prevIsGenerating.current && !isGenerating) {
      setIsLoadingOutput(true);
      const timer = setTimeout(() => {
        setIsLoadingOutput(false);
      }, 1000);
      return () => clearTimeout(timer);
    }
    prevIsGenerating.current = isGenerating;
  }, [isGenerating]);

  useEffect(() => {
    if (iframeRef.current && !isGenerating && !isLoadingOutput) {
      iframeRef.current.srcdoc = code;
    }
  }, [code, isGenerating, isLoadingOutput]);

  return (
    <div className="w-full h-full bg-white relative overflow-hidden">
      {/* Actual Content */}
      <iframe
        ref={iframeRef}
        title="Vayu Live Preview"
        className={`w-full h-full border-none transition-opacity duration-700 ${isGenerating || isLoadingOutput ? 'opacity-0' : 'opacity-100'}`}
        sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin"
      />

      {/* Generation Overlay */}
      {isGenerating && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900/90 backdrop-blur-xl z-30 animate-fade-in text-center p-8">
          <div className="w-20 h-20 mb-8 relative">
            <div className="absolute inset-0 border-4 border-blue-500/20 rounded-full"></div>
            <div className="absolute inset-0 border-4 border-t-blue-500 rounded-full animate-spin"></div>
            <div className="absolute inset-4 bg-blue-500/10 rounded-full flex items-center justify-center">
              <div className="w-4 h-4 bg-blue-500 rounded-full animate-pulse shadow-[0_0_15px_#3b82f6]"></div>
            </div>
          </div>
          <h2 className="text-xl font-black text-white uppercase tracking-[0.3em] mb-3">Vayu is generating code</h2>
          <p className="text-slate-400 text-sm max-w-xs leading-relaxed font-medium">Neural core is synthesizing workspace changes in real-time...</p>
        </div>
      )}

      {/* Post-Generation Loading Transition */}
      {!isGenerating && isLoadingOutput && (
        <div className="absolute inset-0 flex flex-col items-center justify-center bg-white z-40 transition-all duration-500">
          <div className="w-48 h-1 bg-slate-100 rounded-full overflow-hidden mb-4">
             <div className="h-full bg-blue-600 animate-[loading_1s_ease-in-out]"></div>
          </div>
          <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Rendering Output...</span>
          <style>{`
            @keyframes loading {
              0% { width: 0%; transform: translateX(-100%); }
              100% { width: 100%; transform: translateX(0%); }
            }
          `}</style>
        </div>
      )}

      {/* Floating Status Badge */}
      <div className="absolute bottom-4 right-4 pointer-events-none z-20">
        <div className="flex items-center gap-2 px-3 py-1.5 bg-[#0b0e14]/90 backdrop-blur-md border border-white/10 rounded-lg text-[10px] font-black uppercase tracking-widest text-blue-400 shadow-xl">
          <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-amber-500 animate-pulse' : 'bg-green-500 animate-pulse'}`} />
          {isGenerating ? 'Synthesizing' : 'Live Instance'}
        </div>
      </div>
    </div>
  );
};

export enum AIModel {
  CLAUDE_3_5 = 'claude-3-5-sonnet',
  GPT_4O = 'gpt-4o',
  GEMINI_3_PRO = 'gemini-3-pro-preview',
}

export interface AIConfig {
  temperature: number;
  topP: number;
  maxTokens: number;
}

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: string;
  config?: AIConfig;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'idle';
  error?: string;
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
    JSZip: any;
  }
}

import React, { useState, useEffect, useRef, useMemo } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
