import React, { useEffect, useRef, useState, useCallback } from 'react';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoadingOutput, setIsLoadingOutput] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const prevIsGenerating = useRef(isGenerating);

  // Handle generation finish animation
  useEffect(() => {
    if (prevIsGenerating.current && !isGenerating) {
      setIsLoadingOutput(true);
      const timer = setTimeout(() => {
        setIsLoadingOutput(false);
      }, 1000);
      return () => clearTimeout(timer);
    }
    prevIsGenerating.current = isGenerating;
  }, [isGenerating]);

  // Update iframe content
  useEffect(() => {
    if (iframeRef.current && !isGenerating && !isLoadingOutput) {
      try {
        iframeRef.current.srcdoc = code;
      } catch (err) {
        console.error("Failed to render preview:", err);
      }
    }
  }, [code, isGenerating, isLoadingOutput]);

  const handleReload = useCallback(() => {
    if (iframeRef.current) {
      setIsLoadingOutput(true);
      // Brief delay to simulate "re-bundling"
      setTimeout(() => {
        if (iframeRef.current) iframeRef.current.srcdoc = code;
        setIsLoadingOutput(false);
      }, 600);
    }
  }, [code]);

  const toggleFullscreen = useCallback(() => {
    if (!containerRef.current) return;

    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen().catch((err) => {
        console.error(`Error attempting to enable full-screen mode: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  }, []);

  useEffect(() => {
    const handler = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', handler);
    return () => document.removeEventListener('fullscreenchange', handler);
  }, []);

  const handlePopOut = useCallback(() => {
    const newWindow = window.open('', '_blank');
    if (newWindow) {
      newWindow.document.write(code);
      newWindow.document.close();
    }
  }, [code]);

  return (
    <div ref={containerRef} className="w-full h-full bg-white relative overflow-hidden transition-all flex flex-col">
      {/* Precision Toolbar - Google AI Studio Inspired */}
      <div className="absolute top-4 right-4 z-50 flex items-center gap-1.5 p-1.5 bg-[#0b0e14]/80 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-300">
        <button 
          onClick={handleReload}
          className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
          title="Reload Preview"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
        </button>
        <button 
          onClick={handlePopOut}
          className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
          title="Open in New Tab"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
          </svg>
        </button>
        <div className="w-px h-4 bg-white/10 mx-0.5" />
        <button 
          onClick={toggleFullscreen}
          className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
          title={isFullscreen ? "Exit Fullscreen" : "Fullscreen Preview"}
        >
          {isFullscreen ? (
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M6 18L18 6M6 6l12 12" />
            </svg>
          ) : (
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
            </svg>
          )}
        </button>
      </div>

      {/* High-Fidelity Content Frame */}
      <div className="flex-1 relative group">
        <iframe
          ref={iframeRef}
          title="Vayu Live Output"
          className={`w-full h-full border-none transition-all duration-1000 transform ${isGenerating || isLoadingOutput ? 'opacity-0 scale-[0.98] blur-2xl grayscale' : 'opacity-100 scale-100 blur-0 grayscale-0'}`}
          sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin"
