              <div className="absolute inset-0 border-[6px] border-t-blue-500 rounded-full animate-spin shadow-[0_0_30px_rgba(59,130,246,0.5)]"></div>
              <div className="absolute inset-8 bg-blue-500/10 rounded-full flex items-center justify-center">
                <div className="w-8 h-8 bg-blue-500 rounded-full animate-pulse shadow-[0_0_35px_#3b82f6]"></div>
              </div>
              <div className="absolute top-0 left-1/2 -ml-1.5 w-3 h-3 bg-blue-400 rounded-full animate-ping opacity-50"></div>
            </div>
            <h2 className="text-3xl font-black text-white uppercase tracking-[0.5em] mb-6 drop-shadow-[0_0_20px_rgba(59,130,246,0.6)]">Neural Synthesis</h2>
            <p className="text-slate-500 text-[11px] max-w-xs leading-relaxed font-bold uppercase tracking-[0.3em]">Architecting workspace modifications in real-time</p>
