import React, { useEffect, useRef, useState, useCallback } from 'react';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
  activeLanguage: 'web' | 'python';
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating, activeLanguage }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoadingOutput, setIsLoadingOutput] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [pythonOutput, setPythonOutput] = useState<string[]>([]);
  const [pyodide, setPyodide] = useState<any>(null);
  const prevIsGenerating = useRef(isGenerating);

  // Initialize Pyodide
  useEffect(() => {
    if (activeLanguage === 'python' && !pyodide && (window as any).loadPyodide) {
      (window as any).loadPyodide().then((res: any) => {
        setPyodide(res);
      });
    }
  }, [activeLanguage, pyodide]);

  // Handle generation finish animation
  useEffect(() => {
    if (prevIsGenerating.current && !isGenerating) {
      setIsLoadingOutput(true);
      const timer = setTimeout(() => {
        setIsLoadingOutput(false);
      }, 1000);
      return () => clearTimeout(timer);
    }
    prevIsGenerating.current = isGenerating;
  }, [isGenerating]);

  // Execute Code based on language
  useEffect(() => {
    if (isGenerating || isLoadingOutput) return;

    if (activeLanguage === 'web') {
      if (iframeRef.current) {
        iframeRef.current.srcdoc = code;
      }
    } else if (activeLanguage === 'python' && pyodide) {
      const runPython = async () => {
        setPythonOutput(['Initializing Python Neural Instance...']);
        try {
          // Redirect stdout
          pyodide.setStdout({
            batched: (text: string) => {
              setPythonOutput(prev => [...prev, text]);
            }
          });
          pyodide.setStderr({
            batched: (text: string) => {
              setPythonOutput(prev => [...prev, `[ERROR] ${text}`]);
            }
          });
          await pyodide.runPythonAsync(code);
        } catch (err: any) {
          setPythonOutput(prev => [...prev, `[RUNTIME ERROR] ${err.message}`]);
        }
      };
      runPython();
    }
  }, [code, isGenerating, isLoadingOutput, activeLanguage, pyodide]);

  const handleReload = useCallback(() => {
    setIsLoadingOutput(true);
    setTimeout(() => {
      setIsLoadingOutput(false);
    }, 600);
  }, []);

  const toggleFullscreen = useCallback(() => {
    if (!containerRef.current) return;
    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen().catch((err) => {
        console.error(`Error enabling full-screen: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  }, []);

  useEffect(() => {
    const handler = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', handler);
    return () => document.removeEventListener('fullscreenchange', handler);
  }, []);

  const handlePopOut = useCallback(() => {
    if (activeLanguage === 'web') {
      const newWindow = window.open('', '_blank');
      if (newWindow) {
        newWindow.document.write(code);
        newWindow.document.close();
      }
    }
  }, [code, activeLanguage]);

  return (
    <div ref={containerRef} className="w-full h-full bg-white relative overflow-hidden transition-all flex flex-col">
      {/* Precision Toolbar */}
      <div className="absolute top-4 right-4 z-50 flex items-center gap-1.5 p-1.5 bg-[#0b0e14]/80 backdrop-blur-xl border border-white/10 rounded-xl shadow-2xl opacity-0 group-hover/preview:opacity-100 transition-opacity duration-300">
        <button 
          onClick={handleReload}
          className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
          title="Reload Preview"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
        </button>
        {activeLanguage === 'web' && (
          <button 
            onClick={handlePopOut}
            className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
            title="Open in New Tab"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
            </svg>
          </button>
        )}
        <div className="w-px h-4 bg-white/10 mx-0.5" />
        <button 
          onClick={toggleFullscreen}
          className="p-2 rounded-lg text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
          title={isFullscreen ? "Exit Fullscreen" : "Fullscreen Preview"}
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
          </svg>
        </button>
      </div>

      {/* High-Fidelity Content Area */}
      <div className="flex-1 relative group">
        {activeLanguage === 'web' ? (
          <iframe
            ref={iframeRef}
            title="Vayu Live Output"
            className={`w-full h-full border-none transition-all duration-1000 transform ${isGenerating || isLoadingOutput ? 'opacity-0 scale-[0.98] blur-2xl grayscale' : 'opacity-100 scale-100 blur-0 grayscale-0'}`}
            sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin"
          />
        ) : (
          <div className={`w-full h-full bg-[#05070a] p-8 font-mono text-sm overflow-auto custom-scrollbar transition-all duration-1000 ${isGenerating || isLoadingOutput ? 'opacity-0 scale-[0.98] blur-2xl' : 'opacity-100 scale-100 blur-0'}`}>
             <div className="flex items-center gap-3 mb-6 text-blue-400 opacity-50 select-none">
                <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M13 10V3L4 14h7v7l9-11h-7z" /></svg>
                <span className="text-[10px] font-black uppercase tracking-[0.2em]">Python Runtime (Pyodide v0.26)</span>
             </div>
             {pythonOutput.map((line, i) => (
               <div key={i} className={`mb-1 ${line.startsWith('[ERROR]') || line.startsWith('[RUNTIME ERROR]') ? 'text-red-400' : 'text-slate-300'}`}>
                 {line}
               </div>
             ))}
             {!pyodide && <div className="text-blue-500 animate-pulse mt-4">Uplinking to Pyodide Neural core...</div>}
             <div className="h-20" />
          </div>
        )}

        {/* Synthesis Overlay */}
        {isGenerating && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900/95 backdrop-blur-3xl z-40 animate-fade-in text-center p-12">
            <div className="w-32 h-32 mb-12 relative">
              <div className="absolute inset-0 border-[6px] border-blue-500/10 rounded-full"></div>
              <div className="absolute inset-0 border-[6px] border-t-blue-500 rounded-full animate-spin shadow-[0_0_30px_rgba(59,130,246,0.5)]"></div>
              <div className="absolute inset-8 bg-blue-500/10 rounded-full flex items-center justify-center">
                <div className="w-8 h-8 bg-blue-500 rounded-full animate-pulse shadow-[0_0_35px_#3b82f6]"></div>
              </div>
            </div>
            <h2 className="text-3xl font-black text-white uppercase tracking-[0.5em] mb-6 drop-shadow-[0_0_20px_rgba(59,130,246,0.6)]">Neural Synthesis</h2>
            <p className="text-slate-500 text-[11px] max-w-xs leading-relaxed font-bold uppercase tracking-[0.3em]">Architecting project changes in real-time</p>
          </div>
        )}

        {/* Loading Transition */}
        {!isGenerating && isLoadingOutput && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#0b0e14] z-50 animate-fade-in">
            <div className="flex flex-col items-center">
              <div className="w-80 h-1.5 bg-white/5 rounded-full overflow-hidden mb-8 ring-1 ring-white/5">
                 <div className="h-full bg-gradient-to-r from-blue-600 via-indigo-400 to-purple-600 animate-[loading_1s_ease-in-out_infinite] shadow-[0_0_15px_rgba(59,130,246,0.5)]"></div>
              </div>
              <span className="text-[10px] font-black uppercase tracking-[0.5em] text-blue-400/60 animate-pulse">Reconstituting Output...</span>
            </div>
          </div>
        )}
      </div>

      {/* Status Badges */}
      <div className="absolute bottom-8 right-8 pointer-events-none z-30 transition-transform duration-500">
        <div className="flex items-center gap-4 px-5 py-3 bg-[#0b0e14]/90 backdrop-blur-3xl border border-white/10 rounded-2xl text-[9px] font-black uppercase tracking-[0.3em] text-blue-400 shadow-2xl ring-1 ring-white/10">
          <div className={`w-2.5 h-2.5 rounded-full ${isGenerating ? 'bg-amber-500 animate-pulse shadow-[0_0_12px_#f59e0b]' : 'bg-green-500 animate-pulse shadow-[0_0_12px_#22c55e]'}`} />
          {isGenerating ? 'Synthesis Active' : `${activeLanguage.toUpperCase()} Runtime Live`}
        </div>
      </div>

      <style>{`
        @keyframes loading {
          0% { width: 0%; transform: translateX(-100%); opacity: 0.3; }
          50% { opacity: 1; }
          100% { width: 100%; transform: translateX(100%); opacity: 0.3; }
        }
      `}</style>
    </div>
  );
};

