const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_3_PRO);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [streamingFile, setStreamingFile] = useState<string | null>(null);

  // Debouncing logic for the preview
  const [debouncedBundledCode, setDebouncedBundledCode] = useState('');

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const filesRef = useRef<FileEntry[]>(INITIAL_FILES);

  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const rawBundledCode = useMemo(() => {
    if (activeFile.path.endsWith('.py')) return activeFile.content;

    const htmlFile = files.find(f => f.path === 'index.html');
    if (!htmlFile) {
      if (activeFile.path.endsWith('.js') || activeFile.path.endsWith('.ts') || activeFile.path.endsWith('.tsx')) {
        return `<html><head><script src="https://cdn.tailwindcss.com"></script></head><body><div id="root"></div><script type="module">${activeFile.content}</script></body></html>`;
      }
      return activeFile.content;
    }

    let content = htmlFile.content;
    const styles = files.filter(f => f.path.endsWith('.css')).map(f => `<style data-path="${f.path}">${f.content}</style>`).join('\n');

    const scripts = files.filter(f => f.path.endsWith('.js') || f.path.endsWith('.ts') || f.path.endsWith('.tsx')).map(f => {
      const isTS = f.path.endsWith('.ts') || f.path.endsWith('.tsx');
      const type = isTS ? 'text/babel' : 'module';
      const presets = isTS ? 'data-presets="react,typescript"' : '';
      return `<script type="${type}" ${presets} data-path="${f.path}">${f.content}</script>`;
    }).join('\n');

    content = content.replace(/<link[^>]+rel="stylesheet"[^>]*>/gi, (match) => match.includes('http') ? match : '');
    content = content.replace(/<script[^>]+src="[^"]+"[^>]*><\/script>/gi, (match) => match.includes('http') ? match : '');

    if (content.includes('</head>')) {
      content = content.replace('</head>', `${styles}\n</head>`);
    } else {
      content = styles + content;
    }

    if (content.includes('</body>')) {
      content = content.replace('</body>', `${scripts}\n</body>`);
    } else {
      content = content + scripts;
    }

    return content;
  }, [files, activeFile]);

  // Handle debouncing
  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedBundledCode(rawBundledCode);
    }, 400); // 400ms debounce for stability
    return () => clearTimeout(handler);
  }, [rawBundledCode]);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }
  }, [messages, isGenerating, currentStatus]);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    try {
      const zip = new window.JSZip();
      files.forEach(f => zip.file(f.path, f.content));
      const content = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = url;
      link.download = `vayu-neural-pkg-${Date.now()}.zip`;
      link.click();
      URL.revokeObjectURL(url);
    } catch (err) {
      console.error("Export failed:", err);
    }
  };

  const parseAndApplyFiles = useCallback((text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ 
            path, 
            content, 
            language: path.endsWith('.py') ? 'python' : (path.endsWith('.ts') || path.endsWith('.tsx') ? 'typescript' : (path.split('.').pop() || 'plaintext'))
          });
          updated = true;
        }
      }
      return updated ? newFiles : currentFiles;
    });

    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
    }
  }, [streamingFile]);

  const handleSendMessage = async (overridePrompt?: string) => {
    const currentPrompt = overridePrompt || prompt;
    if (!currentPrompt.trim() || isGenerating) return;

    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: currentPrompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    setStreamingFile(null);

    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      const workspaceContext = filesRef.current.map(f => `--- FILE: ${f.path} ---\n${f.content}`).join('\n\n');
      const systemInstruction = `You are Vayu IDE Neural Core. High-fidelity architectural synthesis.
Multi-language: HTML5, CSS3, ESNext, TypeScript 5+, React 18, and Python 3.11.

CORE RULES:
1. Always output code using: [FILE: path/to/file.ext]\n\`\`\`language\nCONTENT\n\`\`\`
2. For Web Apps: Use index.html as your entry point. Prefer Tailwind CSS (https://cdn.tailwindcss.com) and Lucide Icons (https://unpkg.com/lucide@latest) for aesthetics.
3. For Python: Use .py extension. It runs via Pyodide in-browser. No pip installs unless standard lib.
4. For Complex Logic: Prefer TypeScript (.ts/.tsx). It will be transpiled by Babel.
5. QUALITY: Produce sophisticated, polished UIs with buttery-smooth animations and glassmorphism.

CURRENT CONTEXT:
${workspaceContext}`;

      let fullContent = '';
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

      if (activeModel.includes('gemini')) {
        if (!chatInstanceRef.current) {
          chatInstanceRef.current = ai.chats.create({
            model: 'gemini-3-pro-preview',
            config: { systemInstruction }
          });
        }
        const response = await chatInstanceRef.current.sendMessageStream({ message: currentPrompt });
        for await (const chunk of response) {
          fullContent += chunk.text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      } else {
        const stream = await window.puter.ai.chat(`${systemInstruction}\n\nTask: ${currentPrompt}`, { model: activeModel, stream: true });
        for await (const chunk of stream) {
          fullContent += (typeof chunk === 'string' ? chunk : chunk.text || chunk.message?.content || "");
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      }

      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
      setCurrentStatus('idle');
      setStreamingFile(null);
    } catch (error: any) {
      console.error("AI Generation Error:", error);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: error.message || "Neural link failure.", isStreaming: false, error: "Sync interrupted." } : m));
      setStreamingFile(null);
    } finally {
      setIsGenerating(false);
    }
  };

  const getConversationalText = (content: string) => {
    return content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part) => {
      return part.split('```').filter((_, idx) => idx % 2 === 0).join('');
    }).join('').trim();
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30 font-inter">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-8 bg-[#05070a] border-r border-white/5 gap-10">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-2xl flex items-center justify-center font-black text-white text-xl shadow-2xl shadow-blue-500/20 ring-1 ring-white/10 group cursor-pointer transition-all duration-500 hover:scale-110 active:scale-95">
          V
          <div className="absolute inset-0 bg-blue-400 blur-2xl opacity-0 group-hover:opacity-10 transition-opacity"></div>
        </div>
        <div className="flex flex-col gap-8">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-2xl transition-all duration-300 transform ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10 scale-110 shadow-lg shadow-blue-500/5' : 'text-slate-600 hover:text-slate-300 hover:scale-110'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg>
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-2xl transition-all duration-300 transform ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10 scale-110 shadow-lg shadow-blue-500/5' : 'text-slate-600 hover:text-slate-300 hover:scale-110'}`}>
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg>
          </button>
          <div className="h-px w-6 bg-white/5 mx-auto"></div>
          <button onClick={() => window.open('https://spark-ai-search.pages.dev/', '_blank')} className="p-3 rounded-2xl transition-all duration-300 transform text-slate-600 hover:text-blue-400 hover:bg-blue-400/10 hover:scale-110">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" /></svg>
          </button>
          <button onClick={handleDownload} className="p-3 rounded-2xl transition-all duration-300 transform text-slate-600 hover:text-emerald-400 hover:bg-emerald-400/10 hover:scale-110">
            <svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg>
          </button>
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[380px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden transition-all duration-500">
        <div className="p-5 h-16 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[9px] text-slate-600 flex justify-between items-center bg-[#0d1117]/50 backdrop-blur-xl">
          <span className="flex items-center gap-2.5">
             <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse shadow-[0_0_12px_#3b82f6]' : 'bg-slate-700'}`}></div>
             {activeSidebarTab === 'chat' ? 'Neural Link' : 'Project Core'}
          </span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded-lg px-2.5 py-1 text-[8px] text-blue-400 outline-none font-bold tracking-[0.1em] transition-all hover:bg-white/10">
              <option value={AIModel.GEMINI_3_PRO}>Gemini 3 Pro</option>
              <option value={AIModel.GPT_4O}>GPT-4o</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5</option>
            </select>
          )}
        </div>

        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-48 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 select-none animate-spring-in">
                  <div className="w-20 h-20 bg-blue-500/5 rounded-[2rem] flex items-center justify-center border border-blue-500/10 mb-8 transform hover:rotate-12 transition-transform duration-700">
                    <svg className="w-10 h-10 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg>
                  </div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-400">Contextual Link Ready</h3>
                  <p className="text-[11px] mt-4 max-w-[200px] leading-relaxed text-slate-500">Awaiting architectural synthesis.</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-3 animate-spring-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[92%] p-5 rounded-[1.5rem] text-[13px] shadow-2xl border transition-all duration-500 ${
                    msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/40 rounded-br-none shadow-blue-500/10' : 'bg-white/5 backdrop-blur-3xl text-slate-200 border-white/10 rounded-bl-none'
                  }`}>
                    {msg.role === 'assistant' && msg.isStreaming && streamingFile && (
                      <div className="mb-4 px-3 py-2 bg-blue-500/10 border border-blue-500/20 rounded-xl flex items-center gap-3">
                        <div className="w-2 h-2 rounded-full bg-blue-500 animate-ping"></div>
                        <span className="text-[9px] font-black uppercase text-blue-400 tracking-widest">Synthesizing {streamingFile}</span>
                      </div>
                    )}
                    <div className="whitespace-pre-wrap font-normal leading-[1.6]">
                      {msg.role === 'user' ? msg.content : getConversationalText(msg.content)}
                    </div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>

            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/90 backdrop-blur-3xl border border-white/10 rounded-[1.8rem] p-4 shadow-[0_0_60px_rgba(0,0,0,0.6)] ring-1 ring-white/10 focus-within:ring-blue-500/40 focus-within:shadow-[0_0_40px_rgba(59,130,246,0.2)] transition-all duration-700 pointer-events-auto group neural-glow">
                <textarea 
                  value={prompt} 
                  onChange={(e) => setPrompt(e.target.value)} 
                  onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} 
                  placeholder="Architect workspace instructions..." 
                  className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[44px] max-h-[160px] placeholder:text-slate-600 font-medium px-2 py-1 scrollbar-hide" 
                />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-3 ml-2">
                    <div className={`w-1.5 h-1.5 rounded-full transition-all duration-1000 ${currentStatus === 'analyzing' ? 'bg-amber-400 shadow-[0_0_10px_#fbbf24]' : currentStatus === 'coding' ? 'bg-blue-400 animate-pulse shadow-[0_0_10px_#3b82f6]' : 'bg-slate-800'}`}></div>
                    <span className="text-[8px] text-slate-500 font-bold uppercase tracking-[0.2em] select-none">{currentStatus}</span>
                  </div>
                  <button onClick={() => handleSendMessage()} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2.5 rounded-2xl font-black text-[9px] uppercase tracking-[0.2em] transition-all transform active:scale-90 ${isGenerating || !prompt.trim() ? 'opacity-20 bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-xl shadow-blue-500/20 hover:scale-105'}`}>
                    {isGenerating ? 'Synthesizing' : 'Transmit'}
                  </button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-5 space-y-2 bg-[#0b0e14] custom-scrollbar">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-[12px] transition-all duration-300 border transform ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner translate-x-1' : 'hover:bg-white/5 text-slate-500 border-transparent hover:translate-x-1'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-bold uppercase tracking-widest">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>

      {/* Theatre Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14] relative">
        <div className="h-16 px-8 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 sticky top-0 backdrop-blur-3xl">
          <div className="flex items-center gap-6">
            <span className="text-[10px] font-black text-blue-400 uppercase tracking-[0.4em] drop-shadow-[0_0_8px_rgba(59,130,246,0.3)]">{activeFile.path}</span>
            {streamingFile === activeFile.path && (
              <div className="px-3 py-1 bg-amber-500/10 text-[8px] font-black text-amber-500 rounded-lg border border-amber-500/20 uppercase animate-pulse">Neural Write Active</div>
            )}
          </div>
          <div className="flex items-center gap-3 text-[8px] font-black uppercase text-green-500 bg-green-500/5 px-4 py-1.5 rounded-full border border-green-500/10 transition-all hover:bg-green-500/10">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_#22c55e]"></div> Neural Workspace Connected
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden relative">
          <div className="flex-1 border-r border-white/5 bg-[#0b0e14] relative overflow-hidden group editor-container">
            <Editor 
              height="100%" 
              path={activeFile.path} 
              language={activeFile.language} 
              theme="vs-dark" 
              value={activeFile.content} 
              options={{ 
                minimap: { enabled: false }, 
                fontSize: 14, 
                fontFamily: "'Fira Code', monospace", 
                padding: { top: 32 }, 
                lineNumbers: 'on', 
                automaticLayout: true, 
                cursorBlinking: 'smooth', 
                cursorSmoothCaretAnimation: 'on', 
                smoothScrolling: true, 
                renderLineHighlight: 'all', 
                scrollBeyondLastLine: false,
                fontLigatures: true,
                letterSpacing: 0.8,
                readOnly: isGenerating && streamingFile === activeFile.path,
                scrollbar: {
                  useShadows: false,
                  verticalHasArrows: false,
                  horizontalHasArrows: false,
                  vertical: 'visible',
                  horizontal: 'visible',
                  verticalScrollbarSize: 4,
                  horizontalScrollbarSize: 4
                }
              }} 
              onChange={(val) => {
                if (!isGenerating) {
                  setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
                }
              }}
            />
          </div>
          <div className="flex-1 bg-white overflow-hidden shadow-2xl relative transition-all duration-500 group/preview">
            <Preview 
              code={debouncedBundledCode} 
              isGenerating={isGenerating} 
              activeLanguage={activeFile.path.endsWith('.py') ? 'python' : 'web'}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

import React, { useEffect, useRef, useState, useCallback } from 'react';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
  activeLanguage: 'web' | 'python';
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating, activeLanguage }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [isLoadingOutput, setIsLoadingOutput] = useState(false);
  const [isFullscreen, setIsFullscreen] = useState(false);
  const [pythonOutput, setPythonOutput] = useState<string[]>([]);
  const [pyodide, setPyodide] = useState<any>(null);
  const [runtimeError, setRuntimeError] = useState<string | null>(null);

  const prevIsGenerating = useRef(isGenerating);

  // Initialize Pyodide for Python support
  useEffect(() => {
    if (activeLanguage === 'python' && !pyodide && (window as any).loadPyodide) {
      (window as any).loadPyodide().then((res: any) => {
        setPyodide(res);
      });
    }
  }, [activeLanguage, pyodide]);

  // Handle generation finish animation
  useEffect(() => {
    if (prevIsGenerating.current && !isGenerating) {
      setIsLoadingOutput(true);
      const timer = setTimeout(() => {
        setIsLoadingOutput(false);
      }, 1200);
      return () => clearTimeout(timer);
    }
    prevIsGenerating.current = isGenerating;
  }, [isGenerating]);

  // Execute Code based on language
  useEffect(() => {
    // If the synthesis is ongoing or we are in a forced loading state, hold updates
    if (isGenerating || isLoadingOutput || !code) return;

    setRuntimeError(null);

    if (activeLanguage === 'web') {
      if (iframeRef.current) {
        try {
          // Set srcdoc directly to render the bundled HTML/JS/TS
          iframeRef.current.srcdoc = code;
        } catch (err: any) {
          setRuntimeError(err.message);
        }
      }
    } else if (activeLanguage === 'python' && pyodide) {
      const runPython = async () => {
        setPythonOutput(['Neural Link Established. Initializing Python Runtime...']);
        try {
          pyodide.setStdout({
            batched: (text: string) => {
              setPythonOutput(prev => [...prev, text]);
            }
          });
          pyodide.setStderr({
            batched: (text: string) => {
              setPythonOutput(prev => [...prev, `[SYSERR] ${text}`]);
            }
          });
          await pyodide.runPythonAsync(code);
        } catch (err: any) {
          setPythonOutput(prev => [...prev, `[RUNTIME ERROR] ${err.message}`]);
          setRuntimeError(err.message);
        }
      };
      runPython();
    }
  }, [code, isGenerating, isLoadingOutput, activeLanguage, pyodide]);

  const handleReload = useCallback(() => {
    setIsLoadingOutput(true);
    setTimeout(() => {
      setIsLoadingOutput(false);
    }, 800);
  }, []);

  const toggleFullscreen = useCallback(() => {
    if (!containerRef.current) return;
    if (!document.fullscreenElement) {
      containerRef.current.requestFullscreen().catch((err) => {
        console.error(`Error enabling full-screen: ${err.message}`);
      });
      setIsFullscreen(true);
    } else {
      document.exitFullscreen();
      setIsFullscreen(false);
    }
  }, []);

  useEffect(() => {
    const handler = () => setIsFullscreen(!!document.fullscreenElement);
    document.addEventListener('fullscreenchange', handler);
    return () => document.removeEventListener('fullscreenchange', handler);
  }, []);

  const handlePopOut = useCallback(() => {
    if (activeLanguage === 'web') {
      const newWindow = window.open('', '_blank');
      if (newWindow) {
        newWindow.document.write(code);
        newWindow.document.close();
      }
    }
  }, [code, activeLanguage]);

  return (
    <div ref={containerRef} className="w-full h-full bg-white relative overflow-hidden transition-all flex flex-col font-inter">
      {/* Precision Toolbar */}
      <div className="absolute top-6 right-6 z-50 flex items-center gap-2 p-2 bg-[#0b0e14]/90 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-2xl opacity-0 group-hover/preview:opacity-100 transition-all duration-500 transform translate-y-2 group-hover/preview:translate-y-0">
        <button 
          onClick={handleReload}
          className="p-2.5 rounded-xl text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
          title="Refresh Neural Instance"
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15" />
          </svg>
        </button>
        {activeLanguage === 'web' && (
          <button 
            onClick={handlePopOut}
            className="p-2.5 rounded-xl text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
            title="External Viewport"
          >
            <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M10 6H6a2 2 0 00-2 2v10a2 2 0 002 2h10a2 2 0 002-2v-4M14 4h6m0 0v6m0-6L10 14" />
            </svg>
          </button>
        )}
        <div className="w-px h-5 bg-white/10 mx-1" />
        <button 
          onClick={toggleFullscreen}
          className="p-2.5 rounded-xl text-slate-400 hover:text-white hover:bg-white/10 transition-all active:scale-90"
          title={isFullscreen ? "Exit Fullscreen" : "Fullscreen Viewport"}
        >
          <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 8V4m0 0h4M4 4l5 5m11-1V4m0 0h-4m4 0l-5 5M4 16v4m0 0h4m-4 0l5-5m11 5l-5-5m5 5v-4m0 4h-4" />
          </svg>
        </button>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 relative group">
        {activeLanguage === 'web' ? (
          <iframe
            ref={iframeRef}
            title="Vayu Neural Output"
            className={`w-full h-full border-none transition-all duration-1000 transform ${isGenerating || isLoadingOutput ? 'opacity-0 scale-[0.99] blur-2xl grayscale' : 'opacity-100 scale-100 blur-0 grayscale-0'}`}
            sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin"
          />
        ) : (
          <div className={`w-full h-full bg-[#05070a] p-10 font-mono text-sm overflow-auto custom-scrollbar transition-all duration-1000 ${isGenerating || isLoadingOutput ? 'opacity-0 scale-[0.99] blur-2xl' : 'opacity-100 scale-100 blur-0'}`}>
             <div className="flex items-center gap-4 mb-8 text-blue-500/60 select-none">
                <div className="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></div>
                <span className="text-[10px] font-black uppercase tracking-[0.3em]">Python Environment v3.11</span>
             </div>
             {pythonOutput.map((line, i) => (
               <div key={i} className={`mb-1.5 transition-all animate-fade-in ${line.startsWith('[SYSERR]') || line.startsWith('[RUNTIME ERROR]') ? 'text-red-400/90' : 'text-slate-400'}`}>
                 {line}
               </div>
             ))}
             {!pyodide && <div className="text-blue-500 animate-pulse mt-6 font-bold tracking-widest">CONNECTING TO PYTHON CORE...</div>}
             <div className="h-24" />
          </div>
        )}

        {/* Synthesis Progress Overlay */}
        {isGenerating && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-slate-900/95 backdrop-blur-3xl z-40 animate-fade-in text-center p-12">
            <div className="w-32 h-32 mb-14 relative group">
              <div className="absolute inset-0 border-[8px] border-blue-500/5 rounded-full transition-all group-hover:border-blue-500/10"></div>
              <div className="absolute inset-0 border-[8px] border-t-blue-500 rounded-full animate-spin shadow-[0_0_40px_rgba(59,130,246,0.6)]"></div>
              <div className="absolute inset-8 bg-blue-500/5 rounded-full flex items-center justify-center border border-white/5">
                <div className="w-8 h-8 bg-blue-500 rounded-full animate-pulse shadow-[0_0_35px_#3b82f6]"></div>
              </div>
            </div>
            <h2 className="text-4xl font-black text-white uppercase tracking-[0.4em] mb-6 drop-shadow-[0_0_20px_rgba(59,130,246,0.5)]">Synthesis</h2>
            <p className="text-slate-500 text-[10px] max-w-xs leading-relaxed font-bold uppercase tracking-[0.3em] opacity-80">Real-time architectural reconstitution in progress</p>
          </div>
        )}

        {/* Post-Synthesis Loading Transition */}
        {!isGenerating && isLoadingOutput && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#0b0e14] z-50 animate-fade-in">
            <div className="flex flex-col items-center">
              <div className="w-96 h-1.5 bg-white/5 rounded-full overflow-hidden mb-10 ring-1 ring-white/5 shadow-2xl">
                 <div className="h-full bg-gradient-to-r from-blue-600 via-indigo-500 to-fuchsia-600 animate-[loading_1.5s_ease-in-out_infinite] shadow-[0_0_20px_rgba(59,130,246,0.5)]"></div>
              </div>
              <span className="text-[10px] font-black uppercase tracking-[0.6em] text-blue-400/70 animate-pulse">Syncing Neural Instance...</span>
            </div>
          </div>
        )}

        {/* Error State View */}
        {runtimeError && !isGenerating && !isLoadingOutput && (
          <div className="absolute top-10 left-10 right-10 p-6 bg-red-500/10 border border-red-500/20 backdrop-blur-2xl rounded-3xl z-40 animate-spring-in">
             <div className="flex items-center gap-4 mb-3 text-red-500">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
                <span className="text-[11px] font-black uppercase tracking-[0.2em]">Neural Runtime Error</span>
             </div>
             <p className="text-[13px] font-mono text-slate-300 bg-black/30 p-4 rounded-xl overflow-auto custom-scrollbar max-h-48 border border-white/5">{runtimeError}</p>
          </div>
        )}
      </div>

      {/* Bottom Status Panel */}
      <div className="absolute bottom-10 right-10 pointer-events-none z-30 transition-all duration-700">
        <div className="flex items-center gap-4 px-6 py-3.5 bg-[#0b0e14]/95 backdrop-blur-3xl border border-white/10 rounded-[1.8rem] text-[9px] font-black uppercase tracking-[0.3em] text-blue-400 shadow-[0_30px_60px_-15px_rgba(0,0,0,0.8)] ring-1 ring-white/10 hover:ring-blue-500/20 transition-all">
          <div className={`w-2.5 h-2.5 rounded-full transition-all duration-700 ${isGenerating ? 'bg-amber-500 animate-pulse shadow-[0_0_15px_#f59e0b]' : 'bg-green-500 animate-pulse shadow-[0_0_15px_#22c55e]'}`} />
          {isGenerating ? 'Neural Stream: active' : `${activeLanguage.toUpperCase()} Runtime: optimal`}
        </div>
      </div>

      <style>{`
        @keyframes loading {
          0% { width: 0%; transform: translateX(-100%); opacity: 0.3; }
          50% { opacity: 1; }
          100% { width: 100%; transform: translateX(100%); opacity: 0.3; }
        }
      `}</style>
    </div>
  );
};

import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry } from './types';
import { GoogleGenAI } from "@google/genai";

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body {
      background: #0b0e14;
      color: #f8fafc;
      font-family: 'Inter', sans-serif;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .hero {
      text-align: center;
      padding: 4rem;
      border-radius: 4rem;
      background: rgba(255, 255, 255, 0.01);
      backdrop-filter: blur(60px);
      border: 1px solid rgba(255, 255, 255, 0.05);
      box-shadow: 0 50px 100px -20px rgba(0, 0, 0, 0.9);
      transition: all 0.8s cubic-bezier(0.16, 1, 0.3, 1);
    }
    .hero:hover {
      background: rgba(255, 255, 255, 0.03);
      border-color: rgba(59, 130, 246, 0.2);
    }
    .logo {
      font-size: 8rem;
      font-weight: 950;
      background: linear-gradient(to right, #60a5fa, #a78bfa, #f472b6);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      letter-spacing: -0.08em;
      filter: drop-shadow(0 0 40px rgba(96, 165, 250, 0.3));
    }
  </style>
</head>
<body>
  <div class="hero">
    <h1 class="logo">VAYU</h1>
    <p class="mt-10 text-slate-500 font-black tracking-[0.5em] uppercase text-[9px] opacity-60">Neural Workspace Live</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<string>(AIModel.GEMINI_3_PRO);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [streamingFile, setStreamingFile] = useState<string | null>(null);

  const [debouncedBundledCode, setDebouncedBundledCode] = useState('');

  const chatContainerRef = useRef<HTMLDivElement>(null);
  const chatEndRef = useRef<HTMLDivElement>(null);
  const chatInstanceRef = useRef<any>(null); 
  const filesRef = useRef<FileEntry[]>(INITIAL_FILES);

  useEffect(() => {
    filesRef.current = files;
  }, [files]);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const rawBundledCode = useMemo(() => {
    if (activeFile.path.endsWith('.py')) return activeFile.content;

    const htmlFile = files.find(f => f.path === 'index.html');
    let content = htmlFile ? htmlFile.content : `<!DOCTYPE html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body><div id="root"></div></body></html>`;

    const styles = files.filter(f => f.path.endsWith('.css')).map(f => `<style data-path="${f.path}">${f.content}</style>`).join('\n');
    const scripts = files.filter(f => f.path.endsWith('.js') || f.path.endsWith('.ts') || f.path.endsWith('.tsx')).map(f => {
      const isReactOrTS = f.path.endsWith('.ts') || f.path.endsWith('.tsx');
      return `<script type="${isReactOrTS ? 'text/babel' : 'module'}" ${isReactOrTS ? 'data-presets="react,typescript"' : ''} data-path="${f.path}">${f.content}</script>`;
    }).join('\n');

    content = content.replace(/<link[^>]+rel="stylesheet"[^>]*>/gi, (m) => m.includes('http') ? m : '');
    content = content.replace(/<script[^>]+src="[^"]+"[^>]*><\/script>/gi, (m) => m.includes('http') ? m : '');

    if (content.includes('</head>')) content = content.replace('</head>', `${styles}\n</head>`);
    else content = styles + content;

    if (content.includes('</body>')) content = content.replace('</body>', `${scripts}\n</body>`);
    else content = content + scripts;

    return content;
  }, [files, activeFile]);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedBundledCode(rawBundledCode);
    }, 400);
    return () => clearTimeout(handler);
  }, [rawBundledCode]);

  useEffect(() => {
    if (chatEndRef.current) {
      chatEndRef.current.scrollIntoView({ behavior: 'smooth', block: 'end' });
    }
  }, [messages, isGenerating, currentStatus]);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    try {
      const zip = new window.JSZip();
      files.forEach(f => zip.file(f.path, f.content));
      const content = await zip.generateAsync({ type: 'blob' });
      const url = URL.createObjectURL(content);
      const link = document.createElement('a');
      link.href = url;
      link.download = `vayu-neural-pkg-${Date.now()}.zip`;
      link.click();
      URL.revokeObjectURL(url);
    } catch (err) { console.error(err); }
  };

  const parseAndApplyFiles = useCallback((text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let newFiles = [...currentFiles];
      let updated = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const existingIdx = newFiles.findIndex(f => f.path === path);
        if (existingIdx > -1) {
          if (newFiles[existingIdx].content !== content) {
            newFiles[existingIdx] = { ...newFiles[existingIdx], content };
            updated = true;
          }
        } else {
          newFiles.push({ 
            path, content, 
            language: path.endsWith('.py') ? 'python' : (path.endsWith('.ts') || path.endsWith('.tsx') ? 'typescript' : (path.split('.').pop() || 'plaintext'))
          });
          updated = true;
        }
      }
      return updated ? newFiles : currentFiles;
    });
    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
    }
  }, [streamingFile]);

  const handleSendMessage = async () => {
    if (!prompt.trim() || isGenerating) return;
    const userMessage: ChatMessage = { id: Date.now().toString(), role: 'user', content: prompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMessage]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    const assistantId = (Date.now() + 1).toString();
    const assistantMessage: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true, status: 'analyzing' };
    setMessages(prev => [...prev, assistantMessage]);

    try {
      const systemInstruction = `Vayu IDE Neural Core. High-fidelity architectural synthesis.
Multi-language support (Web/React/Python).
Always use [FILE: path]\n\`\`\`\nCONTENT\n\`\`\` format for any code changes.
Output full files to ensure consistency. Use modern libraries (Tailwind, Framer Motion, Three.js).`;
      let fullContent = '';
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      if (activeModel.includes('gemini')) {
        if (!chatInstanceRef.current) chatInstanceRef.current = ai.chats.create({ model: 'gemini-3-pro-preview', config: { systemInstruction } });
        const response = await chatInstanceRef.current.sendMessageStream({ message: userMessage.content });
        for await (const chunk of response) {
          fullContent += chunk.text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      } else {
        const stream = await window.puter.ai.chat(`${systemInstruction}\nTask: ${userMessage.content}`, { model: activeModel, stream: true });
        for await (const chunk of stream) {
          fullContent += (typeof chunk === 'string' ? chunk : chunk.text || chunk.message?.content || "");
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, status: 'coding' } : m));
          parseAndApplyFiles(fullContent);
        }
      }
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent, isStreaming: false, status: 'idle' } : m));
    } catch (error: any) {
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: "Uplink failure.", isStreaming: false, error: "Sync error" } : m));
    } finally {
      setIsGenerating(false);
      setCurrentStatus('idle');
      setStreamingFile(null);
    }
  };

  const getConversationalText = (content: string) => {
    return content.split(/\[FILE:\s*[a-zA-Z0-9._\-/]+\]/).map((part) => {
      return part.split('```').filter((_, idx) => idx % 2 === 0).join('');
    }).join('').trim();
  };

  return (
    <div className="flex h-screen w-full bg-[#0b0e14] text-slate-200 overflow-hidden text-sm selection:bg-blue-500/30 font-inter">
      <div className="w-16 flex flex-col items-center py-8 bg-[#05070a] border-r border-white/5 gap-10">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-2xl flex items-center justify-center font-black text-white text-xl shadow-2xl ring-1 ring-white/10 group cursor-pointer transition-all duration-500 hover:scale-110 active:scale-95">V</div>
        <div className="flex flex-col gap-8">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-2xl transition-all ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-600 hover:text-slate-300'}`}><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M8 10h.01M12 10h.01M16 10h.01M9 16H5a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v8a2 2 0 01-2 2h-5l-5 5v-5z" /></svg></button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-2xl transition-all ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-400/10' : 'text-slate-600 hover:text-slate-300'}`}><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M3 7v10a2 2 0 002 2h14a2 2 0 002-2V9a2 2 0 00-2-2h-6l-2-2H5a2 2 0 00-2 2z" /></svg></button>
          <button onClick={handleDownload} className="p-3 rounded-2xl transition-all text-slate-600 hover:text-emerald-400 hover:bg-emerald-400/10"><svg className="w-6 h-6" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4" /></svg></button>
        </div>
      </div>
      <div className="w-[380px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden transition-all duration-500">
        <div className="p-5 h-16 border-b border-white/5 font-black uppercase tracking-[0.2em] text-[9px] text-slate-600 flex justify-between items-center bg-[#0d1117]/50 backdrop-blur-xl">
          <span className="flex items-center gap-2.5"><div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'bg-blue-500 animate-pulse' : 'bg-slate-700'}`}></div> {activeSidebarTab === 'chat' ? 'Neural Link' : 'Project Core'}</span>
          {activeSidebarTab === 'chat' && (
            <select value={activeModel} onChange={(e) => { setActiveModel(e.target.value); chatInstanceRef.current = null; }} className="bg-white/5 border border-white/10 rounded-lg px-2.5 py-1 text-[8px] text-blue-400 outline-none font-bold tracking-[0.1em] transition-all hover:bg-white/10">
              <option value={AIModel.GEMINI_3_PRO}>Gemini 3 Pro</option>
              <option value={AIModel.GPT_4O}>GPT-4o</option>
              <option value={AIModel.CLAUDE_3_5}>Claude 3.5</option>
            </select>
          )}
        </div>
        {activeSidebarTab === 'chat' ? (
          <div className="flex-1 flex flex-col overflow-hidden relative">
            <div ref={chatContainerRef} className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-48 scroll-smooth">
              {messages.length === 0 && (
                <div className="h-full flex flex-col items-center justify-center text-center opacity-30 select-none animate-spring-in">
                  <div className="w-20 h-20 bg-blue-500/5 rounded-[2rem] flex items-center justify-center border border-blue-500/10 mb-8"><svg className="w-10 h-10 text-blue-500" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M13 10V3L4 14h7v7l9-11h-7z" strokeWidth="1.5"/></svg></div>
                  <h3 className="text-[10px] font-black uppercase tracking-[0.4em] text-blue-400">Contextual Link Ready</h3>
                  <p className="text-[11px] mt-4 max-w-[200px] leading-relaxed text-slate-500">Awaiting instructions.</p>
                </div>
              )}
              {messages.map((msg) => (
                <div key={msg.id} className={`flex flex-col gap-3 animate-spring-in group ${msg.role === 'user' ? 'items-end' : 'items-start'}`}>
                  <div className={`max-w-[92%] p-5 rounded-[1.5rem] text-[13px] shadow-2xl border transition-all duration-500 ${msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/40 rounded-br-none' : 'bg-white/5 backdrop-blur-3xl text-slate-200 border-white/10 rounded-bl-none'}`}>
                    {msg.role === 'assistant' && msg.isStreaming && streamingFile && (
                      <div className="mb-4 px-3 py-2 bg-blue-500/10 border border-blue-500/20 rounded-xl flex items-center gap-3"><div className="w-2 h-2 rounded-full bg-blue-500 animate-ping"></div><span className="text-[9px] font-black uppercase text-blue-400 tracking-widest">Synthesizing {streamingFile}</span></div>
                    )}
                    <div className="whitespace-pre-wrap font-normal leading-[1.6]">{msg.role === 'user' ? msg.content : getConversationalText(msg.content)}</div>
                  </div>
                </div>
              ))}
              <div ref={chatEndRef} />
            </div>
            <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14]/95 to-transparent pointer-events-none z-30">
              <div className="bg-[#1a1f29]/90 backdrop-blur-3xl border border-white/10 rounded-[1.8rem] p-4 shadow-2xl ring-1 ring-white/10 pointer-events-auto group neural-glow">
                <textarea value={prompt} onChange={(e) => setPrompt(e.target.value)} onKeyDown={(e) => { if (e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} placeholder="Architect instructions..." className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[44px] max-h-[160px] placeholder:text-slate-600 font-medium px-2 py-1 scrollbar-hide" />
                <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                  <div className="flex items-center gap-3 ml-2"><div className={`w-1.5 h-1.5 rounded-full ${currentStatus === 'coding' ? 'bg-blue-400 animate-pulse' : 'bg-slate-800'}`}></div><span className="text-[8px] text-slate-500 font-bold uppercase tracking-[0.2em]">{currentStatus}</span></div>
                  <button onClick={handleSendMessage} disabled={isGenerating || !prompt.trim()} className={`px-6 py-2.5 rounded-2xl font-black text-[9px] uppercase tracking-[0.2em] transition-all transform active:scale-90 ${isGenerating || !prompt.trim() ? 'opacity-20 bg-slate-800' : 'bg-blue-600 text-white hover:bg-blue-500 shadow-xl shadow-blue-500/20'}`}>{isGenerating ? 'Synthesizing' : 'Transmit'}</button>
                </div>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex-1 overflow-y-auto p-5 space-y-2 bg-[#0b0e14] custom-scrollbar">
            {files.map(file => (
              <button key={file.path} onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-[12px] transition-all border transform ${activeFilePath === file.path ? 'bg-blue-600/10 text-blue-400 border-blue-400/20 shadow-inner translate-x-1' : 'hover:bg-white/5 text-slate-500 border-transparent'}`}>
                <svg className={`w-4 h-4 ${activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'}`} fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M7 21h10a2 2 0 002-2V9.414a1 1 0 00-.293-.707l-5.414-5.414A1 1 0 0012.586 3H7a2 2 0 00-2 2v14a2 2 0 002 2z" strokeWidth="2" /></svg>
                <span className="flex-1 text-left truncate font-bold uppercase tracking-widest">{file.path}</span>
              </button>
            ))}
          </div>
        )}
      </div>
      <div className="flex-1 flex flex-col min-w-0 bg-[#0b0e14] relative">
        <div className="h-16 px-8 flex items-center justify-between bg-[#0b0e14] border-b border-white/5 z-20 backdrop-blur-3xl">
          <span className="text-[10px] font-black text-blue-400 uppercase tracking-[0.4em]">{activeFile.path}</span>
          <div className="flex items-center gap-3 text-[8px] font-black uppercase text-green-500 bg-green-500/5 px-4 py-1.5 rounded-full border border-green-500/10">
             <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse shadow-[0_0_10px_#22c55e]"></div> Workspace Optimal
          </div>
