      justify-content: center;
      height: 100vh;
      margin: 0;
      overflow: hidden;
    }
    .hero {
      text-align: center;
      padding: 5rem;
      border-radius: 5rem;
      background: rgba(255, 255, 255, 0.01);
      backdrop-filter: blur(80px);
