    @keyframes synthesis { from { opacity: 0; filter: blur(20px); transform: scale(0.95); } to { opacity: 1; filter: blur(0); transform: scale(1); } }
  </style>
</head>
<body>
  <div class="neural-container">
    <div class="status-pill">
      <div class="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></div> 
      Vayu Neural OS Online
    </div>
    <h1>VAYU CODE</h1>
    <p style="color: #64748b; font-size: 1.125rem; margin-top: 1rem; font-weight: 400; max-width: 400px; margin-left: auto; margin-right: auto;">Command the neural engine to synthesize your design architecture.</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [prompt, setPrompt] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GPT_4O);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [terminalLogs, setTerminalLogs] = useState<string[]>(['[SYSTEM] VAYU_SYNTH_CORE Initiated.', '[SYSTEM] Ready for architecture input.']);
  const [streamingFile, setStreamingFile] = useState<string | null>(null);
  const [debouncedBundledCode, setDebouncedBundledCode] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const rawBundledCode = useMemo(() => {
    if (activeFile.path.endsWith('.py')) return activeFile.content;
    const htmlFile = files.find(f => f.path === 'index.html');
    let content = htmlFile ? htmlFile.content : `<!DOCTYPE html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body><div id="root"></div></body></html>`;

    const styles = files.filter(f => f.path.endsWith('.css')).map(f => `<style data-path="${f.path}">${f.content}</style>`).join('\n');
    const scripts = files.filter(f => f.path.endsWith('.js') || f.path.endsWith('.ts') || f.path.endsWith('.tsx')).map(f => {
      const isReactOrTS = f.path.endsWith('.ts') || f.path.endsWith('.tsx');
      return `<script type="${isReactOrTS ? 'text/babel' : 'module'}" ${isReactOrTS ? 'data-presets="react,typescript"' : ''} data-path="${f.path}">${f.content}</script>`;
    }).join('\n');

    if (content.includes('</head>')) content = content.replace('</head>', `${styles}\n</head>`);
    if (content.includes('</body>')) content = content.replace('</body>', `${scripts}\n</body>`);
    return content;
  }, [files, activeFile]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedBundledCode(rawBundledCode), 400); 
    return () => clearTimeout(handler);
  }, [rawBundledCode]);

  useEffect(() => {
    if (chatEndRef.current) chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  // Handle outside clicks for dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsModelDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const addLog = (msg: string) => setTerminalLogs(prev => [...prev.slice(-10), `[${new Date().toLocaleTimeString()}] ${msg}`]);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const a = document.createElement('a');
    a.href = url;
    a.download = `vayu-project-${Date.now()}.zip`;
    a.click();
    addLog('Project manifest exported successfully.');
  };

  const createNewFile = () => {
    const name = prompt('File Name (e.g., style.css):');
    if (!name) return;
    setFiles(prev => [...prev, { path: name, content: '', language: name.split('.').pop() || 'plaintext' }]);
    setActiveFilePath(name);
    addLog(`Buffer created: ${name}`);
  };

  const deleteFile = (path: string) => {
    if (files.length <= 1) return;
    if (confirm(`Delete ${path}?`)) {
      setFiles(prev => prev.filter(f => f.path !== path));
      if (activeFilePath === path) setActiveFilePath(files[0].path);
      addLog(`Purged: ${path}`);
    }
  };

  const parseAndApplyFiles = useCallback((text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let nextFiles = [...currentFiles];
      let hasChanges = false;

      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const idx = nextFiles.findIndex(f => f.path === path);
        if (idx !== -1) {
          if (nextFiles[idx].content !== content) {
            nextFiles[idx] = { ...nextFiles[idx], content };
            hasChanges = true;
          }
        } else {
          nextFiles.push({
            path, content,
            language: path.endsWith('.py') ? 'python' : 
                      (path.endsWith('.tsx') || path.endsWith('.ts')) ? 'typescript' : 
                      path.split('.').pop() || 'plaintext'
          });
          hasChanges = true;
        }
      }
      return hasChanges ? nextFiles : currentFiles;
    });

    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
      addLog(`Synthesizing stream: ${lastPath}`);
    }
  }, [streamingFile]);

  const handleSendMessage = async () => {
    if (!prompt.trim() || isGenerating) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: prompt, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setPrompt('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    addLog('Initiating architectural analysis...');

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true };
    setMessages(prev => [...prev, assistantMsg]);

    try {
      const systemInstruction = `You are VAYU ARCHITECT, an elite neural IDE engine.

      PHASE 1: CONTEXTUAL BLUEPRINTING
      Synthesize the optimal design system for the request.
      - Interactive Dashboards: React + Tailwind + Recharts.
      - Creative Visuals: Three.js + React Three Fiber.
      - Data Processing: Python (NumPy/Pandas logic).

      PHASE 2: SYNTHESIS RULES
      - Use ESM imports.
      - Implement glassmorphism using Tailwind: "backdrop-blur-md bg-white/10 border border-white/20".
      - Output ONLY valid code blocks using the Vayu file tag system.

      [FILE: path/to/file.ext]
      \`\`\`language
      CONTENT
      \`\`\`

      Workspace Context: ${files.length} active buffers.
      User Intent: ${userMsg.content}`;

      let fullContent = '';
      const response = await window.puter.ai.chat(systemInstruction, { 
        model: activeModel, 
        stream: true 
      });

      for await (const chunk of response) {
        const text = typeof chunk === 'string' ? chunk : (chunk.text || chunk.message?.content || "");
        if (text) {
          fullContent += text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { 
            ...m, 
            content: fullContent, 
            status: fullContent.includes('[FILE:') ? 'coding' : 'analyzing' 
          } : m));
          parseAndApplyFiles(fullContent);
          if (fullContent.includes('[FILE:')) setCurrentStatus('coding');
        }
      }

      addLog('Synthesis complete. Runtime ready.');
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
    } catch (err: any) {
      addLog(`CRITICAL_ERR: ${err.message}`);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: `Synthesis Refused: ${err.message}`, isStreaming: false, error: err.message } : m));
    } finally {
      setIsGenerating(false);
      setCurrentStatus('idle');
      setStreamingFile(null);
    }
  };

  const selectedModelData = MODEL_LIST.find(m => m.id === activeModel)!;

  return (
    <div className="flex h-screen w-full bg-[#05070a] text-slate-200 overflow-hidden font-inter selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#080b10] border-r border-white/5 gap-8 z-50">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white shadow-lg shadow-blue-500/30 cursor-default">V</div>
        <div className="flex flex-col gap-6">
          <button 
            onClick={() => setActiveSidebarTab('chat')} 
            className={`p-2.5 rounded-xl transition-all relative group ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-500/10' : 'text-slate-600 hover:text-slate-400 hover:bg-white/5'}`}
          >
            <MessageSquare size={20} />
            {activeSidebarTab === 'chat' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 bg-blue-500 rounded-l-full" />}
