import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Maximize2, Loader2, Zap, RefreshCw, Activity, ShieldCheck } from 'lucide-react';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
  activeLanguage: 'web' | 'python';
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating, activeLanguage }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pythonOutput, setPythonOutput] = useState<string[]>([]);
  const [pyodide, setPyodide] = useState<any>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [runtimeStatus, setRuntimeStatus] = useState<'idle' | 'running' | 'error'>('idle');

  useEffect(() => {
    if (activeLanguage === 'python' && !pyodide && (window as any).loadPyodide) {
      (window as any).loadPyodide().then((res: any) => setPyodide(res));
    }
  }, [activeLanguage, pyodide]);

  const runCode = useCallback(async () => {
    if (!code) return;
    setRuntimeStatus('running');

    if (activeLanguage === 'web') {
      if (iframeRef.current) {
        iframeRef.current.srcdoc = '';
        setTimeout(() => {
          if (iframeRef.current) {
            iframeRef.current.srcdoc = code;
            setRuntimeStatus('idle');
          }
        }, 50);
      }
    } else if (activeLanguage === 'python' && pyodide) {
      setPythonOutput(['>>> Initializing Virtual Trace...']);
      try {
        pyodide.setStdout({ batched: (text: string) => setPythonOutput(prev => [...prev, text]) });
        pyodide.setStderr({ batched: (text: string) => {
          setPythonOutput(prev => [...prev, `[ERR] ${text}`]);
          setRuntimeStatus('error');
        }});
        await pyodide.runPythonAsync(code);
        setRuntimeStatus('idle');
      } catch (err: any) {
        setPythonOutput(prev => [...prev, `[FATAL] ${err.message}`]);
        setRuntimeStatus('error');
      }
    }
  }, [code, activeLanguage, pyodide]);

  useEffect(() => {
    if (isGenerating) return;
    runCode();
  }, [code, isGenerating, refreshKey, runCode]);

  const handleRefresh = () => {
    setRefreshKey(prev => prev + 1);
  };

  const toggleFullscreen = () => {
    if (!containerRef.current) return;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      containerRef.current.requestFullscreen();
    }
  };

  return (
    <div ref={containerRef} className="w-full h-full bg-[#05070a] relative flex flex-col group">
      {/* Precision Controls Overlay */}
      <div className="absolute top-6 right-6 z-40 flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-2 group-hover:translate-y-0">
        <div className="flex items-center gap-2 px-3 py-1.5 bg-black/40 backdrop-blur-xl border border-white/10 rounded-xl">
           <div className={`w-1.5 h-1.5 rounded-full ${runtimeStatus === 'running' ? 'bg-blue-500 animate-pulse' : runtimeStatus === 'error' ? 'bg-rose-500' : 'bg-emerald-500'}`} />
           <span className="text-[9px] font-black uppercase text-slate-400 tracking-widest">{activeLanguage}_RUNTIME</span>
        </div>
        <button 
          className="p-2.5 bg-white/5 backdrop-blur-xl text-white rounded-xl border border-white/10 shadow-2xl hover:bg-white/10 hover:border-white/20 transition-all active:scale-95" 
          title="Refresh" 
          onClick={handleRefresh}
        >
          <RefreshCw size={14} className={runtimeStatus === 'running' ? 'animate-spin' : ''} />
        </button>
        <button 
          className="p-2.5 bg-white/5 backdrop-blur-xl text-white rounded-xl border border-white/10 shadow-2xl hover:bg-white/10 hover:border-white/20 transition-all active:scale-95" 
          title="Fullscreen" 
          onClick={toggleFullscreen}
        >
          <Maximize2 size={14} />
        </button>
      </div>

      <div className="flex-1 relative overflow-hidden">
        {activeLanguage === 'web' ? (
          <iframe 
            ref={iframeRef} 
            title="Preview" 
            className={`w-full h-full border-none bg-white transition-all duration-1000 ${isGenerating ? 'opacity-10 grayscale blur-sm pointer-events-none' : 'opacity-100'}`} 
            sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin" 
          />
        ) : (
          <div className="w-full h-full bg-[#05070a] p-12 font-mono text-[13px] overflow-auto text-slate-300 custom-scrollbar">
             <div className="flex items-center justify-between mb-8 pb-4 border-b border-white/5">
                <div className="flex items-center gap-3">
                  <Activity size={16} className="text-emerald-500" />
                  <span className="text-[11px] font-black uppercase tracking-[0.2em] text-slate-400">Virtual Machine Output</span>
                </div>
                <div className="flex items-center gap-2 text-[10px] text-slate-600 font-bold">
                  <ShieldCheck size={14} /> SECURE_TRACE
                </div>
             </div>
             {pythonOutput.map((line, i) => (
               <div key={i} className={`mb-3 font-medium leading-relaxed font-mono ${line.includes('[ERR]') || line.includes('[FATAL]') ? 'text-rose-400 bg-rose-500/5 px-2 py-1 rounded' : 'text-slate-300'}`}>
                 <span className="opacity-30 mr-4 select-none">{(i+1).toString().padStart(2, '0')}</span>
                 {line}
               </div>
             ))}
             {!pyodide && activeLanguage === 'python' && (
               <div className="flex flex-col items-center justify-center h-full gap-4 text-blue-500 font-bold text-[11px] uppercase tracking-widest">
                 <Loader2 size={32} className="animate-spin opacity-40" />
                 Synchronizing Pyodide Environment...
               </div>
             )}
          </div>
        )}

        {isGenerating && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#05070a]/70 backdrop-blur-3xl z-30 transition-all duration-700">
            <div className="relative mb-10">
              <div className="w-24 h-24 border border-blue-500/10 rounded-full animate-[spin_4s_linear_infinite]" />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-14 h-14 bg-blue-600/90 rounded-2xl flex items-center justify-center shadow-[0_0_50px_rgba(37,99,235,0.4)] rotate-45 animate-pulse">
                  <Zap size={28} className="text-white fill-white -rotate-45" />
                </div>
              </div>
            </div>
            <div className="text-center">
              <p className="text-[12px] font-black uppercase tracking-[0.6em] text-blue-500 mb-3 ml-2">Neural Synthesis</p>
              <p className="text-[10px] font-bold text-slate-500 uppercase tracking-widest animate-pulse">Manifesting Architectural Objects...</p>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

