const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  // Fixed: Renamed from 'prompt' to 'userInput' to avoid shadowing the global window.prompt function
  const [userInput, setUserInput] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GEMINI_3_PRO);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [terminalLogs, setTerminalLogs] = useState<string[]>(['[SYSTEM] VAYU_SYNTH_CORE Initiated.', '[SYSTEM] Ready for architecture input.']);
  const [streamingFile, setStreamingFile] = useState<string | null>(null);
  const [debouncedBundledCode, setDebouncedBundledCode] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const rawBundledCode = useMemo(() => {
    if (activeFile.path.endsWith('.py')) return activeFile.content;
    const htmlFile = files.find(f => f.path === 'index.html');
    let content = htmlFile ? htmlFile.content : `<!DOCTYPE html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body><div id="root"></div></body></html>`;

    const styles = files.filter(f => f.path.endsWith('.css')).map(f => `<style data-path="${f.path}">${f.content}</style>`).join('\n');
    const scripts = files.filter(f => f.path.endsWith('.js') || f.path.endsWith('.ts') || f.path.endsWith('.tsx')).map(f => {
      const isReactOrTS = f.path.endsWith('.ts') || f.path.endsWith('.tsx');
      return `<script type="${isReactOrTS ? 'text/babel' : 'module'}" ${isReactOrTS ? 'data-presets="react,typescript"' : ''} data-path="${f.path}">${f.content}</script>`;
    }).join('\n');

    if (content.includes('</head>')) content = content.replace('</head>', `${styles}\n</head>`);
    if (content.includes('</body>')) content = content.replace('</body>', `${scripts}\n</body>`);
    return content;
  }, [files, activeFile]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedBundledCode(rawBundledCode), 400); 
    return () => clearTimeout(handler);
  }, [rawBundledCode]);

  useEffect(() => {
    if (chatEndRef.current) chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  // Handle outside clicks for dropdown
  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsModelDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const addLog = (msg: string) => setTerminalLogs(prev => [...prev.slice(-10), `[${new Date().toLocaleTimeString()}] ${msg}`]);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const a = document.createElement('a');
    a.href = url;
    a.download = `vayu-project-${Date.now()}.zip`;
    a.click();
    addLog('Project manifest exported successfully.');
  };

  const createNewFile = () => {
    // Fixed: Explicitly using window.prompt to avoid conflict with 'userInput' state and prevent 'Type String is not callable' error
    const name = window.prompt('File Name (e.g., style.css):');
    if (!name) return;
    setFiles(prev => [...prev, { path: name, content: '', language: name.split('.').pop() || 'plaintext' }]);
    setActiveFilePath(name);
    addLog(`Buffer created: ${name}`);
  };

  const deleteFile = (path: string) => {
    if (files.length <= 1) return;
    if (confirm(`Delete ${path}?`)) {
      setFiles(prev => prev.filter(f => f.path !== path));
      if (activeFilePath === path) setActiveFilePath(files[0].path);
      addLog(`Purged: ${path}`);
    }
  };

  const parseAndApplyFiles = useCallback((text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let nextFiles = [...currentFiles];
      let hasChanges = false;

      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const idx = nextFiles.findIndex(f => f.path === path);
        if (idx !== -1) {
          if (nextFiles[idx].content !== content) {
            nextFiles[idx] = { ...nextFiles[idx], content };
            hasChanges = true;
          }
        } else {
          nextFiles.push({
            path, content,
            language: path.endsWith('.py') ? 'python' : 
                      (path.endsWith('.tsx') || path.endsWith('.ts')) ? 'typescript' : 
                      path.split('.').pop() || 'plaintext'
          });
          hasChanges = true;
        }
      }
      return hasChanges ? nextFiles : currentFiles;
    });

    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
      addLog(`Synthesizing stream: ${lastPath}`);
    }
  }, [streamingFile]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || isGenerating) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: userInput, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    const currentPrompt = userInput;
    setUserInput('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    addLog('Initiating architectural analysis...');

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true };
    setMessages(prev => [...prev, assistantMsg]);

    try {
      // Fixed: Using GoogleGenAI with proper initialization
      const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
      const systemInstruction = `You are VAYU ARCHITECT, an elite neural IDE engine.

      PHASE 1: CONTEXTUAL BLUEPRINTING
      Synthesize the optimal design system for the request.
      - Interactive Dashboards: React + Tailwind + Recharts.
      - Creative Visuals: Three.js + React Three Fiber.
      - Data Processing: Python (NumPy/Pandas logic).

      PHASE 2: SYNTHESIS RULES
      - Use ESM imports.
      - Implement glassmorphism using Tailwind: "backdrop-blur-md bg-white/10 border border-white/20".
      - Output ONLY valid code blocks using the Vayu file tag system.

      [FILE: path/to/file.ext]
      \`\`\`language
      CONTENT
      \`\`\`

      Workspace Context: ${files.length} active buffers.
      User Intent: ${currentPrompt}`;

      // Fixed: Using generateContentStream with model and contents parameters
      const response = await ai.models.generateContentStream({ 
        model: activeModel,
        contents: [{ role: 'user', parts: [{ text: currentPrompt }] }],
        config: {
          systemInstruction: systemInstruction,
        }
      });

      let fullContent = '';
      for await (const chunk of response) {
        // Fixed: Accessing text property directly (not as a function)
        const text = chunk.text;
        if (text) {
          fullContent += text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { 
            ...m, 
            content: fullContent, 
            status: fullContent.includes('[FILE:') ? 'coding' : 'analyzing' 
          } : m));
          parseAndApplyFiles(fullContent);
          if (fullContent.includes('[FILE:')) setCurrentStatus('coding');
        }
      }

      addLog('Synthesis complete. Runtime ready.');
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
    } catch (err: any) {
      addLog(`CRITICAL_ERR: ${err.message}`);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: `Synthesis Refused: ${err.message}`, isStreaming: false, error: err.message } : m));
    } finally {
      setIsGenerating(false);
      setCurrentStatus('idle');
      setStreamingFile(null);
    }
  };

  const selectedModelData = MODEL_LIST.find(m => m.id === activeModel)!;

  return (
    <div className="flex h-screen w-full bg-[#05070a] text-slate-200 overflow-hidden font-inter selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#080b10] border-r border-white/5 gap-8 z-50">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white shadow-lg shadow-blue-500/30 cursor-default">V</div>
        <div className="flex flex-col gap-6">
          <button 
            onClick={() => setActiveSidebarTab('chat')} 
            className={`p-2.5 rounded-xl transition-all relative group ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-500/10' : 'text-slate-600 hover:text-slate-400 hover:bg-white/5'}`}
          >
            <MessageSquare size={20} />
            {activeSidebarTab === 'chat' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 bg-blue-500 rounded-l-full" />}
          </button>
          <button 
            onClick={() => setActiveSidebarTab('files')} 
            className={`p-2.5 rounded-xl transition-all relative group ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-500/10' : 'text-slate-600 hover:text-slate-400 hover:bg-white/5'}`}
          >
            <FolderTree size={20} />
            {activeSidebarTab === 'files' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 bg-blue-500 rounded-l-full" />}
          </button>
        </div>
        <div className="mt-auto flex flex-col gap-6 pb-4">
          <button onClick={handleDownload} className="p-2.5 rounded-xl text-slate-600 hover:text-emerald-400 hover:bg-emerald-500/10 transition-all">
            <Download size={20} />
          </button>
          <Settings size={20} className="text-slate-600 hover:text-slate-400 cursor-pointer p-2.5 rounded-xl hover:bg-white/5 transition-all" />
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[400px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="h-16 px-6 border-b border-white/5 flex items-center justify-between bg-[#0b0e14]/50 backdrop-blur-md">
          <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500 flex items-center gap-2">
            {activeSidebarTab === 'chat' ? <BrainCircuit size={12} className="text-blue-500" /> : <Layers size={12} className="text-indigo-500" />}
            {activeSidebarTab === 'chat' ? 'Neural Link' : 'Workspace'}
          </span>

          {activeSidebarTab === 'chat' && (
            <div className="relative" ref={dropdownRef}>
              <button 
                onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)}
                className="flex items-center gap-3 bg-white/[0.03] border border-white/10 hover:border-white/20 transition-all rounded-lg px-3 py-2 text-[10px] font-bold text-slate-300"
              >
                <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'animate-ping' : ''}`} style={{ backgroundColor: selectedModelData.color }}></div>
                {selectedModelData.name}
                <ChevronDown size={12} className={`transition-transform duration-300 ${isModelDropdownOpen ? 'rotate-180' : ''}`} />
              </button>

              {isModelDropdownOpen && (
                <div className="absolute right-0 mt-2 w-56 bg-[#161b24] border border-white/10 rounded-xl shadow-2xl z-[60] overflow-hidden animate-in fade-in slide-in-from-top-2">
                  <div className="px-4 py-3 bg-white/[0.02] border-b border-white/5">
                    <span className="text-[9px] font-black text-slate-500 uppercase tracking-widest">Model Availability</span>
                  </div>
                  {MODEL_LIST.map((m) => (
                    <button
                      key={m.id}
                      onClick={() => { setActiveModel(m.id); setIsModelDropdownOpen(false); }}
                      className={`w-full flex flex-col gap-1 px-4 py-3 text-left hover:bg-white/5 transition-all ${activeModel === m.id ? 'bg-blue-500/5 border-l-2 border-blue-500' : ''}`}
                    >
                      <div className="flex items-center justify-between w-full">
                        <span className="text-[11px] font-bold text-slate-200">{m.name}</span>
                        <div className="flex items-center gap-2">
                          <span className={`text-[8px] px-1.5 py-0.5 rounded uppercase font-black tracking-tighter ${
                            m.status === 'optimal' ? 'text-emerald-400 bg-emerald-500/10' : 
                            m.status === 'high-load' ? 'text-amber-400 bg-amber-500/10' : 'text-blue-400 bg-blue-500/10'
                          }`}>
                            {m.status.replace('-', ' ')}
                          </span>
                          <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: m.color }} />
                        </div>
                      </div>
                      <span className="text-[9px] text-slate-500 font-medium">Core: {m.capability} Synthesis</span>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          {activeSidebarTab === 'chat' ? (
            <>
              <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-40">
                {messages.length === 0 && (
                  <div className="h-full flex flex-col items-center justify-center text-center px-10">
                    <div className="w-16 h-16 bg-blue-500/5 rounded-2xl flex items-center justify-center mb-6 border border-white/5">
                      <Sparkles size={28} className="text-blue-500/50" />
                    </div>
                    <h3 className="text-sm font-bold text-slate-300 mb-2">Architect Link Ready</h3>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium">Describe your structural requirements. Vayu Architect will handle the design-to-code synthesis.</p>
                  </div>
                )}
                {messages.map(msg => (
                  <div key={msg.id} className={`flex flex-col gap-2 ${msg.role === 'user' ? 'items-end' : 'items-start animate-in fade-in slide-in-from-bottom-2'}`}>
                    <div className={`max-w-[94%] p-5 rounded-2xl text-[13px] border transition-all ${
                      msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 shadow-xl' : 'bg-white/[0.03] text-slate-200 border-white/5'
                    }`}>
                      <div className="whitespace-pre-wrap leading-relaxed font-medium">
                        {msg.role === 'user' ? msg.content : msg.content.split(/\[FILE:/)[0].trim()}
                        {msg.isStreaming && !msg.content.split(/\[FILE:/)[0].trim() && (
                          <div className="flex gap-1.5 items-center py-2">
                            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse" />
                            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse delay-75" />
                            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse delay-150" />
                          </div>
                        )}
                      </div>
                    </div>
                    {msg.role === 'assistant' && msg.model && (
                      <span className="text-[9px] font-black uppercase text-slate-600 ml-2 tracking-widest flex items-center gap-2">
                        <Cpu size={10} /> {msg.model}
                      </span>
                    )}
                  </div>
                ))}
                <div ref={chatEndRef} />
              </div>

              <div className="absolute bottom-0 left-0 right-0 p-4 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent z-10">
                <div className="bg-[#161b24] border border-white/10 rounded-2xl p-4 shadow-2xl focus-within:border-blue-500/50 transition-all">
                  <textarea 
                    value={userInput}
                    onChange={(e) => setUserInput(e.target.value)}
                    onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                    placeholder="Enter architectural prompt..."
                    className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[140px] placeholder:text-slate-600 font-medium custom-scrollbar"
                  />
                  <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                    <div className="flex items-center gap-2 text-[9px] text-slate-500 font-black uppercase tracking-[0.2em]">
                      <Activity size={10} className={isGenerating ? 'animate-spin text-blue-500' : ''} />
                      {currentStatus}
                    </div>
                    <button 
                      onClick={handleSendMessage}
                      disabled={isGenerating || !userInput.trim()}
                      className="p-2.5 bg-blue-600 hover:bg-blue-500 disabled:opacity-20 rounded-xl transition-all text-white shadow-lg active:scale-95 flex items-center justify-center"
                    >
                      <Send size={16} />
                    </button>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <div className="flex flex-col h-full">
              <div className="p-4 flex justify-between items-center border-b border-white/5">
                <span className="text-[10px] font-black uppercase tracking-widest text-slate-600">Active Buffers</span>
                <button onClick={createNewFile} className="p-1.5 bg-white/5 hover:bg-white/10 rounded-lg text-slate-400 transition-all">
                  <Plus size={14} />
                </button>
              </div>
              <div className="flex-1 p-4 space-y-1 overflow-y-auto custom-scrollbar">
                {files.map(file => (
                  <div key={file.path} className="group relative">
                    <button 
                      onClick={() => setActiveFilePath(file.path)}
                      className={`w-full flex items-center gap-3 px-4 py-3 rounded-xl text-xs transition-all border ${
                        activeFilePath === file.path ? 'bg-blue-500/10 border-blue-500/30 text-blue-400' : 'border-transparent text-slate-500 hover:bg-white/5'
                      }`}
                    >
                      <Code2 size={14} className={activeFilePath === file.path ? 'text-blue-400' : 'text-slate-600'} />
                      <span className="flex-1 text-left truncate font-semibold">{file.path}</span>
                    </button>
                    {files.length > 1 && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); deleteFile(file.path); }}
                        className="absolute right-3 top-1/2 -translate-y-1/2 p-1.5 opacity-0 group-hover:opacity-100 hover:text-rose-500 transition-all text-slate-600"
                      >
                        <Trash2 size={12} />
                      </button>
                    )}
                  </div>
                ))}
              </div>

              {/* Terminal Output Area */}
              <div className="h-40 bg-black/40 border-t border-white/5 p-4 font-mono text-[10px] text-slate-500 flex flex-col gap-1 overflow-y-auto custom-scrollbar">
                <div className="flex items-center gap-2 mb-2 text-slate-600 font-bold uppercase tracking-widest">
                  <Terminal size={12} /> Console_Output
                </div>
                {terminalLogs.map((log, i) => (
                  <div key={i} className="flex gap-2">
                    <span className="text-slate-700 opacity-50">{i+1}</span>
                    <span>{log}</span>
                  </div>
                ))}
                {isGenerating && (
                  <div className="flex gap-2 text-blue-500 animate-pulse">
                    <span>{terminalLogs.length + 1}</span>
                    <span>_Await_Stream_Capture...</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#05070a]">
        <div className="h-16 px-8 flex items-center justify-between bg-[#0b0e14] border-b border-white/5">
          <div className="flex items-center gap-4">
            <div className="px-3 py-1 bg-white/5 rounded-lg border border-white/10">
              <span className="text-[10px] font-black text-blue-500 uppercase tracking-widest">{activeFile.language}</span>
            </div>
            <span className="text-[12px] font-bold text-slate-400 tracking-tight flex items-center gap-2">
              <FolderTree size={12} className="text-slate-600" />
              {activeFile.path}
            </span>
          </div>
          <div className="flex items-center gap-6">
             <div className="flex items-center gap-3 text-[10px] font-bold text-slate-500 uppercase tracking-widest px-4 py-2 bg-white/[0.02] border border-white/5 rounded-full">
               <div className="w-1.5 h-1.5 rounded-full bg-emerald-500 shadow-[0_0_10px_#10b981]"></div>
               VAYU_SYNTH_CORE_V2.5
             </div>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 relative bg-[#0b0e14]">
            <Editor 
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              options={{
                minimap: { enabled: false },
                fontSize: 14,
                fontFamily: "'Fira Code', monospace",
                automaticLayout: true,
                readOnly: isGenerating && streamingFile === activeFile.path,
                lineNumbers: 'on',
                renderLineHighlight: 'all',
                scrollBeyondLastLine: false,
                cursorSmoothCaretAnimation: 'on',
                smoothScrolling: true,
                padding: { top: 32, bottom: 32 },
                scrollbar: { vertical: 'visible', verticalScrollbarSize: 6 }
              }}
              onChange={(val) => {
                if (!isGenerating) setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f));
              }}
            />
            {isGenerating && streamingFile === activeFile.path && (
              <div className="absolute top-4 right-8 z-10 flex items-center gap-2 text-[10px] font-bold text-blue-500 bg-blue-500/10 border border-blue-500/20 px-3 py-1.5 rounded-full backdrop-blur-md animate-pulse shadow-2xl">
                <Zap size={10} className="fill-current" />
                NEURAL_SYNC_ACTIVE
              </div>
            )}
          </div>

          <div className="flex-1 bg-white">
            <Preview 
              code={debouncedBundledCode} 
              isGenerating={isGenerating} 
              activeLanguage={activeFile.path.endsWith('.py') ? 'python' : 'web'} 
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

export enum AIModel {
  GPT_4O = 'gpt-4o',
  CLAUDE_3_5_SONNET = 'claude-3-5-sonnet',
  GEMINI_1_5_PRO = 'gemini-1.5-pro',
  GEMINI_1_5_FLASH = 'gemini-1.5-flash',
}

export interface ModelMetadata {
  id: AIModel;
  name: string;
  status: 'optimal' | 'high-load' | 'latency';
  capability: 'Reasoning' | 'Creative' | 'Speed';
  color: string;
}

export const MODEL_LIST: ModelMetadata[] = [
  { id: AIModel.GPT_4O, name: 'GPT-4o', status: 'optimal', capability: 'Reasoning', color: '#10b981' },
  { id: AIModel.CLAUDE_3_5_SONNET, name: 'Claude 3.5', status: 'optimal', capability: 'Creative', color: '#f59e0b' },
  { id: AIModel.GEMINI_1_5_PRO, name: 'Gemini 1.5 Pro', status: 'high-load', capability: 'Reasoning', color: '#8b5cf6' },
  { id: AIModel.GEMINI_1_5_FLASH, name: 'Gemini 1.5 Flash', status: 'optimal', capability: 'Speed', color: '#3b82f6' },
];

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: string;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'idle';
  error?: string;
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

declare global {
  interface Window {
    puter: any;
    JSZip: any;
    process: any;
  }
}

import * as React from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry, MODEL_LIST, ModelMetadata } from './types';
import { 
  Code2, 
  MessageSquare, 
  Download, 
  Settings, 
  Zap, 
  FolderTree,
  Send,
  Cpu,
  BrainCircuit,
  Terminal,
  Layers,
  Sparkles,
  RefreshCw,
  Plus,
  Trash2,
  ChevronDown,
  Activity,
  Box
} from 'lucide-react';

const { useState, useEffect, useRef, useMemo, useCallback } = React;

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    :root { --vayu-accent: #3b82f6; --vayu-bg: #05070a; }
    body { 
      background: radial-gradient(circle at top right, #0a0e14, #05070a); 
      color: #f8fafc; 
      font-family: 'Inter', sans-serif; 
      height: 100vh; 
      display: flex; 
      align-items: center; 
      justify-content: center; 
      margin: 0; 
      overflow: hidden;
    }
    .neural-container {
      text-align: center;
      animation: synthesis 1.5s cubic-bezier(0.16, 1, 0.3, 1);
    }
    h1 {
      font-size: 6rem;
      font-weight: 900;
      letter-spacing: -0.06em;
      background: linear-gradient(to bottom right, #fff, #475569);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      margin: 0;
    }
    .status-pill {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      padding: 0.6rem 1.2rem;
      background: rgba(59, 130, 246, 0.08);
      border: 1px solid rgba(59, 130, 246, 0.15);
      border-radius: 100px;
      font-size: 0.7rem;
      font-weight: 700;
      color: #60a5fa;
      letter-spacing: 0.1em;
      text-transform: uppercase;
      margin-bottom: 2.5rem;
    }
    @keyframes synthesis { from { opacity: 0; filter: blur(20px); transform: scale(0.95); } to { opacity: 1; filter: blur(0); transform: scale(1); } }
  </style>
</head>
<body>
  <div class="neural-container">
    <div class="status-pill">
      <div class="w-2 h-2 rounded-full bg-blue-500 animate-pulse"></div> 
      Vayu Neural OS Online
    </div>
    <h1>VAYU CODE</h1>
    <p style="color: #64748b; font-size: 1.125rem; margin-top: 1rem; font-weight: 400; max-width: 400px; margin-left: auto; margin-right: auto;">Describe your architectural vision to begin synthesis.</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GPT_4O);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'idle'>('idle');
  const [terminalLogs, setTerminalLogs] = useState<string[]>(['[SYSTEM] VAYU_SYNTH_CORE Initiated.', '[SYSTEM] Ready for architecture input.']);
  const [streamingFile, setStreamingFile] = useState<string | null>(null);
  const [debouncedBundledCode, setDebouncedBundledCode] = useState('');

  const chatEndRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const rawBundledCode = useMemo(() => {
    if (activeFile.path.endsWith('.py')) return activeFile.content;
    const htmlFile = files.find(f => f.path === 'index.html');
    let content = htmlFile ? htmlFile.content : `<!DOCTYPE html><html><head><script src="https://cdn.tailwindcss.com"></script></head><body><div id="root"></div></body></html>`;

    const styles = files.filter(f => f.path.endsWith('.css')).map(f => `<style data-path="${f.path}">${f.content}</style>`).join('\n');
    const scripts = files.filter(f => f.path.endsWith('.js') || f.path.endsWith('.ts') || f.path.endsWith('.tsx')).map(f => {
      const isReactOrTS = f.path.endsWith('.ts') || f.path.endsWith('.tsx');
      return `<script type="${isReactOrTS ? 'text/babel' : 'module'}" ${isReactOrTS ? 'data-presets="react,typescript"' : ''} data-path="${f.path}">${f.content}</script>`;
    }).join('\n');

    if (content.includes('</head>')) content = content.replace('</head>', `${styles}\n</head>`);
    if (content.includes('</body>')) content = content.replace('</body>', `${scripts}\n</body>`);
    return content;
  }, [files, activeFile]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedBundledCode(rawBundledCode), 400); 
    return () => clearTimeout(handler);
  }, [rawBundledCode]);

  useEffect(() => {
    if (chatEndRef.current) chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setIsModelDropdownOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const addLog = (msg: string) => setTerminalLogs(prev => [...prev.slice(-15), `[${new Date().toLocaleTimeString()}] ${msg}`]);

  const handleDownload = async () => {
    if (!window.JSZip) return;
    const zip = new window.JSZip();
    files.forEach(f => zip.file(f.path, f.content));
    const content = await zip.generateAsync({ type: 'blob' });
    const url = URL.createObjectURL(content);
    const a = document.createElement('a');
    a.href = url;
    a.download = `vayu-bundle-${Date.now()}.zip`;
    a.click();
    addLog('Bundle Manifest Exported.');
  };

  const createNewFile = () => {
    const name = window.prompt('Synthesis Object Identifier (e.g., app.tsx):');
    if (!name) return;
    setFiles(prev => [...prev, { path: name, content: '', language: name.split('.').pop() || 'plaintext' }]);
    setActiveFilePath(name);
    addLog(`New buffer synchronized: ${name}`);
  };

  const deleteFile = (path: string) => {
    if (files.length <= 1) return;
    if (confirm(`Purge architectural object ${path}?`)) {
      setFiles(prev => prev.filter(f => f.path !== path));
      if (activeFilePath === path) setActiveFilePath(files[0].path);
      addLog(`Object purged: ${path}`);
    }
  };

  const parseAndApplyFiles = useCallback((text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;

    setFiles(currentFiles => {
      let nextFiles = [...currentFiles];
      let hasChanges = false;

      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;

        const idx = nextFiles.findIndex(f => f.path === path);
        if (idx !== -1) {
          if (nextFiles[idx].content !== content) {
            nextFiles[idx] = { ...nextFiles[idx], content };
            hasChanges = true;
          }
        } else {
          nextFiles.push({
            path, content,
            language: path.endsWith('.py') ? 'python' : 
                      (path.endsWith('.tsx') || path.endsWith('.ts')) ? 'typescript' : 
                      path.split('.').pop() || 'plaintext'
          });
          hasChanges = true;
        }
      }
      return hasChanges ? nextFiles : currentFiles;
    });

    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
      addLog(`Synthesizing trace: ${lastPath}`);
    }
  }, [streamingFile]);

  const handleSendMessage = async () => {
    if (!userInput.trim() || isGenerating) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: userInput, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    const currentPrompt = userInput;
    setUserInput('');
    setIsGenerating(true);
    setCurrentStatus('analyzing');
    addLog('Initiating Neural Link...');

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true };
    setMessages(prev => [...prev, assistantMsg]);

    try {
      const systemInstruction = `You are VAYU_OS_ARCHITECT. An advanced browser-based IDE engine powered by Puter.js.

      PHASE 1: CONTEXTUAL UNDERSTANDING
      Analyze the user request within the current workspace context.
      Current Files: ${files.map(f => f.path).join(', ')}

      PHASE 2: SYNTHESIS PROTOCOL
      - Determine if the stack requires React (TSX/Tailwind), Three.js (3D), or Python (Algorithm/Data).
      - Maintain glassmorphism design principles (backdrop-blur, border-white/20, bg-white/10).
      - ALWAYS use ESM imports.
      - Output code in the Vayu Tagged Format:

      [FILE: path/to/file.ext]
      \`\`\`language
      CONTENT
      \`\`\`

      Execute synthesis for: ${currentPrompt}`;

      let fullContent = '';
      const response = await window.puter.ai.chat(systemInstruction, { 
        model: activeModel, 
        stream: true 
      });

      for await (const chunk of response) {
        const text = typeof chunk === 'string' ? chunk : (chunk.text || chunk.message?.content || "");
        if (text) {
          fullContent += text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { 
            ...m, 
            content: fullContent, 
            status: fullContent.includes('[FILE:') ? 'coding' : 'analyzing' 
          } : m));
          parseAndApplyFiles(fullContent);
          if (fullContent.includes('[FILE:')) setCurrentStatus('coding');
        }
      }

      addLog('Neural Synthesis finalized.');
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
    } catch (err: any) {
      addLog(`SYNTH_FAIL: ${err.message}`);
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: `Synthesis Refused: ${err.message}`, isStreaming: false, error: err.message } : m));
    } finally {
      setIsGenerating(false);
      setCurrentStatus('idle');
      setStreamingFile(null);
    }
  };

  const selectedModelData = MODEL_LIST.find(m => m.id === activeModel)!;

  return (
    <div className="flex h-screen w-full bg-[#05070a] text-slate-200 overflow-hidden font-inter selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#080b10] border-r border-white/5 gap-8 z-50">
        <div className="w-10 h-10 bg-gradient-to-br from-blue-600 to-indigo-700 rounded-xl flex items-center justify-center font-black text-white shadow-xl shadow-blue-500/20 cursor-default ring-1 ring-white/10">V</div>
        <div className="flex flex-col gap-6">
          <button 
            onClick={() => setActiveSidebarTab('chat')} 
            className={`p-2.5 rounded-xl transition-all relative group ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-500/10' : 'text-slate-600 hover:text-slate-400 hover:bg-white/5'}`}
          >
            <MessageSquare size={20} />
            {activeSidebarTab === 'chat' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 bg-blue-500 rounded-l-full shadow-[0_0_10px_#3b82f6]" />}
          </button>
          <button 
            onClick={() => setActiveSidebarTab('files')} 
            className={`p-2.5 rounded-xl transition-all relative group ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-500/10' : 'text-slate-600 hover:text-slate-400 hover:bg-white/5'}`}
          >
            <FolderTree size={20} />
            {activeSidebarTab === 'files' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 bg-blue-500 rounded-l-full shadow-[0_0_10px_#3b82f6]" />}
          </button>
        </div>
        <div className="mt-auto flex flex-col gap-6 pb-4">
          <button onClick={handleDownload} className="p-2.5 rounded-xl text-slate-600 hover:text-emerald-400 hover:bg-emerald-500/10 transition-all">
            <Download size={20} />
          </button>
          <Settings size={20} className="text-slate-600 hover:text-slate-400 cursor-pointer p-2.5 rounded-xl hover:bg-white/5 transition-all" />
        </div>
      </div>

      {/* Sidebar Panel */}
      <div className="w-[400px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="h-16 px-6 border-b border-white/5 flex items-center justify-between bg-[#0b0e14]/80 backdrop-blur-xl">
          <span className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-500 flex items-center gap-2">
            {activeSidebarTab === 'chat' ? <BrainCircuit size={12} className="text-blue-500" /> : <Layers size={12} className="text-indigo-500" />}
            {activeSidebarTab === 'chat' ? 'Neural Link' : 'Workspace'}
          </span>

          {activeSidebarTab === 'chat' && (
            <div className="relative" ref={dropdownRef}>
              <button 
                onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)}
                className="flex items-center gap-3 bg-white/[0.04] border border-white/10 hover:border-white/20 transition-all rounded-lg px-3 py-2 text-[10px] font-bold text-slate-300 group"
              >
                <div className={`w-1.5 h-1.5 rounded-full ${isGenerating ? 'animate-ping' : ''}`} style={{ backgroundColor: selectedModelData.color }}></div>
                {selectedModelData.name}
                <ChevronDown size={12} className={`transition-transform duration-300 text-slate-600 group-hover:text-slate-400 ${isModelDropdownOpen ? 'rotate-180' : ''}`} />
              </button>

              {isModelDropdownOpen && (
                <div className="absolute right-0 mt-3 w-64 bg-[#121820]/95 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-[0_20px_50px_rgba(0,0,0,0.5)] z-[100] overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
                  <div className="px-5 py-4 bg-white/[0.02] border-b border-white/5">
                    <span className="text-[9px] font-black text-slate-500 uppercase tracking-[0.2em]">Neural Node Availability</span>
                  </div>
                  <div className="max-h-[300px] overflow-y-auto custom-scrollbar">
                    {MODEL_LIST.map((m) => (
                      <button
                        key={m.id}
                        onClick={() => { setActiveModel(m.id); setIsModelDropdownOpen(false); }}
                        className={`w-full flex flex-col gap-1.5 px-5 py-4 text-left hover:bg-white/5 transition-all border-l-2 ${activeModel === m.id ? 'bg-blue-500/5 border-blue-500' : 'border-transparent'}`}
                      >
                        <div className="flex items-center justify-between w-full">
                          <span className="text-[12px] font-bold text-slate-100">{m.name}</span>
                          <div className="flex items-center gap-2">
                            <span className={`text-[8px] px-2 py-0.5 rounded-full uppercase font-black tracking-tighter ${
                              m.status === 'optimal' ? 'text-emerald-400 bg-emerald-500/10' : 
                              m.status === 'high-load' ? 'text-amber-400 bg-amber-500/10' : 'text-blue-400 bg-blue-500/10'
                            }`}>
                              {m.status.replace('-', ' ')}
                            </span>
                            <div className="w-2 h-2 rounded-full shadow-lg" style={{ backgroundColor: m.color }} />
                          </div>
                        </div>
                        <div className="flex items-center gap-2 text-[9px] text-slate-500 font-medium italic">
                          <Activity size={10} />
                          Synthesizing: {m.capability} Profile
                        </div>
                      </button>
                    ))}
                  </div>
                </div>
              )}
            </div>
          )}
        </div>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          {activeSidebarTab === 'chat' ? (
            <>
              <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-44">
                {messages.length === 0 && (
                  <div className="h-full flex flex-col items-center justify-center text-center px-10 pt-20">
                    <div className="w-20 h-20 bg-blue-500/5 rounded-3xl flex items-center justify-center mb-8 border border-white/5 shadow-inner">
                      <Sparkles size={32} className="text-blue-500/40" />
                    </div>
                    <h3 className="text-lg font-bold text-slate-200 mb-3 tracking-tight">Neural Sync Interface</h3>
                    <p className="text-xs text-slate-500 leading-relaxed font-medium max-w-[240px]">Command the Vayu Architect to synthesize modern design components and full-stack objects.</p>
                  </div>
                )}
                {messages.map(msg => (
                  <div key={msg.id} className={`flex flex-col gap-2 ${msg.role === 'user' ? 'items-end' : 'items-start animate-in fade-in slide-in-from-bottom-3 duration-500'}`}>
                    <div className={`max-w-[95%] p-5 rounded-2xl text-[13px] border transition-all ${
                      msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 shadow-2xl shadow-blue-500/20' : 'bg-white/[0.03] text-slate-200 border-white/5 backdrop-blur-md'
                    }`}>
                      <div className="whitespace-pre-wrap leading-relaxed font-medium">
                        {msg.role === 'user' ? msg.content : msg.content.split(/\[FILE:/)[0].trim()}
                        {msg.isStreaming && !msg.content.split(/\[FILE:/)[0].trim() && (
                          <div className="flex gap-2 items-center py-2">
                            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse shadow-[0_0_8px_#3b82f6]" />
                            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse delay-100 shadow-[0_0_8px_#3b82f6]" />
                            <div className="w-1.5 h-1.5 bg-blue-500 rounded-full animate-pulse delay-200 shadow-[0_0_8px_#3b82f6]" />
                          </div>
                        )}
                      </div>
                    </div>
                    {msg.role === 'assistant' && msg.model && (
                      <span className="text-[9px] font-black uppercase text-slate-600 ml-2 tracking-widest flex items-center gap-2">
                        <Box size={10} /> {msg.model} Node
                      </span>
                    )}
                  </div>
                ))}
                <div ref={chatEndRef} />
              </div>

              {/* Refined Input UI */}
              <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent z-10">
                <div className="bg-[#161b24]/80 backdrop-blur-2xl border border-white/10 rounded-2xl p-5 shadow-[0_25px_60px_-15px_rgba(0,0,0,0.6)] focus-within:border-blue-500/40 transition-all">
                  <textarea 
                    value={userInput}
                    onChange={(e) => setUserInput(e.target.value)}
                    onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }}
                    placeholder="Describe architectural intent..."
                    className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[160px] placeholder:text-slate-600 font-medium custom-scrollbar leading-relaxed"
                  />
                  <div className="flex justify-between items-center mt-4 pt-4 border-t border-white/5">
                    <div className="flex items-center gap-3 text-[9px] text-slate-500 font-black uppercase tracking-[0.3em]">
                      <Activity size={12} className={isGenerating ? 'animate-spin text-blue-500' : 'text-slate-700'} />
                      {currentStatus}
                    </div>
                    <button 
                      onClick={handleSendMessage}
                      disabled={isGenerating || !userInput.trim()}
                      className="group p-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-20 rounded-xl transition-all text-white shadow-xl active:scale-95 flex items-center justify-center"
                    >
                      <Send size={18} className="transition-transform group-hover:translate-x-0.5 group-hover:-translate-y-0.5" />
                    </button>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <div className="flex flex-col h-full">
              <div className="p-5 flex justify-between items-center border-b border-white/5 bg-white/[0.01]">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Workspace_Manifest</span>
                <button onClick={createNewFile} className="p-2 bg-white/5 hover:bg-white/10 rounded-lg text-slate-400 transition-all border border-white/5">
                  <Plus size={14} />
                </button>
              </div>
              <div className="flex-1 p-5 space-y-2 overflow-y-auto custom-scrollbar">
                {files.map(file => (
                  <div key={file.path} className="group relative">
                    <button 
                      onClick={() => setActiveFilePath(file.path)}
                      className={`w-full flex items-center gap-4 px-5 py-4 rounded-xl text-xs transition-all border ${
                        activeFilePath === file.path ? 'bg-blue-500/10 border-blue-500/30 text-blue-400' : 'border-transparent text-slate-500 hover:bg-white/5'
                      }`}
                    >
                      <Code2 size={16} className={activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700 group-hover:text-slate-500'} />
                      <span className="flex-1 text-left truncate font-bold tracking-tight">{file.path}</span>
                    </button>
                    {files.length > 1 && (
                      <button 
                        onClick={(e) => { e.stopPropagation(); deleteFile(file.path); }}
                        className="absolute right-4 top-1/2 -translate-y-1/2 p-2 opacity-0 group-hover:opacity-100 hover:text-rose-500 transition-all text-slate-700 bg-[#0b0e14] rounded-lg shadow-lg"
                      >
                        <Trash2 size={14} />
                      </button>
                    )}
                  </div>
                ))}
              </div>

              {/* Terminal Logs */}
              <div className="h-48 bg-black/60 border-t border-white/5 p-5 font-mono text-[10px] text-slate-500 flex flex-col gap-2 overflow-y-auto custom-scrollbar">
                <div className="flex items-center gap-2 mb-2 text-slate-600 font-bold uppercase tracking-[0.2em] border-b border-white/5 pb-2">
                  <Terminal size={14} /> LOGS_CORE
                </div>
                {terminalLogs.map((log, i) => (
                  <div key={i} className="flex gap-3 hover:bg-white/5 px-1 py-0.5 rounded transition-colors group">
                    <span className="text-slate-800 font-bold select-none group-hover:text-slate-700">{(i+1).toString().padStart(2, '0')}</span>
                    <span className="leading-relaxed">{log}</span>
                  </div>
                ))}
                {isGenerating && (
                  <div className="flex gap-3 text-blue-500/80 animate-pulse bg-blue-500/5 px-1 py-0.5 rounded">
                    <span>{(terminalLogs.length + 1).toString().padStart(2, '0')}</span>
                    <span className="font-bold">_Capturing_Neural_Stream...</span>
                  </div>
                )}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Main Content Area */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#05070a] relative">
        <div className="h-16 px-8 flex items-center justify-between bg-[#0b0e14]/80 backdrop-blur-2xl border-b border-white/5 z-20">
          <div className="flex items-center gap-5">
            <div className="px-3 py-1.5 bg-white/5 rounded-lg border border-white/10 shadow-inner">
              <span className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em]">{activeFile.language}</span>
            </div>
            <span className="text-[13px] font-bold text-slate-300 tracking-tight flex items-center gap-3">
              <div className="w-1 h-3 bg-blue-500/50 rounded-full" />
              {activeFile.path}
            </span>
          </div>
          <div className="flex items-center gap-4">
