import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Maximize2, Loader2, Zap, RefreshCw, Activity, ShieldCheck, Cpu } from 'lucide-react';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
  activeLanguage: 'web' | 'python';
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating, activeLanguage }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pythonOutput, setPythonOutput] = useState<string[]>([]);
  const [pyodide, setPyodide] = useState<any>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [runtimeStatus, setRuntimeStatus] = useState<'idle' | 'running' | 'error'>('idle');

  useEffect(() => {
    if (activeLanguage === 'python' && !pyodide && (window as any).loadPyodide) {
      (window as any).loadPyodide().then((res: any) => setPyodide(res));
    }
  }, [activeLanguage, pyodide]);

  const runCode = useCallback(async () => {
    if (!code) return;
    setRuntimeStatus('running');

    if (activeLanguage === 'web') {
      if (iframeRef.current) {
        // Reset iframe doc for clean reload
        iframeRef.current.srcdoc = '';
        setTimeout(() => {
          if (iframeRef.current) {
            iframeRef.current.srcdoc = code;
            setRuntimeStatus('idle');
          }
        }, 100);
      }
    } else if (activeLanguage === 'python' && pyodide) {
      setPythonOutput(['>>> Initializing Neural Logic Trace...']);
      try {
        pyodide.setStdout({ batched: (text: string) => setPythonOutput(prev => [...prev, text]) });
        pyodide.setStderr({ batched: (text: string) => {
          setPythonOutput(prev => [...prev, `[ERR] ${text}`]);
          setRuntimeStatus('error');
        }});
        await pyodide.runPythonAsync(code);
        setRuntimeStatus('idle');
      } catch (err: any) {
        setPythonOutput(prev => [...prev, `[CRITICAL_FAIL] ${err.message}`]);
        setRuntimeStatus('error');
      }
    }
  }, [code, activeLanguage, pyodide]);

  useEffect(() => {
    if (isGenerating) return;
    runCode();
  }, [code, isGenerating, refreshKey, runCode]);

  const handleRefresh = () => {
    setRefreshKey(prev => prev + 1);
  };

  const toggleFullscreen = () => {
    if (!containerRef.current) return;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      containerRef.current.requestFullscreen();
    }
  };

  return (
    <div ref={containerRef} className="w-full h-full bg-[#05070a] relative flex flex-col group overflow-hidden">
      {/* HUD Overlay */}
      <div className="absolute top-6 right-8 z-50 flex items-center gap-4 opacity-0 group-hover:opacity-100 transition-all duration-700 translate-y-3 group-hover:translate-y-0">
        <div className="flex items-center gap-3 px-4 py-2 bg-black/60 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-2xl">
           <div className={`w-2 h-2 rounded-full ${runtimeStatus === 'running' ? 'bg-blue-500 animate-pulse' : runtimeStatus === 'error' ? 'bg-rose-500' : 'bg-emerald-500 shadow-[0_0_8px_#10b981]'}`} />
           <span className="text-[10px] font-black uppercase text-slate-300 tracking-[0.2em]">{activeLanguage}_RUNTIME_OK</span>
        </div>
        <button 
          className="p-3 bg-white/5 backdrop-blur-3xl text-white rounded-2xl border border-white/10 shadow-2xl hover:bg-white/10 hover:border-white/20 transition-all active:scale-90" 
          title="Force Restart Synthesis" 
          onClick={handleRefresh}
        >
          <RefreshCw size={16} className={runtimeStatus === 'running' ? 'animate-spin' : ''} />
        </button>
        <button 
          className="p-3 bg-white/5 backdrop-blur-3xl text-white rounded-2xl border border-white/10 shadow-2xl hover:bg-white/10 hover:border-white/20 transition-all active:scale-90" 
          title="Full Manifestation" 
          onClick={toggleFullscreen}
        >
          <Maximize2 size={16} />
        </button>
      </div>

      <div className="flex-1 relative overflow-hidden">
        {activeLanguage === 'web' ? (
          <iframe 
            ref={iframeRef} 
            title="Vayu Web Preview" 
            className={`w-full h-full border-none bg-white transition-all duration-1000 ${isGenerating ? 'opacity-20 grayscale scale-95 blur-md pointer-events-none' : 'opacity-100 scale-100'}`} 
            sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin" 
          />
        ) : (
          <div className="w-full h-full bg-[#05070a] p-16 font-mono text-[14px] overflow-auto text-slate-300 custom-scrollbar relative">
             <div className="flex items-center justify-between mb-10 pb-5 border-b border-white/10">
                <div className="flex items-center gap-4">
                  <Cpu size={20} className="text-emerald-500" />
                  <div>
                    <span className="text-[12px] font-black uppercase tracking-[0.3em] text-slate-100 block">Neural Runtime Instance</span>
                    <span className="text-[9px] text-slate-600 font-bold uppercase tracking-widest mt-1">Virtual Machine Layer 01</span>
                  </div>
                </div>
                <div className="flex items-center gap-3 text-[11px] text-slate-600 font-bold bg-white/[0.02] px-4 py-2 rounded-xl border border-white/5">
                  <ShieldCheck size={16} /> SECURE_TRACE_ACTIVE
                </div>
             </div>

             <div className="space-y-4">
               {pythonOutput.map((line, i) => (
                 <div key={i} className={`flex gap-6 leading-relaxed ${line.includes('[ERR]') || line.includes('[CRITICAL_FAIL]') ? 'text-rose-400 bg-rose-500/5 px-4 py-3 rounded-xl border border-rose-500/20' : 'text-slate-300'}`}>
                   <span className="opacity-20 font-black select-none text-[10px] pt-1">{(i+1).toString().padStart(2, '0')}</span>
                   <span className="font-medium whitespace-pre-wrap">{line}</span>
                 </div>
               ))}
             </div>

             {pythonOutput.length === 1 && !isGenerating && (
               <div className="mt-10 text-slate-700 italic text-[11px] animate-pulse">_Awaiting_Logic_Execution...</div>
             )}

             {!pyodide && activeLanguage === 'python' && (
               <div className="absolute inset-0 flex flex-col items-center justify-center gap-6 text-blue-500 bg-[#05070a] z-50">
                 <div className="relative">
                   <div className="w-20 h-20 border-2 border-blue-500/20 rounded-full animate-ping opacity-20" />
                   <div className="absolute inset-0 flex items-center justify-center">
                     <Loader2 size={40} className="animate-spin text-blue-500" />
                   </div>
                 </div>
                 <div className="text-center">
                    <span className="text-[11px] font-black uppercase tracking-[0.5em] block mb-2">Syncing Virtual Env</span>
                    <span className="text-[9px] text-slate-600 font-bold uppercase tracking-widest">Hydrating Pyodide Runtimes...</span>
                 </div>
               </div>
             )}
          </div>
        )}

        {isGenerating && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#05070a]/80 backdrop-blur-3xl z-[60] transition-all duration-1000">
            <div className="relative mb-12">
              <div className="w-32 h-32 border border-blue-500/10 rounded-full animate-[spin_8s_linear_infinite]" />
              <div className="w-24 h-24 border border-blue-400/20 rounded-full absolute top-4 left-4 animate-[spin_4s_linear_infinite_reverse]" />
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-16 h-16 bg-blue-600/90 rounded-3xl flex items-center justify-center shadow-[0_0_70px_rgba(37,99,235,0.5)] rotate-45 animate-pulse">
                  <Zap size={32} className="text-white fill-white -rotate-45" />
                </div>
              </div>
            </div>
            <div className="text-center">
              <p className="text-[14px] font-black uppercase tracking-[0.7em] text-blue-500 mb-4 ml-3">Synthesizing</p>
              <div className="flex gap-1.5 items-center justify-center">
                 <div className="w-1 h-1 bg-slate-700 rounded-full animate-bounce" />
                 <div className="w-1 h-1 bg-slate-700 rounded-full animate-bounce delay-100" />
                 <div className="w-1 h-1 bg-slate-700 rounded-full animate-bounce delay-200" />
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

