          </button>
          <button onClick={() => onDebug(code)} title="Debug" className="p-1.5 hover:bg-white/5 rounded-lg text-slate-400 transition-all">
            <ShieldAlert size={14} />
          </button>
          {filePath && (
            <button 
              onClick={() => onApply(filePath, code)} 
              title="Apply to Workspace" 
              className="ml-2 flex items-center gap-1.5 px-2.5 py-1 bg-blue-600 hover:bg-blue-500 text-white text-[10px] font-black rounded-lg transition-all active:scale-95"
            >
              <Zap size={12} className="fill-current" />
              APPLY
            </button>
          )}
        </div>
      </div>
      <div className="p-4 overflow-x-auto custom-scrollbar">
        <pre className="text-[12px] leading-relaxed font-fira text-slate-300">
          <code>{code}</code>
        </pre>
      </div>
    </div>
  );
};

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { background: #05070a; color: #f8fafc; font-family: 'Inter', sans-serif; display: flex; align-items: center; justify-content: center; height: 100vh; margin: 0; overflow: hidden; }
    .glass { background: rgba(255, 255, 255, 0.03); backdrop-filter: blur(20px); border: 1px solid rgba(255, 255, 255, 0.05); border-radius: 2rem; padding: 4rem; text-align: center; box-shadow: 0 25px 50px -12px rgba(0, 0, 0, 0.5); }
    h1 { font-size: 4rem; font-weight: 900; background: linear-gradient(to right, #60a5fa, #a78bfa); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
  </style>
</head>
<body>
  <div class="glass">
    <h1>VAYU OS</h1>
    <p style="color: #64748b;">Awaiting Synthesis Instructions</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GPT_4O);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'diagnosing' | 'idle'>('idle');
  const [terminalLogs, setTerminalLogs] = useState<string[]>(['[VAYU_OS] Neural Core Ready.']);
  const [streamingFile, setStreamingFile] = useState<string | null>(null);
  const [debouncedBundledCode, setDebouncedBundledCode] = useState('');
  const [lastDiagnostic, setLastDiagnostic] = useState<DiagnosticReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const rawBundledCode = useMemo(() => {
    if (activeFile.path.endsWith('.py')) return activeFile.content;
    const htmlFile = files.find(f => f.path === 'index.html');
    let content = htmlFile ? htmlFile.content : `<!DOCTYPE html><html><body><div id="root"></div></body></html>`;
    const styles = files.filter(f => f.path.endsWith('.css')).map(f => `<style data-path="${f.path}">${f.content}</style>`).join('\n');
    const scripts = files.filter(f => f.path.endsWith('.js') || f.path.endsWith('.ts') || f.path.endsWith('.tsx')).map(f => {
      const isReactOrTS = f.path.endsWith('.ts') || f.path.endsWith('.tsx');
      return `<script type="${isReactOrTS ? 'text/babel' : 'module'}" ${isReactOrTS ? 'data-presets="react,typescript"' : ''} data-path="${f.path}">${f.content}</script>`;
    }).join('\n');
    if (content.includes('</head>')) content = content.replace('</head>', `${styles}\n</head>`);
    if (content.includes('</body>')) content = content.replace('</body>', `${scripts}\n</body>`);
    return content;
  }, [files, activeFile]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedBundledCode(rawBundledCode), 300); 
    return () => clearTimeout(handler);
  }, [rawBundledCode]);

  const addLog = (msg: string) => setTerminalLogs(prev => [...prev.slice(-20), `[${new Date().toLocaleTimeString()}] ${msg}`]);

  const applyFileChange = (path: string, content: string) => {
    setFiles(prev => {
      const idx = prev.findIndex(f => f.path === path);
      if (idx !== -1) {
        const next = [...prev];
        next[idx] = { ...next[idx], content };
        return next;
      }
      return [...prev, { path, content, language: path.split('.').pop() || 'plaintext' }];
    });
    setActiveFilePath(path);
    addLog(`Atomic Sync: ${path}`);
  };

  const handleRefineSnippet = (snippet: string) => {
    setUserInput(`Refine this logic:\n\n\`\`\`\n${snippet}\n\`\`\`\n\n`);
    setActiveSidebarTab('chat');
  };

  const handleDebugSnippet = (snippet: string) => {
    setUserInput(`Debug this snippet for potential issues:\n\n\`\`\`\n${snippet}\n\`\`\`\n\n`);
    handleSendMessage();
  };

  const parseAndApplyFiles = useCallback((text: string) => {
    const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
    let match;
    let lastPath: string | null = null;
    setFiles(currentFiles => {
      let nextFiles = [...currentFiles];
      let hasChanges = false;
      while ((match = fileRegex.exec(text)) !== null) {
        const path = match[1].trim();
        const content = match[2].trim();
        lastPath = path;
        const idx = nextFiles.findIndex(f => f.path === path);
        if (idx !== -1) {
          if (nextFiles[idx].content !== content) {
            nextFiles[idx] = { ...nextFiles[idx], content };
            hasChanges = true;
          }
        } else {
          nextFiles.push({
            path, content,
            language: path.endsWith('.py') ? 'python' : (path.endsWith('.tsx') || path.endsWith('.ts')) ? 'typescript' : path.split('.').pop() || 'plaintext'
          });
          hasChanges = true;
        }
      }
      return hasChanges ? nextFiles : currentFiles;
    });
    if (lastPath && lastPath !== streamingFile) {
      setStreamingFile(lastPath);
      setActiveFilePath(lastPath);
    }
  }, [streamingFile]);

  const handleSendMessage = async (forceDiagnostic = false) => {
    const textToProcess = forceDiagnostic ? "NEURAL_DIAGNOSTIC: Fix all errors." : userInput;
    if (!textToProcess.trim() || isGenerating) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: textToProcess, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    const currentInput = textToProcess;
    setUserInput('');
    setIsGenerating(true);
    setCurrentStatus(forceDiagnostic ? 'diagnosing' : 'analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true };
    setMessages(prev => [...prev, assistantMsg]);

    try {
      const workspaceContext = files.map(f => `FILE: ${f.path}\n\`\`\`${f.language}\n${f.content}\n\`\`\``).join('\n\n');
      const diagContext = forceDiagnostic && lastDiagnostic ? `DIAGNOSTIC_ERR: ${lastDiagnostic.error}\nLOGS: ${lastDiagnostic.logs.join('\n')}` : '';

      const systemInstruction = `You are VAYU_OS_ARCHITECT. A multi-file, context-aware IDE engine. 
      CURRENT_WORKSPACE:\n${workspaceContext}\n\n${diagContext}\n\n
      RULES:
      1. Be a "Cursor AI" clone. Be extremely smart and concise.
      2. Use [FILE: path] for full file generation.
      3. For smaller snippets, use standard markdown blocks.
      4. Always think project-wide. Fix dependencies automatically.`;

      let fullContent = '';
      const response = await window.puter.ai.chat(systemInstruction, { model: activeModel, stream: true });

      for await (const chunk of response) {
        const text = typeof chunk === 'string' ? chunk : (chunk.text || chunk.message?.content || "");
        if (text) {
          fullContent += text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent } : m));
          parseAndApplyFiles(fullContent);
        }
      }
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
    } catch (err: any) {
      addLog(`SYNTH_FAIL: ${err.message}`);
    } finally {
      setIsGenerating(false);
      setCurrentStatus('idle');
      setStreamingFile(null);
    }
  };

  const renderMessageContent = (msg: ChatMessage) => {
    const parts = msg.content.split(/```/);
    return parts.map((part, i) => {
      if (i % 2 === 0) return <div key={i} className="whitespace-pre-wrap">{part}</div>;

      const lines = part.split('\n');
      const langMatch = lines[0].trim();
      const code = lines.slice(1).join('\n').trim();

      // Try to find if this block was intended for a file
      const prevPart = parts[i-1] || "";
      const fileMatch = prevPart.match(/\[FILE:\s*([a-zA-Z0-9._\-/]+)\]/);
      const filePath = fileMatch ? fileMatch[1] : undefined;

      return (
        <ChatCodeBlock 
          key={i} 
          code={code} 
          language={langMatch || 'text'} 
          filePath={filePath}
          onApply={applyFileChange}
          onRefine={handleRefineSnippet}
          onDebug={handleDebugSnippet}
        />
      );
    });
  };

  return (
    <div className="flex h-screen w-full bg-[#05070a] text-slate-200 overflow-hidden font-inter selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-6 bg-[#080b10] border-r border-white/5 gap-8 z-50">
        <VayuLogo active={isGenerating} />
        <div className="flex flex-col gap-6">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-2.5 rounded-xl transition-all relative group ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-500/10 shadow-[0_0_20px_rgba(59,130,246,0.1)]' : 'text-slate-600 hover:text-slate-400'}`}>
            <MessageSquare size={20} />
            {activeSidebarTab === 'chat' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 bg-blue-500 rounded-l-full shadow-[0_0_10px_#3b82f6]" />}
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-2.5 rounded-xl transition-all relative group ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-500/10' : 'text-slate-600 hover:text-slate-400'}`}>
            <FolderTree size={20} />
            {activeSidebarTab === 'files' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-4 bg-blue-500 rounded-l-full shadow-[0_0_10px_#3b82f6]" />}
          </button>
        </div>
        <div className="mt-auto flex flex-col gap-6 pb-4">
          <button onClick={() => handleSendMessage(true)} className="p-2.5 rounded-xl text-slate-600 hover:text-amber-400 hover:bg-amber-500/10 transition-all" title="Project Diagnostic">
            <ShieldAlert size={20} className={lastDiagnostic?.error ? 'animate-pulse text-rose-500' : ''} />
          </button>
          <button onClick={() => window.location.reload()} className="p-2.5 rounded-xl text-slate-600 hover:text-blue-400 transition-all">
            <RefreshCw size={20} />
          </button>
        </div>
      </div>

      {/* Sidebar */}
      <div className="w-[400px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="h-16 px-6 border-b border-white/5 flex items-center justify-between bg-[#0b0e14]/50 backdrop-blur-xl">
          <span className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-500 flex items-center gap-2">
            {activeSidebarTab === 'chat' ? <BrainCircuit size={12} className="text-blue-500" /> : <Layers size={12} className="text-indigo-500" />}
            {activeSidebarTab === 'chat' ? 'Neural Link' : 'Workspace'}
          </span>
          {activeSidebarTab === 'chat' && (
            <div className="relative" ref={dropdownRef}>
              <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="flex items-center gap-3 bg-white/[0.04] border border-white/10 hover:border-white/20 transition-all rounded-lg px-3 py-2 text-[10px] font-bold text-slate-300">
                <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: MODEL_LIST.find(m => m.id === activeModel)?.color }}></div>
                {MODEL_LIST.find(m => m.id === activeModel)?.name}
                <ChevronDown size={12} className={`transition-transform ${isModelDropdownOpen ? 'rotate-180' : ''}`} />
              </button>
              {isModelDropdownOpen && (
                <div className="absolute right-0 mt-3 w-64 bg-[#121820]/95 backdrop-blur-3xl border border-white/10 rounded-2xl shadow-2xl z-[100] overflow-hidden">
                  {MODEL_LIST.map((m) => (
                    <button key={m.id} onClick={() => { setActiveModel(m.id); setIsModelDropdownOpen(false); }} className={`w-full flex flex-col gap-1 px-5 py-4 text-left hover:bg-white/5 transition-all border-l-2 ${activeModel === m.id ? 'bg-blue-500/5 border-blue-500' : 'border-transparent'}`}>
                      <div className="flex items-center justify-between w-full">
                        <span className="text-[12px] font-bold text-slate-100">{m.name}</span>
                        <span className={`text-[8px] px-2 py-0.5 rounded-full uppercase font-black ${m.status === 'optimal' ? 'text-emerald-400 bg-emerald-500/10' : 'text-amber-400 bg-amber-500/10'}`}>{m.status}</span>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          {activeSidebarTab === 'chat' ? (
            <>
              <div className="flex-1 overflow-y-auto p-6 space-y-6 custom-scrollbar pb-40">
                {messages.map(msg => (
                  <div key={msg.id} className={`flex flex-col gap-2 ${msg.role === 'user' ? 'items-end' : 'items-start animate-in fade-in slide-in-from-bottom-2'}`}>
                    <div className={`max-w-[98%] p-5 rounded-2xl text-[13px] border transition-all ${msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 shadow-xl' : 'bg-white/[0.03] text-slate-200 border-white/5'}`}>
                      {renderMessageContent(msg)}
                    </div>
                  </div>
                ))}
                <div ref={chatEndRef} />
              </div>
              <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent z-10">
                <div className="bg-[#161b24] border border-white/10 rounded-2xl p-4 shadow-2xl focus-within:border-blue-500/40 transition-all">
                  <textarea value={userInput} onChange={(e) => setUserInput(e.target.value)} onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} placeholder="Talk to Vayu Architect..." className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[160px] placeholder:text-slate-600 font-medium custom-scrollbar" />
                  <div className="flex justify-between items-center mt-3 pt-3 border-t border-white/5">
                    <div className="flex items-center gap-2 text-[9px] text-slate-500 font-black uppercase tracking-[0.2em]">
                      <Activity size={10} className={isGenerating ? 'animate-spin text-blue-500' : ''} />
                      {currentStatus}
                    </div>
                    <button onClick={() => handleSendMessage()} disabled={isGenerating || !userInput.trim()} className="p-2.5 bg-blue-600 hover:bg-blue-500 rounded-xl transition-all shadow-lg active:scale-95"><Send size={16} /></button>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <div className="flex flex-col h-full">
              <div className="p-5 flex justify-between items-center border-b border-white/5 bg-white/[0.01]">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Workspace</span>
                <button onClick={() => {
                  const name = window.prompt("New File Name:");
                  if (name) applyFileChange(name, "");
                }} className="p-2 bg-white/5 hover:bg-white/10 rounded-lg text-slate-400 border border-white/5"><Plus size={14} /></button>
              </div>
              <div className="flex-1 p-5 space-y-2 overflow-y-auto custom-scrollbar">
                {files.map(file => (
                  <div key={file.path} className="group relative">
                    <button onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-4 px-5 py-3.5 rounded-xl text-xs transition-all border ${activeFilePath === file.path ? 'bg-blue-500/10 border-blue-500/30 text-blue-400' : 'border-transparent text-slate-500 hover:bg-white/5'}`}>
                      <Code2 size={16} className={activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'} />
                      <span className="flex-1 text-left truncate font-bold tracking-tight">{file.path}</span>
                    </button>
                    <button onClick={(e) => { e.stopPropagation(); setFiles(f => f.filter(fi => fi.path !== file.path)); }} className="absolute right-4 top-1/2 -translate-y-1/2 p-2 opacity-0 group-hover:opacity-100 hover:text-rose-500 transition-all text-slate-700"><Trash2 size={14} /></button>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Editor & Preview */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#05070a] relative">
        <div className="h-16 px-8 flex items-center justify-between bg-[#0b0e14]/50 border-b border-white/5 backdrop-blur-3xl z-20">
          <div className="flex items-center gap-5">
            <div className="px-3 py-1 bg-blue-500/10 rounded border border-blue-500/20 shadow-inner">
              <span className="text-[10px] font-black text-blue-400 uppercase tracking-widest">{activeFile.language}</span>
            </div>
            <span className="text-[13px] font-bold text-slate-400 flex items-center gap-3">
              <FolderTree size={14} className="text-slate-600" />
              {activeFile.path}
            </span>
          </div>
          <button onClick={handleDownload} className="flex items-center gap-2 px-4 py-2 bg-white/5 hover:bg-white/10 rounded-xl text-[10px] font-black text-slate-300 uppercase tracking-widest border border-white/5 transition-all">
            <Download size={14} /> EXPORT
          </button>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 relative bg-[#0b0e14]/20">
            <Editor 
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              options={{ minimap: { enabled: false }, fontSize: 14, fontFamily: "'Fira Code', monospace", automaticLayout: true, readOnly: isGenerating && streamingFile === activeFile.path, scrollBeyondLastLine: false, cursorSmoothCaretAnimation: 'on', smoothScrolling: true, padding: { top: 32, bottom: 32 }, scrollbar: { vertical: 'visible', verticalScrollbarSize: 8 }, bracketPairColorization: { enabled: true } }}
              onChange={(val) => { if (!isGenerating) setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f)); }}
            />
          </div>

          <div className="flex-1 bg-white relative">
            <Preview 
              code={debouncedBundledCode} 
              isGenerating={isGenerating} 
              activeLanguage={activeFile.path.endsWith('.py') ? 'python' : 'web'} 
              onDiagnosticUpdate={setLastDiagnostic}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

export enum AIModel {
  GPT_4O = 'gpt-4o',
  CLAUDE_3_5_SONNET = 'claude-3-5-sonnet',
  GEMINI_1_5_PRO = 'gemini-1.5-pro',
}

export interface ModelMetadata {
  id: AIModel;
  name: string;
  status: 'optimal' | 'high-load';
  capability: 'Reasoning' | 'Creative';
  color: string;
}

export const MODEL_LIST: ModelMetadata[] = [
  { id: AIModel.GPT_4O, name: 'GPT-4o', status: 'optimal', capability: 'Reasoning', color: '#10b981' },
  { id: AIModel.CLAUDE_3_5_SONNET, name: 'Claude 3.5', status: 'optimal', capability: 'Creative', color: '#f59e0b' },
  { id: AIModel.GEMINI_1_5_PRO, name: 'Gemini 1.5 Pro', status: 'optimal', capability: 'Reasoning', color: '#8b5cf6' },
];

export interface ChatMessage {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  model?: string;
  timestamp: number;
  isStreaming?: boolean;
  status?: 'analyzing' | 'coding' | 'diagnosing' | 'idle';
  error?: string;
}

export interface FileEntry {
  path: string;
  content: string;
  language: string;
}

export interface DiagnosticReport {
  timestamp: number;
  error?: string;
  logs: string[];
}

declare global {
  interface Window {
    puter: any;
    JSZip: any;
  }
}

import * as React from 'react';
import Editor from '@monaco-editor/react';
import { Preview } from './components/Preview';
import { AIModel, ChatMessage, FileEntry, MODEL_LIST, ModelMetadata, DiagnosticReport } from './types';
import { 
  Code2, 
  MessageSquare, 
  Download, 
  Settings, 
  Zap, 
  FolderTree,
  Send,
  Cpu,
  BrainCircuit,
  Terminal,
  Layers,
  Sparkles,
  Plus,
  Trash2,
  ChevronDown,
  Activity,
  Wand2,
  ShieldAlert,
  Copy,
  Check,
  RefreshCw,
  Search,
  Box
} from 'lucide-react';

const { useState, useEffect, useRef, useMemo, useCallback } = React;

// --- CREATIVE LOGO ---
const VayuLogo = ({ active }: { active: boolean }) => (
  <div className="relative flex items-center justify-center w-10 h-10 group cursor-pointer">
    <svg viewBox="0 0 100 100" className={`w-full h-full transition-all duration-700 ${active ? 'scale-110 rotate-[360deg]' : 'group-hover:scale-110'}`}>
      <defs>
        <linearGradient id="vayuGrad" x1="0%" y1="0%" x2="100%" y2="100%">
          <stop offset="0%" stopColor="#60a5fa" />
          <stop offset="100%" stopColor="#8b5cf6" />
        </linearGradient>
        <filter id="glow"><feGaussianBlur stdDeviation="3" result="blur"/><feMerge><feMergeNode in="blur"/><feMergeNode in="SourceGraphic"/></feMerge></filter>
      </defs>
      <path d="M20 30 L50 80 L80 30" fill="none" stroke="url(#vayuGrad)" strokeWidth="10" strokeLinecap="round" strokeLinejoin="round" filter="url(#glow)" />
      <path d="M40 45 L50 65 L60 45" fill="none" stroke="white" strokeWidth="5" strokeLinecap="round" opacity="0.8" />
      <circle cx="50" cy="80" r="5" fill="#fff" className={active ? 'animate-ping' : ''} />
    </svg>
    {active && <div className="absolute inset-0 bg-blue-500/20 blur-2xl rounded-full animate-pulse" />}
  </div>
);

// --- CHAT CODE BLOCK ---
const ChatCodeBlock: React.FC<{ 
  code: string; 
  language: string; 
  filePath?: string;
  onApply: (path: string, content: string) => void;
  onRefine: (code: string) => void;
  onDebug: (code: string) => void;
}> = ({ code, language, filePath, onApply, onRefine, onDebug }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="group/code relative my-5 rounded-2xl overflow-hidden border border-white/10 bg-black/60 shadow-2xl transition-all hover:border-blue-500/40">
      <div className="flex items-center justify-between px-5 py-3 bg-white/[0.04] border-b border-white/5 backdrop-blur-2xl">
        <div className="flex items-center gap-4">
          <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{language}</div>
          {filePath && <div className="text-[10px] font-bold text-blue-400/80 truncate max-w-[180px] bg-blue-500/10 px-2 py-0.5 rounded border border-blue-500/20">{filePath}</div>}
        </div>
        <div className="flex items-center gap-2 opacity-0 group-hover/code:opacity-100 transition-all duration-300">
          <button onClick={handleCopy} className="p-2 hover:bg-white/10 rounded-xl text-slate-400 transition-all">
            {copied ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
          </button>
          <button onClick={() => onRefine(code)} className="p-2 hover:bg-white/10 rounded-xl text-slate-400 transition-all">
            <RefreshCw size={14} />
          </button>
          <button onClick={() => onDebug(code)} className="p-2 hover:bg-white/10 rounded-xl text-slate-400 transition-all">
            <ShieldAlert size={14} />
          </button>
          {filePath && (
            <button 
              onClick={() => onApply(filePath, code)} 
              className="ml-2 flex items-center gap-2 px-4 py-1.5 bg-blue-600 hover:bg-blue-500 text-white text-[10px] font-black rounded-xl transition-all active:scale-95 shadow-lg shadow-blue-500/20"
            >
              <Zap size={14} className="fill-current" />
              APPLY
            </button>
          )}
        </div>
      </div>
      <div className="p-6 overflow-x-auto custom-scrollbar bg-[#0d1117]/50">
        <pre className="text-[13px] leading-relaxed font-fira text-slate-300 selection:bg-blue-500/30">
          <code>{code}</code>
        </pre>
      </div>
    </div>
  );
};

const INITIAL_FILES: FileEntry[] = [
  {
    path: 'index.html',
    language: 'html',
    content: `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <script src="https://cdn.tailwindcss.com"></script>
  <style>
    body { background: #05070a; color: #f8fafc; font-family: 'Inter', sans-serif; height: 100vh; display: flex; align-items: center; justify-content: center; margin: 0; overflow: hidden; }
    .vayu-card { background: rgba(255, 255, 255, 0.02); backdrop-filter: blur(40px); border: 1px solid rgba(255, 255, 255, 0.05); border-radius: 3rem; padding: 5rem; text-align: center; }
    h1 { font-size: 5rem; font-weight: 900; letter-spacing: -0.05em; background: linear-gradient(to bottom right, #fff, #475569); -webkit-background-clip: text; -webkit-text-fill-color: transparent; }
  </style>
</head>
<body>
  <div class="vayu-card">
    <h1>VAYU OS</h1>
    <p style="color: #64748b; font-weight: 500;">Commanding the Neural Workspace...</p>
  </div>
</body>
</html>`
  }
];

const App: React.FC = () => {
  const [files, setFiles] = useState<FileEntry[]>(INITIAL_FILES);
  const [activeFilePath, setActiveFilePath] = useState<string>('index.html');
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [userInput, setUserInput] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [activeModel, setActiveModel] = useState<AIModel>(AIModel.GPT_4O);
  const [isModelDropdownOpen, setIsModelDropdownOpen] = useState(false);
  const [activeSidebarTab, setActiveSidebarTab] = useState<'chat' | 'files'>('chat');
  const [currentStatus, setCurrentStatus] = useState<'analyzing' | 'coding' | 'diagnosing' | 'idle'>('idle');
  const [terminalLogs, setTerminalLogs] = useState<string[]>(['[SYSTEM] VAYU_KERNEL_LOADED', '[SYSTEM] Neural Bridge Syncing...']);
  const [streamingFile, setStreamingFile] = useState<string | null>(null);
  const [debouncedBundledCode, setDebouncedBundledCode] = useState('');
  const [lastDiagnostic, setLastDiagnostic] = useState<DiagnosticReport | null>(null);

  const chatEndRef = useRef<HTMLDivElement>(null);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const activeFile = useMemo(() => files.find(f => f.path === activeFilePath) || files[0], [files, activeFilePath]);

  const rawBundledCode = useMemo(() => {
    if (activeFile.path.endsWith('.py')) return activeFile.content;
    const htmlFile = files.find(f => f.path === 'index.html');
    let content = htmlFile ? htmlFile.content : `<!DOCTYPE html><html><body><div id="root"></div></body></html>`;
    const styles = files.filter(f => f.path.endsWith('.css')).map(f => `<style data-path="${f.path}">${f.content}</style>`).join('\n');
    const scripts = files.filter(f => f.path.endsWith('.js') || f.path.endsWith('.ts') || f.path.endsWith('.tsx')).map(f => {
      const isReactOrTS = f.path.endsWith('.ts') || f.path.endsWith('.tsx');
      return `<script type="${isReactOrTS ? 'text/babel' : 'module'}" ${isReactOrTS ? 'data-presets="react,typescript"' : ''} data-path="${f.path}">${f.content}</script>`;
    }).join('\n');
    if (content.includes('</head>')) content = content.replace('</head>', `${styles}\n</head>`);
    if (content.includes('</body>')) content = content.replace('</body>', `${scripts}\n</body>`);
    return content;
  }, [files, activeFile]);

  useEffect(() => {
    const handler = setTimeout(() => setDebouncedBundledCode(rawBundledCode), 200); 
    return () => clearTimeout(handler);
  }, [rawBundledCode]);

  useEffect(() => {
    if (chatEndRef.current) chatEndRef.current.scrollIntoView({ behavior: 'smooth' });
  }, [messages, isGenerating]);

  const addLog = (msg: string) => setTerminalLogs(prev => [...prev.slice(-20), `[${new Date().toLocaleTimeString()}] ${msg}`]);

  const applyFileChange = useCallback((path: string, content: string) => {
    setFiles(prev => {
      const idx = prev.findIndex(f => f.path === path);
      if (idx !== -1) {
        const next = [...prev];
        next[idx] = { ...next[idx], content };
        return next;
      }
      return [...prev, { path, content, language: path.split('.').pop() || 'plaintext' }];
    });
    setActiveFilePath(path);
    addLog(`Atomic Synchronized: ${path}`);
  }, []);

  const handleSendMessage = async (forceDiagnostic = false) => {
    const textToProcess = forceDiagnostic ? "NEURAL_DIAGNOSTIC: Fix all errors in the workspace." : userInput;
    if (!textToProcess.trim() || isGenerating) return;

    const userMsg: ChatMessage = { id: Date.now().toString(), role: 'user', content: textToProcess, timestamp: Date.now() };
    setMessages(prev => [...prev, userMsg]);
    setUserInput('');
    setIsGenerating(true);
    setCurrentStatus(forceDiagnostic ? 'diagnosing' : 'analyzing');

    const assistantId = (Date.now() + 1).toString();
    const assistantMsg: ChatMessage = { id: assistantId, role: 'assistant', content: '', model: activeModel, timestamp: Date.now(), isStreaming: true };
    setMessages(prev => [...prev, assistantMsg]);

    try {
      const workspaceContext = files.map(f => `FILE: ${f.path}\nCODE:\n${f.content}`).join('\n\n');
      const diagContext = forceDiagnostic && lastDiagnostic ? `RUNTIME_ERRORS:\n${lastDiagnostic.error}\nLOGS: ${lastDiagnostic.logs.join('\n')}` : '';

      const systemInstruction = `You are VAYU_OS_CORE. A highly advanced, multi-file browser IDE AI.

      CONTEXT:
      ${workspaceContext}

      ${diagContext}

      RULES:
      1. Use [FILE: path] followed by a code block for workspace updates.
      2. For general talk or snippets, use standard markdown.
      3. Focus on Design-driven development (Tailwind, Glassmorphism).
      4. Always be project-aware. If changing a component, check where it is imported.`;

      let fullContent = '';
      const response = await window.puter.ai.chat(systemInstruction, { 
        model: activeModel, 
        stream: true 
      });

      for await (const chunk of response) {
        const text = typeof chunk === 'string' ? chunk : (chunk.text || chunk.message?.content || "");
        if (text) {
          fullContent += text;
          setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, content: fullContent } : m));
          // Intelligent Auto-Parsing (Cursor style)
          const fileRegex = /\[FILE:\s*([a-zA-Z0-9._\-/]+)\]\s*```[a-z]*\n([\s\S]*?)(?:```|$)/g;
          let match;
          while ((match = fileRegex.exec(fullContent)) !== null) {
            const path = match[1].trim();
            const content = match[2].trim();
            if (content.length > 10) { // Avoid partial parsing
               applyFileChange(path, content);
            }
          }
        }
      }
      setMessages(prev => prev.map(m => m.id === assistantId ? { ...m, isStreaming: false, status: 'idle' } : m));
    } catch (err: any) {
      addLog(`SYNTH_FAIL: ${err.message}`);
    } finally {
      setIsGenerating(false);
      setCurrentStatus('idle');
    }
  };

  const renderMessageContent = (msg: ChatMessage) => {
    const parts = msg.content.split(/```/);
    return parts.map((part, i) => {
      if (i % 2 === 0) return <div key={i} className="whitespace-pre-wrap">{part}</div>;

      const lines = part.split('\n');
      const langMatch = lines[0].trim();
      const code = lines.slice(1).join('\n').trim();

      const prevPart = parts[i-1] || "";
      const fileMatch = prevPart.match(/\[FILE:\s*([a-zA-Z0-9._\-/]+)\]/);
      const filePath = fileMatch ? fileMatch[1] : undefined;

      return (
        <ChatCodeBlock 
          key={i} 
          code={code} 
          language={langMatch || 'text'} 
          filePath={filePath}
          onApply={applyFileChange}
          onRefine={(c) => setUserInput(`Refine this snippet:\n\n\`\`\`\n${c}\n\`\`\`\n`)}
          onDebug={(c) => { setUserInput(`Debug this logic:\n\n\`\`\`\n${c}\n\`\`\`\n`); handleSendMessage(); }}
        />
      );
    });
  };

  return (
    <div className="flex h-screen w-full bg-[#05070a] text-slate-200 overflow-hidden font-inter selection:bg-blue-500/30">
      {/* Activity Bar */}
      <div className="w-16 flex flex-col items-center py-8 bg-[#080b10] border-r border-white/5 gap-10 z-50 backdrop-blur-3xl">
        <VayuLogo active={isGenerating} />
        <div className="flex flex-col gap-8">
          <button onClick={() => setActiveSidebarTab('chat')} className={`p-3 rounded-2xl transition-all relative group ${activeSidebarTab === 'chat' ? 'text-blue-400 bg-blue-500/10 shadow-[0_0_30px_rgba(59,130,246,0.1)]' : 'text-slate-600 hover:text-slate-400'}`}>
            <MessageSquare size={22} />
            {activeSidebarTab === 'chat' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-5 bg-blue-500 rounded-l-full shadow-[0_0_15px_#3b82f6]" />}
          </button>
          <button onClick={() => setActiveSidebarTab('files')} className={`p-3 rounded-2xl transition-all relative group ${activeSidebarTab === 'files' ? 'text-blue-400 bg-blue-500/10' : 'text-slate-600 hover:text-slate-400'}`}>
            <FolderTree size={22} />
            {activeSidebarTab === 'files' && <div className="absolute right-0 top-1/2 -translate-y-1/2 w-1 h-5 bg-blue-500 rounded-l-full shadow-[0_0_15px_#3b82f6]" />}
          </button>
        </div>
        <div className="mt-auto flex flex-col gap-8 pb-4">
          <button onClick={() => handleSendMessage(true)} className="p-3 rounded-2xl text-slate-600 hover:text-amber-400 hover:bg-amber-500/10 transition-all" title="Diagnostic Run">
            <ShieldAlert size={22} className={lastDiagnostic?.error ? 'animate-pulse text-rose-500' : ''} />
          </button>
          <button onClick={() => window.location.reload()} className="p-3 rounded-2xl text-slate-600 hover:text-blue-400 transition-all">
            <RefreshCw size={22} />
          </button>
        </div>
      </div>

      {/* Sidebar */}
      <div className="w-[420px] flex flex-col bg-[#0b0e14] border-r border-white/5 overflow-hidden">
        <div className="h-16 px-6 border-b border-white/5 flex items-center justify-between bg-[#0b0e14]/50 backdrop-blur-xl">
          <span className="text-[10px] font-black uppercase tracking-[0.4em] text-slate-500 flex items-center gap-2">
            {activeSidebarTab === 'chat' ? <BrainCircuit size={14} className="text-blue-500" /> : <Layers size={14} className="text-indigo-500" />}
            {activeSidebarTab === 'chat' ? 'Neural Link' : 'Workspace'}
          </span>
          {activeSidebarTab === 'chat' && (
            <div className="relative" ref={dropdownRef}>
              <button onClick={() => setIsModelDropdownOpen(!isModelDropdownOpen)} className="flex items-center gap-3 bg-white/[0.04] border border-white/10 hover:border-white/20 transition-all rounded-xl px-4 py-2 text-[10px] font-bold text-slate-300">
                <div className="w-2 h-2 rounded-full" style={{ backgroundColor: MODEL_LIST.find(m => m.id === activeModel)?.color }}></div>
                {MODEL_LIST.find(m => m.id === activeModel)?.name}
                <ChevronDown size={14} className={`transition-transform duration-300 ${isModelDropdownOpen ? 'rotate-180' : ''}`} />
              </button>
              {isModelDropdownOpen && (
                <div className="absolute right-0 mt-3 w-64 bg-[#121820]/95 backdrop-blur-3xl border border-white/10 rounded-2xl shadow-2xl z-[100] overflow-hidden animate-in fade-in slide-in-from-top-2">
                  {MODEL_LIST.map((m) => (
                    <button key={m.id} onClick={() => { setActiveModel(m.id); setIsModelDropdownOpen(false); }} className={`w-full flex flex-col gap-1 px-5 py-4 text-left hover:bg-white/5 transition-all border-l-2 ${activeModel === m.id ? 'bg-blue-500/5 border-blue-500' : 'border-transparent'}`}>
                      <div className="flex items-center justify-between w-full">
                        <span className="text-[12px] font-bold text-slate-100">{m.name}</span>
                        <span className={`text-[8px] px-2 py-0.5 rounded-full uppercase font-black ${m.status === 'optimal' ? 'text-emerald-400 bg-emerald-500/10' : 'text-amber-400 bg-amber-500/10'}`}>{m.status}</span>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          )}
        </div>

        <div className="flex-1 flex flex-col overflow-hidden relative">
          {activeSidebarTab === 'chat' ? (
            <>
              <div className="flex-1 overflow-y-auto p-6 space-y-8 custom-scrollbar pb-44">
                {messages.length === 0 && (
                  <div className="h-full flex flex-col items-center justify-center text-center px-10 py-20">
                    <div className="w-24 h-24 bg-blue-500/5 rounded-3xl flex items-center justify-center mb-8 border border-white/5 shadow-inner">
                      <Sparkles size={32} className="text-blue-500/30" />
                    </div>
                    <h3 className="text-lg font-bold text-slate-200 mb-3 tracking-tight">Vayu Neural Interface</h3>
                    <p className="text-xs text-slate-500 font-medium leading-relaxed">Command the engine to manifest your design architecture. Cursor-grade synthesis active.</p>
                  </div>
                )}
                {messages.map(msg => (
                  <div key={msg.id} className={`flex flex-col gap-2 ${msg.role === 'user' ? 'items-end' : 'items-start animate-in fade-in slide-in-from-bottom-3 duration-500'}`}>
                    <div className={`max-w-[98%] p-6 rounded-3xl text-[13px] border transition-all ${msg.role === 'user' ? 'bg-blue-600 text-white border-blue-400/30 shadow-2xl shadow-blue-500/20' : 'bg-white/[0.02] text-slate-200 border-white/5 backdrop-blur-md'}`}>
                      {renderMessageContent(msg)}
                    </div>
                  </div>
                ))}
                <div ref={chatEndRef} />
              </div>
              <div className="absolute bottom-0 left-0 right-0 p-6 bg-gradient-to-t from-[#0b0e14] via-[#0b0e14] to-transparent z-10">
                <div className="bg-[#161b24]/80 backdrop-blur-3xl border border-white/10 rounded-2xl p-5 shadow-[0_25px_50px_-12px_rgba(0,0,0,0.5)] focus-within:border-blue-500/40 transition-all">
                  <textarea value={userInput} onChange={(e) => setUserInput(e.target.value)} onKeyDown={(e) => { if(e.key === 'Enter' && !e.shiftKey) { e.preventDefault(); handleSendMessage(); } }} placeholder="Describe your synthesis intent..." className="w-full bg-transparent outline-none resize-none text-[13px] min-h-[50px] max-h-[160px] placeholder:text-slate-600 font-medium custom-scrollbar leading-relaxed" />
                  <div className="flex justify-between items-center mt-4 pt-4 border-t border-white/5">
                    <div className="flex items-center gap-3 text-[9px] text-slate-500 font-black uppercase tracking-[0.3em]">
                      <Activity size={12} className={isGenerating ? 'animate-spin text-blue-500' : 'text-slate-700'} />
                      {currentStatus}
                    </div>
                    <button onClick={() => handleSendMessage()} disabled={isGenerating || !userInput.trim()} className="p-3 bg-blue-600 hover:bg-blue-500 disabled:opacity-20 rounded-xl transition-all shadow-xl active:scale-95 text-white"><Send size={18} /></button>
                  </div>
                </div>
              </div>
            </>
          ) : (
            <div className="flex flex-col h-full">
              <div className="p-5 flex justify-between items-center border-b border-white/5 bg-white/[0.01]">
                <span className="text-[10px] font-black uppercase tracking-[0.3em] text-slate-500">Workspace Manifest</span>
                <button onClick={() => {
                  const name = window.prompt("Synthesis Object Identifier:");
                  if (name) applyFileChange(name, "");
                }} className="p-2 bg-white/5 hover:bg-white/10 rounded-xl text-slate-400 border border-white/5 transition-all"><Plus size={16} /></button>
              </div>
              <div className="flex-1 p-5 space-y-3 overflow-y-auto custom-scrollbar">
                {files.map(file => (
                  <div key={file.path} className="group relative">
                    <button onClick={() => setActiveFilePath(file.path)} className={`w-full flex items-center gap-4 px-5 py-4 rounded-2xl text-xs transition-all border ${activeFilePath === file.path ? 'bg-blue-500/10 border-blue-500/30 text-blue-400' : 'border-transparent text-slate-500 hover:bg-white/5'}`}>
                      <Code2 size={18} className={activeFilePath === file.path ? 'text-blue-400' : 'text-slate-700'} />
                      <span className="flex-1 text-left truncate font-bold tracking-tight">{file.path}</span>
                    </button>
                    <button onClick={(e) => { e.stopPropagation(); setFiles(f => f.filter(fi => fi.path !== file.path)); }} className="absolute right-4 top-1/2 -translate-y-1/2 p-2 opacity-0 group-hover:opacity-100 hover:text-rose-500 transition-all text-slate-700 bg-[#0b0e14] rounded-lg shadow-lg"><Trash2 size={16} /></button>
                  </div>
                ))}
              </div>
              <div className="h-48 bg-black/60 border-t border-white/5 p-6 font-mono text-[11px] text-slate-500 flex flex-col gap-2 overflow-y-auto custom-scrollbar">
                <div className="flex items-center gap-3 mb-2 text-slate-600 font-bold uppercase tracking-[0.2em] border-b border-white/5 pb-2">
                  <Terminal size={14} /> KERNEL_LOGS
                </div>
                {terminalLogs.map((log, i) => (
                  <div key={i} className="flex gap-4 hover:bg-white/5 px-1 py-0.5 rounded transition-colors group">
                    <span className="text-slate-800 font-bold select-none group-hover:text-slate-700">{(i+1).toString().padStart(2,'0')}</span>
                    <span className="leading-relaxed">{log}</span>
                  </div>
                ))}
              </div>
            </div>
          )}
        </div>
      </div>

      {/* Editor & Preview */}
      <div className="flex-1 flex flex-col min-w-0 bg-[#05070a] relative">
        <div className="h-16 px-8 flex items-center justify-between bg-[#0b0e14]/50 border-b border-white/5 backdrop-blur-3xl z-20">
          <div className="flex items-center gap-6">
            <div className="px-3 py-1.5 bg-white/5 rounded-xl border border-white/10 shadow-inner">
              <span className="text-[10px] font-black text-blue-500 uppercase tracking-[0.4em]">{activeFile.language}</span>
            </div>
            <span className="text-[13px] font-bold text-slate-300 flex items-center gap-4">
              <div className="w-1 h-3 bg-blue-500/50 rounded-full" />
              {activeFile.path}
            </span>
          </div>
          <div className="flex items-center gap-4">
             <div className="flex items-center gap-3 text-[10px] font-black text-slate-600 uppercase tracking-[0.3em] px-5 py-2.5 bg-white/[0.02] border border-white/5 rounded-full shadow-inner">
               <div className="w-2 h-2 rounded-full bg-emerald-500 shadow-[0_0_12px_#10b981] animate-pulse"></div>
               SYNTH_NODE_V3.8
             </div>
          </div>
        </div>

        <div className="flex-1 flex overflow-hidden">
          <div className="flex-1 border-r border-white/5 relative bg-[#0b0e14]/40">
            <Editor 
              height="100%"
              path={activeFile.path}
              language={activeFile.language}
              theme="vs-dark"
              value={activeFile.content}
              options={{ minimap: { enabled: false }, fontSize: 14, fontFamily: "'Fira Code', monospace", automaticLayout: true, readOnly: isGenerating && streamingFile === activeFile.path, scrollBeyondLastLine: false, cursorSmoothCaretAnimation: 'on', smoothScrolling: true, padding: { top: 32, bottom: 32 }, scrollbar: { vertical: 'visible', verticalScrollbarSize: 8 }, bracketPairColorization: { enabled: true } }}
              onChange={(val) => { if (!isGenerating) setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f)); }}
            />
          </div>

          <div className="flex-1 bg-white relative">
            <Preview 
              code={debouncedBundledCode} 
              isGenerating={isGenerating} 
              activeLanguage={activeFile.path.endsWith('.py') ? 'python' : 'web'} 
              onDiagnosticUpdate={setLastDiagnostic}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

export default App;

