// --- ATOMIC CODE BLOCK COMPONENT ---
const ChatCodeBlock: React.FC<{ 
  code: string; 
  language: string; 
  filePath?: string;
  onApply: (path: string, content: string) => void;
  onRefine: (code: string) => void;
  onDebug: (code: string) => void;
}> = ({ code, language, filePath, onApply, onRefine, onDebug }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="group/code relative my-6 rounded-2xl overflow-hidden border border-white/10 bg-[#0d1117]/80 shadow-2xl transition-all hover:border-blue-500/40">
      <div className="flex items-center justify-between px-5 py-3 bg-white/[0.03] border-b border-white/5 backdrop-blur-2xl">
        <div className="flex items-center gap-4">
          <div className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">{language}</div>
          {filePath && (
            <div className="text-[10px] font-bold text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded border border-blue-500/20 truncate max-w-[200px]">
              {filePath}
            </div>
          )}
        </div>
        <div className="flex items-center gap-1.5 opacity-0 group-hover/code:opacity-100 transition-all duration-300">
          <button onClick={handleCopy} title="Copy Code" className="p-2 hover:bg-white/10 rounded-xl text-slate-400 transition-all">
            {copied ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
          </button>
          <button onClick={() => onRefine(code)} title="Refine Logic" className="p-2 hover:bg-white/10 rounded-xl text-slate-400 transition-all">
            <RefreshCw size={14} />
          </button>
          <button onClick={() => onDebug(code)} title="Diagnostic Trace" className="p-2 hover:bg-white/10 rounded-xl text-slate-400 transition-all">
            <ShieldAlert size={14} />
          </button>
          {filePath && (
            <button 
              onClick={() => onApply(filePath, code)} 
              className="ml-2 flex items-center gap-2 px-4 py-2 bg-blue-600 hover:bg-blue-500 text-white text-[10px] font-black rounded-xl transition-all active:scale-95 shadow-lg shadow-blue-500/30"
            >
              <Zap size={14} className="fill-current" />
              APPLY
            </button>
          )}
        </div>
      </div>
      <div className="p-6 overflow-x-auto custom-scrollbar bg-black/20">
        <pre className="text-[13px] leading-relaxed font-fira text-slate-300 selection:bg-blue-500/30">
          <code>{code}</code>
        </pre>
      </div>
    </div>
  );
};

const INITIAL_FILES: FileEntry[] = [
  {
