import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Maximize2, Loader2, Zap, RefreshCw, Activity, ShieldCheck, Cpu, Terminal } from 'lucide-react';
import { DiagnosticReport } from '../types';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
  activeLanguage: 'web' | 'python';
  onDiagnosticUpdate: (report: DiagnosticReport) => void;
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating, activeLanguage, onDiagnosticUpdate }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pythonOutput, setPythonOutput] = useState<string[]>([]);
  const [pyodide, setPyodide] = useState<any>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [runtimeStatus, setRuntimeStatus] = useState<'idle' | 'running' | 'error'>('idle');
  const [errorLogs, setErrorLogs] = useState<string[]>([]);

  useEffect(() => {
    if (activeLanguage === 'python' && !pyodide && (window as any).loadPyodide) {
      (window as any).loadPyodide().then((res: any) => setPyodide(res));
    }
  }, [activeLanguage, pyodide]);

  const runCode = useCallback(async () => {
    if (!code) return;
    setRuntimeStatus('running');
    setErrorLogs([]);

    if (activeLanguage === 'web') {
      if (iframeRef.current) {
        // Setup console capture
        const captureScript = `
          <script>
            (function() {
              const originalLog = console.log;
              const originalError = console.error;
              console.log = function(...args) {
                window.parent.postMessage({ type: 'LOG', content: args.join(' ') }, '*');
                originalLog.apply(console, args);
              };
              console.error = function(...args) {
                window.parent.postMessage({ type: 'ERROR', content: args.join(' ') }, '*');
                originalError.apply(console, args);
              };
              window.onerror = function(msg, url, line, col, error) {
                window.parent.postMessage({ type: 'ERROR', content: msg + ' (Line: ' + line + ')' }, '*');
                return false;
              };
            })();
          </script>
        `;

        iframeRef.current.srcdoc = captureScript + code;
        setRuntimeStatus('idle');
      }
    } else if (activeLanguage === 'python' && pyodide) {
      setPythonOutput(['>>> Executing Neural Trace...']);
      try {
        pyodide.setStdout({ batched: (text: string) => setPythonOutput(prev => [...prev, text]) });
        pyodide.setStderr({ batched: (text: string) => {
          setPythonOutput(prev => [...prev, `[ERR] ${text}`]);
          setErrorLogs(prev => [...prev, text]);
          setRuntimeStatus('error');
        }});
        await pyodide.runPythonAsync(code);
        setRuntimeStatus('idle');
      } catch (err: any) {
        setPythonOutput(prev => [...prev, `[CRITICAL] ${err.message}`]);
        setErrorLogs(prev => [...prev, err.message]);
        setRuntimeStatus('error');
      }
    }
  }, [code, activeLanguage, pyodide]);

  useEffect(() => {
    const handleMessage = (e: MessageEvent) => {
      if (e.data.type === 'ERROR') {
        setErrorLogs(prev => [...prev, e.data.content]);
        setRuntimeStatus('error');
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  useEffect(() => {
    if (errorLogs.length > 0 || runtimeStatus === 'error') {
      onDiagnosticUpdate({
        timestamp: Date.now(),
        error: errorLogs[errorLogs.length - 1],
        logs: errorLogs
      });
    }
  }, [errorLogs, runtimeStatus, onDiagnosticUpdate]);

  useEffect(() => {
    if (isGenerating) return;
    runCode();
  }, [code, isGenerating, refreshKey, runCode]);

  const toggleFullscreen = () => {
    if (!containerRef.current) return;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      containerRef.current.requestFullscreen();
    }
  };

  return (
    <div ref={containerRef} className="w-full h-full bg-[#05070a] relative flex flex-col group overflow-hidden">
      {/* HUD Controls */}
      <div className="absolute top-6 right-8 z-50 flex items-center gap-4 opacity-0 group-hover:opacity-100 transition-all duration-700 translate-y-3 group-hover:translate-y-0">
        <div className={`flex items-center gap-3 px-4 py-2 bg-black/60 backdrop-blur-2xl border border-white/10 rounded-2xl shadow-2xl`}>
           <div className={`w-2 h-2 rounded-full ${runtimeStatus === 'running' ? 'bg-blue-500 animate-pulse' : runtimeStatus === 'error' ? 'bg-rose-500 shadow-[0_0_10px_#f43f5e]' : 'bg-emerald-500 shadow-[0_0_8px_#10b981]'}`} />
           <span className="text-[10px] font-black uppercase text-slate-300 tracking-[0.2em]">{runtimeStatus === 'error' ? 'CRITICAL_FAULT' : 'RUNTIME_STABLE'}</span>
        </div>
        <button onClick={() => setRefreshKey(k => k + 1)} className="p-3 bg-white/5 backdrop-blur-3xl text-white rounded-2xl border border-white/10 shadow-2xl hover:bg-white/10 transition-all active:scale-90">
          <RefreshCw size={16} className={runtimeStatus === 'running' ? 'animate-spin' : ''} />
        </button>
        <button onClick={toggleFullscreen} className="p-3 bg-white/5 backdrop-blur-3xl text-white rounded-2xl border border-white/10 shadow-2xl hover:bg-white/10 transition-all active:scale-90">
          <Maximize2 size={16} />
        </button>
      </div>

      <div className="flex-1 relative overflow-hidden">
        {activeLanguage === 'web' ? (
          <iframe 
            ref={iframeRef} 
            title="Vayu Web Preview" 
            className={`w-full h-full border-none bg-white transition-all duration-1000 ${isGenerating ? 'opacity-20 grayscale blur-xl pointer-events-none' : 'opacity-100'}`} 
            sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin" 
          />
        ) : (
          <div className="w-full h-full bg-[#05070a] p-16 font-mono text-[14px] overflow-auto text-slate-300 custom-scrollbar">
             <div className="flex items-center justify-between mb-10 pb-5 border-b border-white/10">
                <div className="flex items-center gap-4">
                  <Cpu size={20} className="text-emerald-500" />
                  <span className="text-[12px] font-black uppercase tracking-[0.3em] text-slate-100">Neural Logic VM</span>
                </div>
                {runtimeStatus === 'error' && <div className="flex items-center gap-2 text-rose-500 font-bold text-[10px] uppercase tracking-widest bg-rose-500/10 px-3 py-1.5 rounded-full border border-rose-500/20"><Activity size={12} /> Fault_Detected</div>}
             </div>

             <div className="space-y-4">
               {pythonOutput.map((line, i) => (
                 <div key={i} className={`flex gap-6 leading-relaxed ${line.includes('[ERR]') || line.includes('[CRITICAL]') ? 'text-rose-400 bg-rose-500/5 px-4 py-3 rounded-xl border border-rose-500/20' : 'text-slate-300'}`}>
                   <span className="opacity-20 font-black select-none text-[10px] pt-1">{(i+1).toString().padStart(2, '0')}</span>
                   <span className="font-medium whitespace-pre-wrap">{line}</span>
                 </div>
               ))}
             </div>

             {!pyodide && activeLanguage === 'python' && (
               <div className="absolute inset-0 flex flex-col items-center justify-center gap-6 bg-[#05070a]">
                 <Loader2 size={40} className="animate-spin text-blue-500/50" />
                 <span className="text-[10px] font-black uppercase tracking-[0.5em] text-slate-600">Hydrating Virtual VM</span>
               </div>
             )}
          </div>
        )}

        {isGenerating && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#05070a]/90 backdrop-blur-3xl z-[60] transition-all duration-1000">
            <div className="relative mb-12 flex items-center justify-center">
              <div className="w-32 h-32 border border-blue-500/10 rounded-full animate-[spin_10s_linear_infinite]" />
              <div className="w-24 h-24 border border-blue-400/20 rounded-full absolute animate-[spin_6s_linear_infinite_reverse]" />
              <Zap size={40} className="absolute text-blue-500 fill-blue-500 shadow-[0_0_30px_#3b82f6] animate-pulse" />
            </div>
            <p className="text-[14px] font-black uppercase tracking-[0.8em] text-blue-500 animate-pulse">Synthesis Active</p>
          </div>
        )}
      </div>
    </div>
  );
};

