                fontFamily: "'Fira Code', monospace", 
                automaticLayout: true, 
                readOnly: isGenerating && streamingFile === activeFile.path, 
                scrollBeyondLastLine: false, 
                cursorSmoothCaretAnimation: 'on', 
                smoothScrolling: true, 
                padding: { top: 32, bottom: 32 }, 
                scrollbar: { vertical: 'visible', verticalScrollbarSize: 8 }, 
                bracketPairColorization: { enabled: true },
                lineNumbers: 'on',
                renderLineHighlight: 'all',
                fixedOverflowWidgets: true
              }}
              onChange={(val) => { if (!isGenerating) setFiles(prev => prev.map(f => f.path === activeFile.path ? { ...f, content: val || '' } : f)); }}
            />
            {isGenerating && streamingFile === activeFile.path && (
              <div className="absolute top-6 right-10 z-30 flex items-center gap-3 text-[10px] font-black text-blue-500 bg-blue-500/10 border border-blue-500/20 px-5 py-2.5 rounded-full backdrop-blur-3xl animate-pulse shadow-2xl">
                <Zap size={12} className="fill-current" />
                NEURAL_PATCHING_WORKSPACE...
              </div>
            )}
          </div>

          {/* REALTIME PREVIEW */}
          <div className="flex-1 bg-white relative">
            <Preview 
              code={debouncedBundledCode} 
              isGenerating={isGenerating} 
              activeLanguage={activeFile.path.endsWith('.py') ? 'python' : 'web'} 
              onDiagnosticUpdate={setLastDiagnostic}
            />
          </div>
        </div>
      </div>
    </div>
  );
};

