// --- ATOMIC CODE BLOCK ---
const ChatCodeBlock: React.FC<{ 
  code: string; 
  language: string; 
  filePath?: string;
  onApply: (path: string, content: string) => void;
  onRefine: (code: string) => void;
}> = ({ code, language, filePath, onApply, onRefine }) => {
  const [copied, setCopied] = useState(false);

  const handleCopy = () => {
    navigator.clipboard.writeText(code);
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  return (
    <div className="group/code relative my-4 rounded-xl overflow-hidden border border-white/10 bg-[#0d1117]/60 shadow-xl transition-all hover:border-blue-500/30">
      <div className="flex items-center justify-between px-4 py-2 bg-white/[0.03] border-b border-white/5 backdrop-blur-md">
        <div className="flex items-center gap-3">
          <div className="text-[10px] font-black text-slate-500 uppercase tracking-widest">{language}</div>
          {filePath && <div className="text-[10px] font-bold text-blue-400 bg-blue-500/10 px-2 py-0.5 rounded border border-blue-500/20 truncate max-w-[150px]">{filePath}</div>}
        </div>
        <div className="flex items-center gap-1.5 opacity-0 group-hover/code:opacity-100 transition-opacity">
          <button onClick={handleCopy} className="p-1.5 hover:bg-white/10 rounded-lg text-slate-400 transition-colors">
            {copied ? <Check size={14} className="text-emerald-500" /> : <Copy size={14} />}
          </button>
          <button onClick={() => onRefine(code)} className="p-1.5 hover:bg-white/10 rounded-lg text-slate-400 transition-colors">
            <RefreshCw size={14} />
          </button>
          {filePath && (
            <button 
              onClick={() => onApply(filePath, code)} 
              className="ml-1 flex items-center gap-1.5 px-3 py-1 bg-blue-600 hover:bg-blue-500 text-white text-[10px] font-black rounded-lg transition-all active:scale-95 shadow-lg shadow-blue-500/20"
            >
              <Zap size={12} className="fill-current" />
              APPLY
            </button>
          )}
        </div>
      </div>
      <div className="p-4 overflow-x-auto custom-scrollbar bg-black/20">
        <pre className="text-[12px] leading-relaxed font-fira text-slate-300"><code>{code}</code></pre>
      </div>
    </div>
  );
};

const INITIAL_FILES: FileEntry[] = [
  {
