import React, { useEffect, useRef, useState, useCallback } from 'react';
import { Maximize2, Loader2, Zap, RefreshCw, Activity, ShieldCheck, Cpu, Terminal, X, ChevronUp, ChevronDown, MonitorPlay } from 'lucide-react';
import { DiagnosticReport } from '../types';

interface PreviewProps {
  code: string;
  isGenerating: boolean;
  activeLanguage: 'web' | 'python';
  onDiagnosticUpdate: (report: DiagnosticReport) => void;
}

export const Preview: React.FC<PreviewProps> = ({ code, isGenerating, activeLanguage, onDiagnosticUpdate }) => {
  const iframeRef = useRef<HTMLIFrameElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);
  const [pythonOutput, setPythonOutput] = useState<string[]>([]);
  const [webLogs, setWebLogs] = useState<{type: 'LOG' | 'ERROR', content: string}[]>([]);
  const [pyodide, setPyodide] = useState<any>(null);
  const [refreshKey, setRefreshKey] = useState(0);
  const [runtimeStatus, setRuntimeStatus] = useState<'idle' | 'running' | 'error'>('idle');
  const [showConsole, setShowConsole] = useState(false);

  useEffect(() => {
    if (activeLanguage === 'python' && !pyodide && (window as any).loadPyodide) {
      (window as any).loadPyodide().then((res: any) => setPyodide(res));
    }
  }, [activeLanguage, pyodide]);

  const runCode = useCallback(async () => {
    if (!code) return;
    setRuntimeStatus('running');

    if (activeLanguage === 'web') {
      if (iframeRef.current) {
        const captureScript = `
          <script>
            (function() {
              const originalLog = console.log;
              const originalError = console.error;
              console.log = function(...args) {
                window.parent.postMessage({ type: 'LOG', content: args.join(' ') }, '*');
                originalLog.apply(console, args);
              };
              console.error = function(...args) {
                window.parent.postMessage({ type: 'ERROR', content: args.join(' ') }, '*');
                originalError.apply(console, args);
              };
              window.onerror = function(msg, url, line, col, error) {
                window.parent.postMessage({ type: 'ERROR', content: msg + ' (Line: ' + line + ')' }, '*');
                return false;
              };
            })();
          </script>
        `;
        // Inject script + code into srcdoc for isolated execution
        iframeRef.current.srcdoc = captureScript + code;
        setRuntimeStatus('idle');
      }
    } else if (activeLanguage === 'python' && pyodide) {
      setPythonOutput(['>>> Trace Init...']);
      try {
        pyodide.setStdout({ batched: (text: string) => setPythonOutput(prev => [...prev, text]) });
        pyodide.setStderr({ batched: (text: string) => {
          setPythonOutput(prev => [...prev, `[ERR] ${text}`]);
          setRuntimeStatus('error');
        }});
        await pyodide.runPythonAsync(code);
        setRuntimeStatus('idle');
      } catch (err: any) {
        setPythonOutput(prev => [...prev, `[CRITICAL] ${err.message}`]);
        setRuntimeStatus('error');
      }
    }
  }, [code, activeLanguage, pyodide]);

  useEffect(() => {
    const handleMessage = (e: MessageEvent) => {
      if (e.data.type === 'LOG' || e.data.type === 'ERROR') {
        setWebLogs(prev => [...prev.slice(-49), e.data]);
        if (e.data.type === 'ERROR') setRuntimeStatus('error');
      }
    };
    window.addEventListener('message', handleMessage);
    return () => window.removeEventListener('message', handleMessage);
  }, []);

  useEffect(() => {
    const errorLogs = webLogs.filter(l => l.type === 'ERROR').map(l => l.content);
    if (errorLogs.length > 0) {
      onDiagnosticUpdate({
        timestamp: Date.now(),
        error: errorLogs[errorLogs.length - 1],
        logs: errorLogs
      });
    }
  }, [webLogs, onDiagnosticUpdate]);

  // Reactive auto-run when code changes
  useEffect(() => {
    runCode();
  }, [code, refreshKey, runCode]);

  const toggleFullscreen = () => {
    if (!containerRef.current) return;
    if (document.fullscreenElement) {
      document.exitFullscreen();
    } else {
      containerRef.current.requestFullscreen();
    }
  };

  return (
    <div ref={containerRef} className="w-full h-full bg-[#f8fafc] relative flex flex-col group overflow-hidden">
      {/* Viewport HUD */}
      <div className="absolute top-6 right-8 z-[50] flex items-center gap-3 opacity-0 group-hover:opacity-100 transition-all duration-500 translate-y-3 group-hover:translate-y-0">
        <div className="flex items-center gap-3 px-4 py-2 bg-[#0b0e14]/90 backdrop-blur-3xl border border-white/10 rounded-2xl shadow-2xl">
           <div className={`w-1.5 h-1.5 rounded-full ${runtimeStatus === 'error' ? 'bg-rose-500 shadow-[0_0_10px_#f43f5e]' : 'bg-emerald-500 shadow-[0_0_10px_#10b981]'}`} />
           <span className="text-[9px] font-black uppercase text-slate-300 tracking-widest">{runtimeStatus === 'error' ? 'Fault_Detected' : 'System_Ready'}</span>
        </div>

        <button onClick={() => setRefreshKey(k => k + 1)} className="p-2.5 bg-white shadow-xl text-slate-700 rounded-xl border border-slate-200 hover:bg-slate-50 transition-all active:scale-90" title="Force Reload">
          <RefreshCw size={14} className={runtimeStatus === 'running' ? 'animate-spin' : ''} />
        </button>

        <button onClick={() => setShowConsole(!showConsole)} className={`p-2.5 shadow-xl rounded-xl border transition-all active:scale-90 ${showConsole ? 'bg-blue-600 text-white border-blue-500' : 'bg-white text-slate-700 border-slate-200 hover:bg-slate-50'}`} title="Toggle Debug Console">
          <Terminal size={14} />
        </button>

        <button onClick={toggleFullscreen} className="p-2.5 bg-white shadow-xl text-slate-700 rounded-xl border border-slate-200 hover:bg-slate-50 transition-all active:scale-90" title="Fullscreen Preview">
          <Maximize2 size={14} />
        </button>
      </div>

      {/* Synthesis Active Pulse */}
      {isGenerating && (
        <div className="absolute top-6 left-8 z-[50] animate-in slide-in-from-left-4 fade-in duration-500">
           <div className="flex items-center gap-3 px-4 py-2 bg-blue-600 text-white rounded-2xl shadow-2xl shadow-blue-500/20">
             <MonitorPlay size={14} className="animate-pulse" />
             <span className="text-[10px] font-black uppercase tracking-widest">Synthesis Sync Active</span>
           </div>
        </div>
      )}

      <div className="flex-1 relative overflow-hidden flex flex-col">
        {activeLanguage === 'web' ? (
          <div className="flex-1 relative">
            <iframe 
              ref={iframeRef} 
              title="Vayu Web Preview" 
              className={`w-full h-full border-none transition-all duration-700 bg-white`} 
              sandbox="allow-scripts allow-forms allow-modals allow-popups allow-same-origin" 
            />
          </div>
        ) : (
          <div className="flex-1 bg-[#05070a] p-12 font-mono text-[13px] overflow-auto text-slate-300 custom-scrollbar">
             <div className="flex items-center gap-3 mb-8 opacity-40">
                <Cpu size={18} />
                <span className="text-[10px] font-black uppercase tracking-widest">Logic VM Active</span>
             </div>
             <div className="space-y-3">
               {pythonOutput.map((line, i) => (
                 <div key={i} className={`flex gap-5 ${line.includes('[ERR]') ? 'text-rose-400' : 'text-slate-300'}`}>
                   <span className="opacity-10 text-[9px] w-4">{i+1}</span>
                   <span className="font-medium whitespace-pre-wrap">{line}</span>
                 </div>
               ))}
             </div>
             {!pyodide && <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#05070a]"><Loader2 size={32} className="animate-spin text-blue-500/20" /></div>}
          </div>
        )}

        {/* Console Overlay (Retractable) */}
        <div className={`absolute bottom-0 left-0 right-0 bg-[#0b0e14]/98 backdrop-blur-3xl border-t border-white/10 transition-transform duration-500 z-40 h-72 overflow-hidden flex flex-col shadow-[0_-20px_50px_rgba(0,0,0,0.5)] ${showConsole ? 'translate-y-0' : 'translate-y-full'}`}>
           <div className="px-6 py-4 border-b border-white/5 flex items-center justify-between bg-black/30">
              <span className="text-[10px] font-black uppercase tracking-[0.2em] text-slate-400 flex items-center gap-2"><Terminal size={14} className="text-blue-500" /> System Runtime Logs</span>
              <div className="flex items-center gap-4">
                <button onClick={() => setWebLogs([])} className="text-[9px] font-bold text-slate-500 hover:text-white uppercase">Clear Logs</button>
                <button onClick={() => setShowConsole(false)} className="text-slate-500 hover:text-white transition-colors"><X size={16} /></button>
              </div>
           </div>
           <div className="flex-1 overflow-y-auto p-6 font-mono text-[12px] space-y-2 custom-scrollbar">
              {webLogs.length === 0 && <div className="text-slate-700 italic py-4 text-center">Kernel observing runtime for output...</div>}
              {webLogs.map((log, i) => (
                <div key={i} className={`flex gap-4 p-3 rounded-xl ${log.type === 'ERROR' ? 'bg-rose-500/10 text-rose-400 border border-rose-500/10' : 'bg-white/5 text-slate-300 border border-white/5'}`}>
                   <span className="opacity-20 text-[10px] font-bold">{new Date().toLocaleTimeString()}</span>
                   <span className="whitespace-pre-wrap">{log.content}</span>
                </div>
              ))}
           </div>
        </div>

        {/* Global Loading state when Synthesis starts */}
        {isGenerating && messages.length > 0 && messages[messages.length-1].content === '' && (
          <div className="absolute inset-0 flex flex-col items-center justify-center bg-[#05070a]/60 backdrop-blur-3xl z-[60] transition-all duration-1000">
            <div className="relative mb-8 flex items-center justify-center">
              <div className="w-24 h-24 border border-blue-500/20 rounded-full animate-[spin_4s_linear_infinite]" />
              <Zap size={32} className="absolute text-blue-500 fill-blue-500/20 animate-pulse" />
            </div>
            <p className="text-[11px] font-black uppercase tracking-[0.5em] text-blue-400/80 animate-pulse">Synthesis Hub Synchronizing</p>
          </div>
        )}
      </div>
    </div>
  );
};

